cp7_sku_conversion.cost_root_v3(uuid):
CREATE OR REPLACE FUNCTION cp7_sku_conversion.cost_root_v3(p_lot uuid)
 RETURNS TABLE(root_lot_id uuid, po_id uuid, hpp_version_id uuid, unit_value numeric, source_revision jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;n integer;
begin
 select count(*)into n from erp.product_conversion_allocations a where a.destination_lot_id=p_lot;
 if n<>1 then raise exception 'CP7_SKU_COST_ROOT_ALLOCATION_NOT_UNIQUE';end if;
 select a.*,c.status conversion_status,l.po_id,h.id version_id,h.cost_state,
  erp.be_allocation_extra_v1(a.id)extra
 into strict r from erp.product_conversion_allocations a
 join erp.product_conversions c on c.id=a.conversion_id
 join erp.fg_lots l on l.id=a.destination_lot_id
 left join erp.hpp_versions h on h.lot_id=l.id and h.is_current where a.destination_lot_id=p_lot;
 if r.qty_pcs<=0 or r.extra is null or r.extra::text in('NaN','Infinity','-Infinity')
  or r.version_id is null or r.cost_state='ESTIMATED' or r.conversion_status not in('POSTED','REVERSED')
  or erp.bd_lot_laundry_unknown_v1(p_lot)
  or(r.po_id is not null and not exists(select 1 from erp.get_hpp_completeness(r.po_id)c where c.pending_reason_count=0))then
  raise exception 'CP7_SKU_POOL_HPP_UNKNOWN: seluruh komponen ekonomi termasuk reservasi harus diketahui';end if;
 return query select p_lot,r.po_id,r.version_id,(r.extra/r.qty_pcs)::numeric,
  jsonb_build_object('allocation',to_jsonb(r),'sources',(select coalesce(jsonb_agg(to_jsonb(s)order by s.document_id),'[]')
   from erp.be_conversion_cost_sources_v1 s where s.conversion_id=r.conversion_id),
   'events',(select coalesce(jsonb_agg(to_jsonb(e)order by e.id),'[]')from erp.be_conversion_cost_events_v1 e
    join erp.be_conversion_cost_sources_v1 s on s.document_id=e.document_id where s.conversion_id=r.conversion_id));
end $function$

cp7_sku_conversion.assert_group_inverse_:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.assert_group_inverse_capacity_v3(p_group uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q cp7_sku_conversion.valuation_quotes_v2%rowtype;
begin
 perform erp.require_internal();perform erp.require_permission('warehouse.brand_conversion.reverse');perform erp.require_owner_admin();
 perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 select *into strict q from cp7_sku_conversion.valuation_quotes_v2 where group_id=p_group;
 if exists(select 1 from cp7_sku_conversion.valuation_postings_v2 where group_id=p_group and phase='REVERSE')then
  raise exception 'CP7_SKU_MOVAVG_ALREADY_REVERSED';end if;
 if not exists(select 1 from cp7_sku_conversion.members_v1 where group_id=p_group)
  or exists(select 1 from cp7_sku_conversion.members_v1 m left join erp.product_conversions c on c.id=m.conversion_id
   where m.group_id=p_group and c.status is distinct from 'POSTED')then
  raise exception 'CP7_SKU_INVERSE_ALL_MEMBERS_POSTED_REQUIRED';end if;
 if exists(
  select 1 from cp7_sku_conversion.valuation_contributors_v2 c
  left join cp7_sku_conversion.pool_components_v2(q.target_product_id,q.location_id,q.quality_grade)p using(root_lot_id)
  where c.group_id=p_group and coalesce(p.component_units,0)<c.transfer_units
 )then raise exception 'CP7_SKU_INVERSE_ECONOMIC_COMPONENT_USED';end if;
 if exists(
  with required as(
   select c.root_lot_id,c.transfer_units units from cp7_sku_conversion.cost_contributors_v3 c where c.group_id=p_group
   union all select e.root_lot_id,e.units_delta from cp7_sku_conversion.cost_events_v3 e
    where e.source_type='SKU_CONVERSION'and e.source_id=p_group and e.side='ORIGIN'and e.phase='POST'
  ),needed as(select root_lot_id,sum(units)units from required group by root_lot_id)
  select 1 from needed n left join cp7_sku_conversion.pool_cost_components_v3(q.target_product_id,q.location_id,q.quality_grade)p using(root_lot_id)
  where coalesce(p.component_units,0)<n.units
 )then raise exception 'CP7_SKU_INVERSE_ECONOMIC_COST_USED';end if;
end $function$

cp7_sku_conversion.capture_group_inverse:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.capture_group_inverse_v3(p_group uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare q cp7_sku_conversion.valuation_quotes_v2%rowtype;products uuid[];roots uuid[];product uuid;
 target jsonb;book jsonb;proof jsonb:='[]';
begin
 perform erp.require_internal();perform erp.require_permission('warehouse.brand_conversion.reverse');perform erp.require_owner_admin();
 perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 select *into strict q from cp7_sku_conversion.valuation_quotes_v2 where group_id=p_group;
 if not exists(select 1 from cp7_sku_conversion.members_v1 where group_id=p_group)
  or exists(select 1 from cp7_sku_conversion.members_v1 m left join erp.product_conversions c on c.id=m.conversion_id
   where m.group_id=p_group and c.status is distinct from 'REVERSED')then
  raise exception 'CP7_SKU_NATIVE_INVERSE_REQUIRED';end if;
 select array_agg(id order by id)into products from(select distinct unnest(array[q.source_product_id,q.target_product_id])id)p;
 select coalesce(array_agg(distinct id order by id),'{}'::uuid[])into roots from(
  select unnest(cp7_sku_conversion.hpp_scope_lot_ids_v2(p.product_id,null))id from unnest(products)p(product_id)
  union select root_lot_id from cp7_sku_conversion.valuation_contributors_v2 where group_id=p_group
  union select root_lot_id from cp7_sku_conversion.cost_contributors_v3 where group_id=p_group
  union select a.destination_lot_id from cp7_sku_conversion.members_v1 m
   join erp.product_conversion_allocations a on a.conversion_id=m.conversion_id where m.group_id=p_group
 )r;
 foreach product in array products loop
  perform erp.assert_non_po_product_hpp_target_book_v2620f(product);
  select to_jsonb(t)into strict target from erp.compute_non_po_product_hpp_targets_v2620f(product)t;
  select to_jsonb(b)into strict book from erp.compute_non_po_product_hpp_book_v2620f(product)b;
  if target is distinct from book then raise exception 'CP7_SKU_INVERSE_PRESTATE_NOT_EXACT';end if;
  proof:=proof||jsonb_build_array(jsonb_build_object('product_id',product,'target',target,'book',book));
 end loop;
 return jsonb_build_object('group_id',p_group,'products',to_jsonb(products),'roots',to_jsonb(roots),'before',proof,
  'sources',cp7_sku_conversion.inverse_source_facts_v3(roots),'backend_pid',pg_backend_pid(),'transaction_id',txid_current());
end $function$

cp7_sku_conversion.rebalance_group_inver:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.rebalance_group_inverse_v3(p_group uuid, p_before jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare q cp7_sku_conversion.valuation_quotes_v2%rowtype;products uuid[];roots uuid[];product uuid;row jsonb;
 target jsonb;book jsonb;proof jsonb:='[]';lines jsonb:='[]';target_change numeric:=0;book_change numeric:=0;
 redistribution numeric:=0;delta numeric;journal uuid;economic_date date:=(statement_timestamp()at time zone 'Asia/Jakarta')::date;
begin
 perform erp.require_internal();perform erp.require_permission('warehouse.brand_conversion.reverse');perform erp.require_owner_admin();
 perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 select *into strict q from cp7_sku_conversion.valuation_quotes_v2 where group_id=p_group;
 if p_before->>'group_id'is distinct from p_group::text
  or(p_before->>'backend_pid')::integer is distinct from pg_backend_pid()
  or(p_before->>'transaction_id')::bigint is distinct from txid_current()then
  raise exception 'CP7_SKU_INVERSE_PROOF_REQUIRED';end if;
 select array_agg(id order by id)into products from(select distinct unnest(array[q.source_product_id,q.target_product_id])id)p;
 if to_jsonb(products)is distinct from p_before->'products'then raise exception 'CP7_SKU_INVERSE_SCOPE_CHANGED';end if;
 select array_agg(value::uuid order by value::uuid)into roots from jsonb_array_elements_text(p_before->'roots');
 if cp7_sku_conversion.inverse_source_facts_v3(roots)is distinct from p_before->'sources'then
  raise exception 'CP7_SKU_INVERSE_SOURCE_CHANGED';end if;
 foreach product in array products loop
  select value into strict row from jsonb_array_elements(p_before->'before')where(value->>'product_id')::uuid=product;
  select to_jsonb(t)into strict target from erp.compute_non_po_product_hpp_targets_v2620f(product)t;
  select to_jsonb(b)into strict book from erp.compute_non_po_product_hpp_book_v2620f(product)b;
  target_change:=target_change+(target->>'hpp_total_cost')::numeric-(row->'target'->>'hpp_total_cost')::numeric;
  book_change:=book_change+(book->>'hpp_total_cost')::numeric-(row->'book'->>'hpp_total_cost')::numeric;
  delta:=(target->>'hpp_total_cost')::numeric-(book->>'hpp_total_cost')::numeric;
  redistribution:=redistribution+delta;
  proof:=proof||jsonb_build_array(jsonb_build_object('product_id',product,'target',target,'book',book,'current_value_reallocation',delta));
  if delta<>0 then lines:=lines||jsonb_build_array(jsonb_build_object('mapping_key','FG_INVENTORY','product_id',product,
   'debit',greatest(delta,0),'credit',greatest(-delta,0)));end if;
 end loop;
 if target_change<>0 or book_change<>0 or redistribution<>0 then
  raise exception 'CP7_SKU_INVERSE_TOTAL_NOT_EXACT: target %, book %, redistribution %',target_change,book_change,redistribution;end if;
 if jsonb_array_length(lines)>0 then
  journal:=erp.post_journal('SKU_CURRENT_VALUE_INVERSE',p_group,economic_date,'Pembalikan mengikuti nilai sumber terkini',lines);
 end if;
 foreach product in array products loop
  perform erp.sync_non_po_product_hpp_to_gl_v2620f(product,economic_date,'SKU_CURRENT_VALUE_INVERSE',p_group,'Nilai terkini sesudah pembalikan Ganti Merek');
  perform erp.assert_non_po_product_hpp_target_book_v2620f(product);
 end loop;
 insert into cp7_sku_conversion.group_inverse_rebalances_v3(group_id,before_proof,after_proof,journal_id,economic_date)
 values(p_group,p_before,jsonb_build_object('after_historical_inverse',proof,'target_change',target_change,'book_change',book_change),journal,economic_date);
end $function$

cp7_sku_conversion.rebalance_cost_source:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.rebalance_cost_source_v3(p_document uuid, p_date date, p_before jsonb, p_source_delta numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare products uuid[];product uuid;row jsonb;target jsonb;book jsonb;proof jsonb:='[]';lines jsonb:='[]';
 old_events jsonb;delta numeric;target_change numeric:=0;book_change numeric:=0;redistribution numeric:=0;event_change numeric;
 event_id uuid;journal uuid;new_events jsonb;
begin
 perform erp.require_internal();perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 if p_before->>'document_id'is distinct from p_document::text
  or(p_before->>'backend_pid')::integer is distinct from pg_backend_pid()
  or(p_before->>'transaction_id')::bigint is distinct from txid_current()
  or p_source_delta is null or p_source_delta<>round(p_source_delta,2)
  or p_source_delta::text in('NaN','Infinity','-Infinity')then raise exception 'CP7_SKU_COST_SOURCE_PROOF_REQUIRED';end if;
 products:=cp7_sku_conversion.cost_source_products_v3(p_document);
 if to_jsonb(products)is distinct from p_before->'products'then raise exception 'CP7_SKU_COST_SOURCE_SCOPE_CHANGED';end if;
 select coalesce(jsonb_agg(to_jsonb(e)order by e.id),'[]')into old_events from erp.be_conversion_cost_events_v1 e
 where e.document_id=p_document and e.id in(select(value->>'id')::uuid from jsonb_array_elements(p_before->'cost_events'));
 if old_events is distinct from p_before->'cost_events'then raise exception 'CP7_SKU_COST_SOURCE_HISTORY_CHANGED';end if;
 select coalesce(sum(e.target_amount-e.previous_amount),0),coalesce(jsonb_agg(to_jsonb(e)order by e.id),'[]')into event_change,new_events
 from erp.be_conversion_cost_events_v1 e where e.document_id=p_document
  and e.id not in(select(value->>'id')::uuid from jsonb_array_elements(p_before->'cost_events'));
 if event_change is distinct from p_source_delta then raise exception 'CP7_SKU_COST_SOURCE_EVENT_DELTA_NOT_EXACT';end if;
 -- Retain physical recost and its own immutable source entries. The later
 -- original sync call sees no further physical change and distributes FG/COGS.
 perform cp7_sku_conversion.reprice_document_money_v3(p_document,p_date,p_before->'cost_money_state',new_events,p_source_delta);
 perform erp.be_nonpo_prepare_transfers_v1(p_date);
 foreach product in array products loop
  select value into strict row from jsonb_array_elements(p_before->'before')where(value->>'product_id')::uuid=product;
  select to_jsonb(t)into strict target from erp.compute_non_po_product_hpp_targets_v2620f(product)t;
  select to_jsonb(b)into strict book from erp.compute_non_po_product_hpp_book_v2620f(product)b;
  target_change:=target_change+(target->>'hpp_total_cost')::numeric-(row->'target'->>'hpp_total_cost')::numeric;
  book_change:=book_change+(book->>'hpp_total_cost')::numeric-(row->'book'->>'hpp_total_cost')::numeric;
  delta:=(target->>'hpp_total_cost')::numeric-(book->>'hpp_total_cost')::numeric;
  redistribution:=redistribution+delta;
  proof:=proof||jsonb_build_array(jsonb_build_object('product_id',product,'target',target,'book',book,'source_reallocation',delta));
  if delta<>0 then lines:=lines||jsonb_build_array(jsonb_build_object('mapping_key','FG_INVENTORY','product_id',product,
   'debit',greatest(delta,0),'credit',greatest(-delta,0)));end if;
 end loop;
 if target_change is distinct from p_source_delta or book_change is distinct from p_source_delta or redistribution<>0 then
  raise exception 'CP7_SKU_COST_SOURCE_TOTAL_NOT_EXACT: source %, target change %, book change %, redistribution %',p_source_delta,target_change,book_change,redistribution;end if;
 if jsonb_array_length(lines)>0 then
  event_id:=gen_random_uuid();
  journal:=erp.post_journal('SKU_SOURCED_COST_REALLOCATION',event_id,p_date,'Pembagian biaya sumber mengikuti nilai SKU yang memiliki',lines);
  insert into cp7_sku_conversion.cost_source_rebalances_v3(id,document_id,source_delta,before_proof,after_proof,journal_id,economic_date)
  values(event_id,p_document,p_source_delta,p_before,jsonb_build_object('after_native_physical',proof,'new_source_events',new_events),journal,p_date);
 end if;
end $function$

cp7_sku_conversion.cost_current_unit_v3(:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.cost_current_unit_v3(p_root uuid, p_product uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;total_units numeric;total_money numeric;owned record;
begin
 -- Keep current HPP completeness and real PO attribution from the Native root.
 select *into strict r from cp7_sku_conversion.cost_root_v3(p_root);
 if r.po_id is not null then return r.unit_value;end if;
 if p_product is null then raise exception 'CP7_SKU_COST_MONEY_PRODUCT_REQUIRED';end if;
 select a.qty_pcs,erp.be_allocation_extra_v1(a.id)extra into strict r
 from erp.product_conversion_allocations a where a.destination_lot_id=p_root;
 select sum(c.units),sum(c.amount)into total_units,total_money from cp7_sku_conversion.cost_money_cells_v3(p_root)c;
 if not exists(select 1 from cp7_sku_conversion.cost_money_events_v3 where root_lot_id=p_root and kind='ORIGIN')
  or total_units is null or total_money is null
  or exists(select 1 from cp7_sku_conversion.cost_money_cells_v3(p_root)c where c.units<0 or(c.units=0 and c.amount<>0))
  or exists(select 1 from cp7_sku_conversion.cost_events_v3 e where e.root_lot_id=p_root
   and(e.source_type<>'SALE'or exists(select 1 from erp.sales_headers h where h.id=e.source_id and h.status in('POSTED','PARTIAL_PAID','PAID','REVERSED')))
   and(e.source_type<>'SALES_RETURN'or exists(select 1 from erp.sales_returns h where h.id=e.source_id and h.status in('POSTED','REVERSED')))
   group by e.product_id having sum(e.units_delta)<0)
  or(total_units<>r.qty_pcs and total_units<>0)
  or(total_units=0 and(total_money<>0 or r.extra<>0))
  or(total_units>0 and total_money is distinct from r.extra)then
  raise exception 'CP7_SKU_COST_MONEY_SOURCE_NOT_EXACT';end if;
 select c.units,c.amount into owned from cp7_sku_conversion.cost_money_cells_v3(p_root)c where c.product_id=p_product;
 if not found or owned.units=0 then return 0;end if;
 return owned.amount/owned.units;
end $function$

cp7_sku_conversion.post_conversion_money:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.post_conversion_money_v3(p_group uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare q cp7_sku_conversion.valuation_quotes_v2%rowtype;c record;cell record;old_units numeric;
 economic_date date;product uuid;
begin
 perform erp.require_internal();perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 select *into strict q from cp7_sku_conversion.valuation_quotes_v2 where group_id=p_group;
 economic_date:=(q.physical_at at time zone 'Asia/Jakarta')::date;
 for c in select *from cp7_sku_conversion.cost_contributors_v3 where group_id=p_group and po_id is null order by root_lot_id loop
  select *into strict cell from cp7_sku_conversion.cost_money_cells_v3(c.root_lot_id)where product_id=q.source_product_id;
  -- Cost units have just moved; the money still belongs to the old source.
  old_units:=cell.units+c.transfer_units;
  if old_units<=0 or c.transfer_units>old_units
   or(c.transfer_units=old_units and c.transfer_value is distinct from cell.amount)
   or(cell.amount>=0 and(c.transfer_value<0 or c.transfer_value>cell.amount))
   or(cell.amount<0 and(c.transfer_value>0 or c.transfer_value<cell.amount))then
   raise exception 'CP7_SKU_COST_MONEY_TRANSFER_CAPACITY';end if;
  insert into cp7_sku_conversion.cost_money_events_v3(id,kind,source_id,root_lot_id,product_id,amount_delta,revision,source_proof,economic_date)
  values(gen_random_uuid(),'TRANSFER',p_group,c.root_lot_id,q.source_product_id,-c.transfer_value,p_group::text,to_jsonb(c),economic_date),
        (gen_random_uuid(),'TRANSFER',p_group,c.root_lot_id,q.target_product_id,c.transfer_value,p_group::text,to_jsonb(c),economic_date);
 end loop;
 for c in select a.*,l.po_id from cp7_sku_conversion.members_v1 m
  join erp.product_conversion_allocations a on a.conversion_id=m.conversion_id join erp.fg_lots l on l.id=a.destination_lot_id
  where m.group_id=p_group and l.po_id is null order by a.id loop
  insert into cp7_sku_conversion.cost_money_events_v3(id,kind,source_id,root_lot_id,product_id,amount_delta,revision,source_proof,economic_date)
  values(gen_random_uuid(),'ORIGIN',p_group,c.destination_lot_id,q.target_product_id,erp.be_allocation_extra_v1(c.id),
   p_group::text,jsonb_build_object('allocation',to_jsonb(c),'initial_extra',erp.be_allocation_extra_v1(c.id)),economic_date);
 end loop;
 for c in select distinct e.root_lot_id from cp7_sku_conversion.cost_events_v3 e where e.source_type='SKU_CONVERSION'and e.source_id=p_group loop
  perform cp7_sku_conversion.cost_current_unit_v3(c.root_lot_id,q.source_product_id);
  perform cp7_sku_conversion.cost_current_unit_v3(c.root_lot_id,q.target_product_id);
 end loop;
end $function$

cp7_sku_conversion.reverse_conversion_mo:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.reverse_conversion_money_v3(p_group uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare q cp7_sku_conversion.valuation_quotes_v2%rowtype;c record;amount numeric;
 economic_date date:=(statement_timestamp()at time zone 'Asia/Jakarta')::date;
begin
 perform erp.require_internal();perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 select *into strict q from cp7_sku_conversion.valuation_quotes_v2 where group_id=p_group;
 for c in select *from cp7_sku_conversion.cost_contributors_v3 where group_id=p_group and po_id is null order by root_lot_id loop
  amount:=round(c.transfer_units*cp7_sku_conversion.cost_current_unit_v3(c.root_lot_id,q.target_product_id),2);
  insert into cp7_sku_conversion.cost_money_events_v3(id,kind,source_id,root_lot_id,product_id,amount_delta,revision,source_proof,economic_date)
  values(gen_random_uuid(),'INVERSE_TRANSFER',p_group,c.root_lot_id,q.target_product_id,-amount,p_group::text,
         jsonb_build_object('original_contributor',to_jsonb(c),'current_amount',amount),economic_date),
        (gen_random_uuid(),'INVERSE_TRANSFER',p_group,c.root_lot_id,q.source_product_id,amount,p_group::text,
         jsonb_build_object('original_contributor',to_jsonb(c),'current_amount',amount),economic_date);
 end loop;
 for c in select a.*,l.po_id from cp7_sku_conversion.members_v1 m
  join erp.product_conversion_allocations a on a.conversion_id=m.conversion_id join erp.fg_lots l on l.id=a.destination_lot_id
  where m.group_id=p_group and l.po_id is null order by a.id loop
  if erp.be_allocation_extra_v1(c.id)<>0
   or exists(select 1 from cp7_sku_conversion.cost_money_cells_v3(c.destination_lot_id)x where x.amount<>0)then
   raise exception 'CP7_SKU_INVERSE_OWN_COST_STILL_ACTIVE';end if;
  insert into cp7_sku_conversion.cost_money_events_v3(id,kind,source_id,root_lot_id,product_id,amount_delta,revision,source_proof,economic_date)
  values(gen_random_uuid(),'INVERSE_ORIGIN',p_group,c.destination_lot_id,q.target_product_id,0,p_group::text,to_jsonb(c),economic_date);
 end loop;
end $function$

cp7_sku_conversion.cost_document_money_s:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.cost_document_money_state_v3(p_document uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a record;state jsonb:='[]';cells jsonb;
begin
 for a in select allocation.*,l.po_id from erp.be_conversion_cost_sources_v1 s
  join erp.product_conversion_allocations allocation on allocation.conversion_id=s.conversion_id join erp.fg_lots l on l.id=allocation.destination_lot_id
  where s.document_id=p_document and l.po_id is null order by allocation.destination_lot_id loop
  perform cp7_sku_conversion.cost_current_unit_v3(a.destination_lot_id,(select e.product_id from cp7_sku_conversion.cost_events_v3 e
   where e.root_lot_id=a.destination_lot_id and e.side='ORIGIN'and e.phase='POST'));
  select coalesce(jsonb_agg(to_jsonb(c)order by c.product_id),'[]')into cells from cp7_sku_conversion.cost_money_cells_v3(a.destination_lot_id)c;
  state:=state||jsonb_build_array(jsonb_build_object('root_lot_id',a.destination_lot_id,'allocation_id',a.id,'qty',a.qty_pcs,
   'extra',erp.be_allocation_extra_v1(a.id),'cells',cells,
   'money_events',(select coalesce(jsonb_agg(to_jsonb(e)order by e.id),'[]')from cp7_sku_conversion.cost_money_events_v3 e where e.root_lot_id=a.destination_lot_id)));
 end loop;
 return state;
end $function$

cp7_sku_conversion.reprice_document_mone:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.reprice_document_money_v3(p_document uuid, p_date date, p_before jsonb, p_events jsonb, p_delta numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old_root jsonb;current_cells jsonb;old_events jsonb;a record;c record;new_total numeric;old_total numeric;
 cumulative_units numeric;previous_target numeric;target numeric;amount numeric;total_change numeric:=0;revision text;count_roots integer:=0;
begin
 perform erp.require_internal();perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 if jsonb_typeof(p_before)is distinct from 'array'or jsonb_typeof(p_events)is distinct from 'array'then
  raise exception 'CP7_SKU_COST_MONEY_SOURCE_PROOF_REQUIRED';end if;
 for a in select allocation.*,l.po_id from erp.be_conversion_cost_sources_v1 s
  join erp.product_conversion_allocations allocation on allocation.conversion_id=s.conversion_id join erp.fg_lots l on l.id=allocation.destination_lot_id
  where s.document_id=p_document and l.po_id is null order by allocation.destination_lot_id loop
  count_roots:=count_roots+1;
  select value into strict old_root from jsonb_array_elements(p_before)where(value->>'root_lot_id')::uuid=a.destination_lot_id;
  select coalesce(jsonb_agg(to_jsonb(x)order by x.product_id),'[]')into current_cells from cp7_sku_conversion.cost_money_cells_v3(a.destination_lot_id)x;
  select coalesce(jsonb_agg(to_jsonb(e)order by e.id),'[]')into old_events from cp7_sku_conversion.cost_money_events_v3 e where e.root_lot_id=a.destination_lot_id;
  if old_root->>'allocation_id'is distinct from a.id::text or(old_root->>'qty')::numeric is distinct from a.qty_pcs
   or current_cells is distinct from old_root->'cells'or old_events is distinct from old_root->'money_events'then
   raise exception 'CP7_SKU_COST_MONEY_CUSTODY_CHANGED';end if;
  old_total:=(old_root->>'extra')::numeric;new_total:=erp.be_allocation_extra_v1(a.id);
  if old_total is distinct from(select sum(x.amount)from cp7_sku_conversion.cost_money_cells_v3(a.destination_lot_id)x)
   or new_total is null or new_total<>round(new_total,2)or new_total::text in('NaN','Infinity','-Infinity')then
   raise exception 'CP7_SKU_COST_MONEY_SOURCE_NOT_EXACT';end if;
  total_change:=total_change+new_total-old_total;
  if new_total=old_total then continue;end if;
  if jsonb_array_length(p_events)=0 then raise exception 'CP7_SKU_COST_MONEY_NATIVE_EVENTS_REQUIRED';end if;
  cumulative_units:=0;previous_target:=0;
  revision:=md5(jsonb_build_object('before',old_root,'new_total',new_total,'events',p_events)::text);
  for c in select *from cp7_sku_conversion.cost_money_cells_v3(a.destination_lot_id)order by product_id loop
   if c.units<0 or(c.units=0 and c.amount<>0)then raise exception 'CP7_SKU_COST_MONEY_CAPACITY';end if;
   cumulative_units:=cumulative_units+c.units;
   target:=round(new_total*cumulative_units/a.qty_pcs,2);amount:=target-previous_target-c.amount;previous_target:=target;
   if amount<>0 then
    insert into cp7_sku_conversion.cost_money_events_v3(id,kind,source_id,root_lot_id,product_id,amount_delta,revision,source_proof,economic_date)
    values(gen_random_uuid(),'SOURCE_PRICE',p_document,a.destination_lot_id,c.product_id,amount,revision,
     jsonb_build_object('allocation_id',a.id,'qty_basis_pcs',a.qty_pcs,'old_total',old_total,'new_total',new_total,
      'before_cell',to_jsonb(c),'before_money_event_count',jsonb_array_length(old_root->'money_events'),
      'before_money_revision',md5((old_root->'money_events')::text),'native_events',p_events,
      'cumulative_units',cumulative_units,'cumulative_target',target),p_date);
   end if;
  end loop;
  if cumulative_units is distinct from a.qty_pcs or previous_target is distinct from new_total then
   raise exception 'CP7_SKU_COST_MONEY_ALLOCATION_NOT_EXACT';end if;
 end loop;
 if count_roots<>jsonb_array_length(p_before)or total_change is distinct from p_delta then
  raise exception 'CP7_SKU_COST_MONEY_DOCUMENT_DELTA_NOT_EXACT';end if;
end $function$

cp7_sku_conversion.return_cost_component:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.return_cost_components_v3(p_allocation uuid, p_qty numeric, p_current_return uuid)
 RETURNS TABLE(root_lot_id uuid, po_id uuid, component_units numeric, hpp_per_pcs numeric, hpp_version_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_sold numeric;v_prior numeric;v_product uuid;
begin
 perform erp.require_internal();
 if p_qty is null or p_qty<=0 or p_qty<>trunc(p_qty)or p_qty::text in('NaN','Infinity','-Infinity')then
  raise exception 'CP7_SKU_RETURN_COMPONENT_QTY_INVALID';end if;
 select v.qty_pcs,v.product_id into v_sold,v_product from cp7_sku_conversion.sale_allocation_values_v2 v where v.sale_stock_allocation_id=p_allocation;
 if not found then return;end if;
 select coalesce(sum(i.qty_pcs),0)into v_prior from erp.sales_return_items i join erp.sales_returns h on h.id=i.return_id
  where i.sale_stock_allocation_id=p_allocation and h.status='POSTED';
 if p_current_return is not null then v_prior:=v_prior+coalesce((select sum(v.qty_pcs)
  from cp7_sku_conversion.sales_return_values_v2 v where v.sale_stock_allocation_id=p_allocation and v.return_id=p_current_return),0);end if;
 if v_prior+p_qty>v_sold then raise exception 'CP7_SKU_RETURN_VALUE_EXCEEDS_SALE_ALLOCATION';end if;
 return query with prior as(
  select c.root_lot_id,sum(c.component_units)::numeric units from cp7_sku_conversion.return_cost_components_v3 c
  join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)join erp.sales_returns h on h.id=v.return_id
  where v.sale_stock_allocation_id=p_allocation and(h.status='POSTED'or h.id=p_current_return)group by c.root_lot_id
 ),planned as(
  select c.root_lot_id,c.po_id,(round((v_prior+p_qty)*c.component_units/v_sold,12)-coalesce(p.units,0))::numeric units
  from cp7_sku_conversion.sale_cost_components_v3 c left join prior p on p.root_lot_id=c.root_lot_id
  where c.sale_stock_allocation_id=p_allocation
 )select p.root_lot_id,p.po_id,p.units,cp7_sku_conversion.cost_current_unit_v3(p.root_lot_id,v_product),r.hpp_version_id from planned p
 cross join lateral cp7_sku_conversion.cost_root_v3(p.root_lot_id)r where p.units<>0 order by p.root_lot_id;
end $function$

cp7_sku_conversion.capture_cost_source_v:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.capture_cost_source_v3(p_document uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare products uuid[];product uuid;proof jsonb:='[]';target jsonb;book jsonb;events jsonb;
begin
 perform erp.require_internal();perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 products:=cp7_sku_conversion.cost_source_products_v3(p_document);
 if cardinality(products)=0 then raise exception 'CP7_SKU_COST_SOURCE_SCOPE_EMPTY';end if;
 foreach product in array products loop
  -- Opposite unexplained discrepancies cannot cancel in a global sum.
  perform erp.assert_non_po_product_hpp_target_book_v2620f(product);
  select to_jsonb(t)into strict target from erp.compute_non_po_product_hpp_targets_v2620f(product)t;
  select to_jsonb(b)into strict book from erp.compute_non_po_product_hpp_book_v2620f(product)b;
  if target is distinct from book then raise exception 'CP7_SKU_COST_SOURCE_PRESTATE_NOT_EXACT';end if;
  proof:=proof||jsonb_build_array(jsonb_build_object('product_id',product,'target',target,'book',book));
 end loop;
 select coalesce(jsonb_agg(to_jsonb(e)order by e.id),'[]')into events from erp.be_conversion_cost_events_v1 e where e.document_id=p_document;
 return jsonb_build_object('cost_money_state',cp7_sku_conversion.cost_document_money_state_v3(p_document),'document_id',p_document,'products',to_jsonb(products),'before',proof,'cost_events',events,
  'backend_pid',pg_backend_pid(),'transaction_id',txid_current());
end $function$

cp7_sku_conversion.base_scope_correction:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.base_scope_correction_v4(p_product uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c record;answer numeric:=0;
begin
 for c in select e.root_lot_id,sum(e.units_delta)units,sum(e.amount_delta)amount,h.hpp_per_pcs
  from cp7_sku_conversion.base_money_events_v4 e join erp.hpp_versions h on h.lot_id=e.root_lot_id and h.is_current
  where e.product_id=p_product group by e.root_lot_id,h.hpp_per_pcs loop
  perform cp7_sku_conversion.base_current_unit_v4(c.root_lot_id,p_product);
  perform cp7_sku_conversion.base_transition_value_v4(c.root_lot_id,p_product);
  answer:=answer+c.amount-c.units*c.hpp_per_pcs;
 end loop;
 return answer;
end $function$

cp7_sku_conversion.base_current_unit_v4(:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.base_current_unit_v4(p_root uuid, p_product uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h record;c record;qty numeric;amount numeric;
begin
 select v.*,l.po_id into strict h from erp.fg_lots l join erp.hpp_versions v on v.lot_id=l.id and v.is_current where l.id=p_root;
 if h.po_id is not null and exists(select 1 from cp7_sku_conversion.base_money_events_v4 where root_lot_id=p_root)then
  raise exception 'CP7_SKU_BASE_MONEY_PO_PROVENANCE_CHANGED';end if;
 if h.po_id is not null or not exists(select 1 from cp7_sku_conversion.base_money_events_v4 where root_lot_id=p_root)then
  return h.hpp_per_pcs;end if;
 select sum(x.units),sum(x.amount)into qty,amount from cp7_sku_conversion.base_money_cells_v4(p_root)x;
 if p_product is null or h.qty_basis_pcs<=0 or h.total_cost<0 or h.total_cost::text in('NaN','Infinity','-Infinity')
  or h.cost_state='ESTIMATED'or qty is distinct from h.qty_basis_pcs or amount is distinct from round(h.total_cost,2)
  or(select count(*)from cp7_sku_conversion.base_money_events_v4 where root_lot_id=p_root and kind='ORIGIN')<>1
  or exists(select 1 from cp7_sku_conversion.base_money_cells_v4(p_root)x where x.units<0 or x.amount<0 or(x.units=0 and x.amount<>0))then
  raise exception 'CP7_SKU_BASE_MONEY_SOURCE_NOT_EXACT';end if;
 select *into c from cp7_sku_conversion.base_money_cells_v4(p_root)where product_id=p_product;
 if not found or c.units=0 then return 0;end if;
 return c.amount/c.units;
end $function$

cp7_sku_conversion.ensure_base_money_v4(:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.ensure_base_money_v4(p_root uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r record;cell record;
begin
 perform erp.require_internal();perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 select l.*,h.id hpp_id,h.qty_basis_pcs,h.total_cost,h.cost_state into strict r
 from erp.fg_lots l join erp.hpp_versions h on h.lot_id=l.id and h.is_current where l.id=p_root;
 if r.po_id is not null then perform cp7_sku_conversion.base_current_unit_v4(p_root,r.product_id);return;end if;
 if exists(select 1 from cp7_sku_conversion.base_money_events_v4 where root_lot_id=p_root)then
  perform cp7_sku_conversion.base_current_unit_v4(p_root,r.product_id);
  for cell in select product_id from cp7_sku_conversion.base_money_cells_v4(p_root)
   union select product_id from cp7_sku_conversion.base_raw_custody_v4(p_root)loop
   perform cp7_sku_conversion.base_transition_value_v4(p_root,cell.product_id);
  end loop;
  return;end if;
 if r.lot_origin in('CONVERSION','VOIDED_PRODUCTION')or r.qty_basis_pcs<=0 or r.qty_basis_pcs<>r.initial_qty_pcs
  or r.total_cost<0 or r.total_cost::text in('NaN','Infinity','-Infinity')or r.cost_state='ESTIMATED'
  or exists(select 1 from cp7_sku_conversion.component_events_v2 where root_lot_id=p_root and source_type='SKU_CONVERSION')
  or exists(select 1 from erp.product_conversion_allocations a join erp.product_conversions c on c.id=a.conversion_id
   where a.source_lot_id=p_root and c.status='POSTED')then
  raise exception 'CP7_SKU_BASE_MONEY_UNADMITTED_PRIOR_CUSTODY';end if;
 insert into cp7_sku_conversion.base_money_events_v4(id,kind,source_id,root_lot_id,product_id,units_delta,amount_delta,source_proof,economic_date)
 values(gen_random_uuid(),'ORIGIN',r.hpp_id,p_root,r.product_id,r.qty_basis_pcs,round(r.total_cost,2),to_jsonb(r),
  (statement_timestamp()at time zone 'Asia/Jakarta')::date);
end $function$

