cp7_sku_conversion.reprice_base_money_v4:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.reprice_base_money_v4(p_root uuid, p_date date, p_before jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare h record;c record;cells jsonb;events jsonb;new_total numeric;old_total numeric;cumulative numeric:=0;prior numeric:=0;target numeric;delta numeric;
begin
 perform erp.require_internal();perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 if p_before->>'root'is distinct from p_root::text or(p_before->>'backend_pid')::integer is distinct from pg_backend_pid()
  or(p_before->>'transaction_id')::bigint is distinct from txid_current()then raise exception 'CP7_SKU_BASE_PRICE_PROOF_REQUIRED';end if;
 select *into strict h from erp.hpp_versions where lot_id=p_root and is_current;
 select jsonb_agg(to_jsonb(cell)order by cell.product_id)into cells from cp7_sku_conversion.base_money_cells_v4(p_root)cell;
 select jsonb_agg(to_jsonb(e)order by e.id)into events from cp7_sku_conversion.base_money_events_v4 e where e.root_lot_id=p_root;
 old_total:=round((p_before->'hpp'->>'total_cost')::numeric,2);new_total:=round(h.total_cost,2);
 if cells is distinct from p_before->'cells'or events is distinct from p_before->'events'
  or h.qty_basis_pcs is distinct from(p_before->'hpp'->>'qty_basis_pcs')::integer
  or h.supersedes_id::text is distinct from p_before->'hpp'->>'id'
  or new_total<0 or new_total::text in('NaN','Infinity','-Infinity')or h.cost_state='ESTIMATED'
  or old_total is distinct from(select sum(x.amount)from cp7_sku_conversion.base_money_cells_v4(p_root)x)then
  raise exception 'CP7_SKU_BASE_PRICE_SOURCE_NOT_EXACT';end if;
 if new_total=old_total then return;end if;
 for c in select *from cp7_sku_conversion.base_money_cells_v4(p_root)order by product_id loop
  cumulative:=cumulative+c.units;target:=round(new_total*cumulative/h.qty_basis_pcs,2);delta:=target-prior-c.amount;prior:=target;
  if delta<>0 then
   insert into cp7_sku_conversion.base_money_events_v4(id,kind,source_id,root_lot_id,product_id,units_delta,amount_delta,source_proof,economic_date)
   values(gen_random_uuid(),'SOURCE_PRICE',h.id,p_root,c.product_id,0,delta,
    jsonb_build_object('old_hpp',p_before->'hpp','new_hpp',to_jsonb(h),'before_cell',to_jsonb(c),
     'prior_event_count',jsonb_array_length(events),'prior_event_digest',md5(events::text),'cumulative_units',cumulative,'cumulative_target',target),p_date);
  end if;
 end loop;
 if cumulative is distinct from h.qty_basis_pcs or prior is distinct from new_total then raise exception 'CP7_SKU_BASE_PRICE_CENTS_NOT_EXACT';end if;
end $function$

cp7_credit.initial_hpp_projection_v1(jso:
CREATE OR REPLACE FUNCTION cp7_credit.initial_hpp_projection_v1(p_legacy jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare x jsonb;a record;r record;t record;b record;cost numeric;owned numeric;sold numeric;returned numeric;
 hpp numeric:=0;items jsonb:='[]';groups jsonb:='[]';lines jsonb:='[]';group_amount numeric;
 products uuid[];pos uuid[];lots uuid[];versions uuid[];fresh_lots uuid[];fresh_versions uuid[];
 before_profile jsonb;after_profile jsonb;before_target jsonb;after_target jsonb;actual_book jsonb;saved_state jsonb;account_facts jsonb;source_support jsonb;opening_source jsonb;
 component_plan jsonb;fresh_component_plan jsonb;scope_items jsonb;
 delta_fg numeric;delta_cogs numeric;delta_other numeric;fg_account uuid;cogs_account uuid;expense_account uuid;income_account uuid;
begin
 select array_agg(distinct i.product_id order by i.product_id),array_agg(distinct fl.po_id order by fl.po_id)filter(where fl.po_id is not null)
 into products,pos from jsonb_array_elements(p_legacy->'items')as draft_item(value)join erp.sale_stock_allocations sa on sa.id=(draft_item.value->>'allocation_id')::uuid
  join erp.sales_items i on i.id=sa.sale_item_id join erp.fg_lots fl on fl.id=sa.lot_id;
 pos:=coalesce(pos,'{}'::uuid[]);
 select coalesce(jsonb_agg(jsonb_build_object('allocation_id',planned_allocation.id,'product_id',si.product_id,'root_lot_id',c.root_lot_id,
  'component_kind',c.kind,'po_id',c.po_id,'component_units',c.component_units,'hpp_per_pcs',c.hpp_per_pcs,'hpp_version_id',c.hpp_version_id)
  order by planned_allocation.id,c.kind,c.root_lot_id),'[]')into component_plan from jsonb_array_elements(p_legacy->'items')as planned_item(value)
  join erp.sale_stock_allocations planned_allocation on planned_allocation.id=(planned_item.value->>'allocation_id')::uuid join erp.sales_items si on si.id=planned_allocation.sale_item_id
  cross join lateral(select 'BASE'::text kind,*from cp7_sku_conversion.return_components_v2(planned_allocation.id,(planned_item.value->>'qty_pcs')::numeric,null)
  union all select 'COST',*from cp7_sku_conversion.return_cost_components_v3(planned_allocation.id,(planned_item.value->>'qty_pcs')::numeric,null))c;
