  select distinct jsonb_build_object('product_id',case when fl.po_id is null then si.product_id end,'po_id',fl.po_id)z
  from jsonb_array_elements(p_legacy->'items')as planned_item(value) join erp.sale_stock_allocations planned_allocation on planned_allocation.id=(planned_item.value->>'allocation_id')::uuid
  join erp.sales_items si on si.id=planned_allocation.sale_item_id join erp.fg_lots fl on fl.id=planned_allocation.lot_id
  union select distinct jsonb_build_object('product_id',case when planned_item.value->>'po_id'is null then(planned_item.value->>'product_id')::uuid end,'po_id',(planned_item.value->>'po_id')::uuid)
   from jsonb_array_elements(component_plan)as planned_item(value))s;
 select coalesce(array_agg(distinct id order by id),'{}'::uuid[])into pos from(
  select unnest(pos)id union select(planned_item.value->>'po_id')::uuid from jsonb_array_elements(scope_items)as planned_item(value) where planned_item.value->>'po_id'is not null)s;

 select coalesce(array_agg(distinct id order by id),'{}'::uuid[])into lots from(
  select id from erp.fg_lots where product_id=any(products)or po_id=any(pos)
  union select unnest(cp7_sku_conversion.hpp_scope_lot_ids_v2((planned_item.value->>'product_id')::uuid,(planned_item.value->>'po_id')::uuid))
   from jsonb_array_elements(scope_items)as planned_item(value))s;
 select coalesce(array_agg(id order by id),'{}'::uuid[])into versions from erp.hpp_versions where lot_id=any(lots);
 perform 1 from erp.locations where id in(select(value->>'location_id')::uuid from jsonb_array_elements(p_legacy->'items'))order by id for share;
 perform 1 from erp.fg_inventory_balances inv where exists(select 1 from jsonb_array_elements(p_legacy->'items')draft_item
  join erp.sale_stock_allocations sa on sa.id=(draft_item->>'allocation_id')::uuid join erp.sales_items si on si.id=sa.sale_item_id
  where inv.product_id=si.product_id and inv.location_id=(draft_item->>'location_id')::uuid and inv.quality_grade=draft_item->>'quality_grade')
  order by inv.product_id,inv.location_id,inv.quality_grade for update;
 -- Include PO siblings even when another product owns them. Never acquire
 -- newly discovered earlier-order rows from the completion callback.
 perform 1 from erp.fg_lots where id=any(lots)order by id for update;
 perform 1 from erp.hpp_versions where id=any(versions)order by id for share;
 perform 1 from erp.opening_lot_hpp_gl_state where lot_id=any(lots)order by lot_id for update;
 perform 1 from erp.opening_hpp_corrections where lot_id=any(lots)order by id for share;
 perform 1 from erp.po_hpp_gl_state where po_id=any(pos)order by po_id for update;
 select coalesce(array_agg(distinct id order by id),'{}'::uuid[])into fresh_lots from(
  select id from erp.fg_lots where product_id=any(products)or po_id=any(pos)
  union select unnest(cp7_sku_conversion.hpp_scope_lot_ids_v2((planned_item.value->>'product_id')::uuid,(planned_item.value->>'po_id')::uuid))
   from jsonb_array_elements(scope_items)as planned_item(value))s;
 select coalesce(array_agg(id order by id),'{}'::uuid[])into fresh_versions from erp.hpp_versions where lot_id=any(fresh_lots);
 select coalesce(jsonb_agg(jsonb_build_object('allocation_id',planned_allocation.id,'product_id',si.product_id,'root_lot_id',c.root_lot_id,
  'component_kind',c.kind,'po_id',c.po_id,'component_units',c.component_units,'hpp_per_pcs',c.hpp_per_pcs,'hpp_version_id',c.hpp_version_id)
  order by planned_allocation.id,c.kind,c.root_lot_id),'[]')into fresh_component_plan from jsonb_array_elements(p_legacy->'items')as planned_item(value)
  join erp.sale_stock_allocations planned_allocation on planned_allocation.id=(planned_item.value->>'allocation_id')::uuid join erp.sales_items si on si.id=planned_allocation.sale_item_id
  cross join lateral(select 'BASE'::text kind,*from cp7_sku_conversion.return_components_v2(planned_allocation.id,(planned_item.value->>'qty_pcs')::numeric,null)
  union all select 'COST',*from cp7_sku_conversion.return_cost_components_v3(planned_allocation.id,(planned_item.value->>'qty_pcs')::numeric,null))c;
 if component_plan is distinct from fresh_component_plan or fresh_lots is distinct from lots or fresh_versions is distinct from versions then raise exception 'CP7_CREDIT_HPP_LOCK_SET_CHANGED';end if;
 account_facts:=cp7_credit.initial_hpp_account_facts_v1();
 fg_account:=cp7_credit.account_by_mapping_v1('FG_INVENTORY');cogs_account:=cp7_credit.account_by_mapping_v1('COGS');
 expense_account:=cp7_credit.account_by_mapping_v1('OTHER_EXPENSE');income_account:=cp7_credit.account_by_mapping_v1('OTHER_INCOME');
 if exists(select 1 from jsonb_array_elements(account_facts->'mappings')as mapped(value)where(mapped.value->>'account_id')::uuid is distinct from
  case mapped.value->>'mapping_key'when'FG_INVENTORY'then fg_account when'COGS'then cogs_account when'OTHER_EXPENSE'then expense_account else income_account end)then
  raise exception 'CP7_CREDIT_HPP_ACCOUNT_SOURCE_CHANGED';end if;
 for x in select value from jsonb_array_elements(p_legacy->'items')loop
  select sa.*,i.sale_id,i.product_id,fl.po_id,fl.lot_origin,hv.id hpp_id,hv.total_cost,hv.qty_basis_pcs,hv.hpp_per_pcs current_unit_snapshot into strict a
   from erp.sale_stock_allocations sa join erp.sales_items i on i.id=sa.sale_item_id join erp.fg_lots fl on fl.id=sa.lot_id
   join erp.hpp_versions hv on hv.lot_id=fl.id and hv.is_current where sa.id=(x->>'allocation_id')::uuid;
  if a.sale_id<>(p_legacy->>'sale_id')::uuid or a.qty_basis_pcs<=0 or a.lot_origin='VOIDED_PRODUCTION'
   or not exists(select 1 from erp.locations where id=(x->>'location_id')::uuid and is_active and location_type='FG_WAREHOUSE')then
   raise exception 'CP7_CREDIT_RETURN_SOURCE_OR_DESTINATION_CHANGED';end if;
  if a.total_cost::text in('NaN','Infinity','-Infinity')or a.current_unit_snapshot::text in('NaN','Infinity','-Infinity')then
   raise exception 'CP7_CREDIT_NONFINITE_HPP_SOURCE';end if;
  cost:=a.total_cost/a.qty_basis_pcs;
  if cost<0 then raise exception 'CP7_CREDIT_NEGATIVE_HPP_SOURCE';end if;
  select coalesce(sum(m.qty_signed),0)+coalesce(sum(abs(m.qty_signed))filter(where m.movement_type='SALE_RESERVE'
   and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=m.id)),0)into owned
   from erp.fg_stock_movements m where m.lot_id=a.lot_id;
  select coalesce(sum(sa.qty_pcs),0)into sold from erp.sale_stock_allocations sa join erp.sales_items si on si.id=sa.sale_item_id
   join erp.sales_headers sh on sh.id=si.sale_id where sa.lot_id=a.lot_id and sh.status in('POSTED','PARTIAL_PAID','PAID');
  select coalesce(sum(ri.qty_pcs),0)into returned from erp.sales_return_items ri join erp.sales_returns rr on rr.id=ri.return_id
   where ri.lot_id=a.lot_id and rr.status='POSTED';
  -- Preserve the retained Native allocation refusal before the extra HPP
  -- target checks; a prior completed return consumes this same allocation.
  if (x->>'qty_pcs')::numeric>a.qty_pcs-coalesce((select sum(ri.qty_pcs)from erp.sales_return_items ri join erp.sales_returns rr on rr.id=ri.return_id
    where rr.status='POSTED'and ri.sale_stock_allocation_id=a.id),0)then raise exception 'AH_RETURN_EXCEEDS_ORIGINAL_ALLOCATION';end if;
  if owned<0 or sold-returned<(select sum((v->>'qty_pcs')::numeric)from jsonb_array_elements(p_legacy->'items')v
   join erp.sale_stock_allocations s on s.id=(v->>'allocation_id')::uuid where s.lot_id=a.lot_id)then raise exception 'CP7_CREDIT_RETURN_QTY_SOURCE_INVALID';end if;
  items:=items||jsonb_build_array(x||jsonb_build_object('product_id',a.product_id,'lot_id',a.lot_id,'po_id',a.po_id,
   'hpp_version_id',a.hpp_id,'unit_hpp_raw',cost::text,'unit_hpp_snapshot',a.current_unit_snapshot::text));
 end loop;
 for r in select distinct case when z->>'po_id'is null then(z->>'product_id')::uuid end product_id,
  (z->>'po_id')::uuid po_id from jsonb_array_elements(scope_items)z
  order by po_id nulls first,product_id loop
  saved_state:=null;
  source_support:=cp7_credit.initial_hpp_support_v1(r.product_id,r.po_id);
  opening_source:=cp7_credit.initial_opening_hpp_source_v1(r.product_id,r.po_id);
  if r.po_id is null then
   select *into strict t from erp.compute_non_po_product_hpp_targets_v2620f(r.product_id);
   select coalesce(sum(l.debit-l.credit)filter(where l.account_id=fg_account),0)fg_value,
    coalesce(sum(l.debit-l.credit)filter(where l.account_id=cogs_account),0)cogs_value,
    coalesce(sum(l.debit-l.credit)filter(where l.account_id in(expense_account,income_account)),0)other_out_value
   into b from erp.journal_lines l join erp.journal_entries j on j.id=l.journal_entry_id left join erp.journal_entries o on o.id=j.reversal_of_id
    where l.product_id=r.product_id and l.po_id is null and j.status in('POSTED','REVERSED')
     and(j.source_type<>'PRODUCT_CONVERSION'or erp.be_nonpo_admitted_v1(j.source_id))
     and(j.source_type<>'JOURNAL_REVERSAL'or o.source_type is distinct from'PRODUCT_CONVERSION'or erp.be_nonpo_admitted_v1(o.source_id));
   if round(t.fg_value,2)<>b.fg_value or round(t.cogs_value,2)<>b.cogs_value or round(t.other_out_value,2)<>b.other_out_value then
    raise exception 'CP7_CREDIT_HPP_TARGET_BOOK_NOT_RECONCILED';end if;
   actual_book:=to_jsonb(b)||jsonb_build_object('hpp_total_cost',b.fg_value+b.cogs_value+b.other_out_value);
  else
   -- PO groups are emitted once, and the source is the actual Native book
   -- reader's safe private equivalent, not the possibly stale cache alone.
   select *into strict t from erp.compute_po_hpp_gl_targets_v2620d(r.po_id);
   select to_jsonb(st)into strict saved_state from erp.po_hpp_gl_state st where st.po_id=r.po_id;
   if t.base_output_qty is distinct from(saved_state->>'base_output_qty')::integer
    or t.hpp_total_cost is distinct from(saved_state->>'hpp_total_cost')::numeric
    or t.fg_value is distinct from(saved_state->>'fg_value')::numeric or t.cogs_value is distinct from(saved_state->>'cogs_value')::numeric
    or t.other_out_value is distinct from(saved_state->>'other_out_value')::numeric then
    raise exception 'CP7_CREDIT_HPP_TARGET_BOOK_NOT_RECONCILED';end if;
   actual_book:=cp7_credit.initial_po_hpp_book_v1(r.po_id,fg_account,cogs_account,expense_account,income_account);
   select (actual_book->>'hpp_total_cost')::numeric hpp_total_cost,(actual_book->>'fg_value')::numeric fg_value,
    (actual_book->>'cogs_value')::numeric cogs_value,(actual_book->>'other_out_value')::numeric other_out_value into b;
   if round(t.hpp_total_cost,2)<>b.hpp_total_cost or round(t.fg_value,2)<>b.fg_value or round(t.cogs_value,2)<>b.cogs_value
    or round(t.other_out_value,2)<>b.other_out_value then raise exception 'CP7_CREDIT_HPP_TARGET_BOOK_NOT_RECONCILED';end if;
  end if;
  before_profile:=cp7_credit.initial_hpp_targets_v1(r.product_id,r.po_id,items,false);
  after_profile:=cp7_credit.initial_hpp_targets_v1(r.product_id,r.po_id,items,true);
  before_target:=before_profile->'target';after_target:=after_profile->'target';
  if before_target is distinct from to_jsonb(t)then raise exception 'CP7_CREDIT_HPP_CANONICAL_TARGET_MISMATCH';end if;
  if exists(select 1 from jsonb_array_elements(before_profile->'lots')f where(f->>'unit_raw')::text in('NaN','Infinity','-Infinity')
   or(f->>'raw_total')::text in('NaN','Infinity','-Infinity')or(f->>'unit_raw')::numeric<0
   or(f->>'owned_qty')::numeric<0 or(f->>'sold_qty')::numeric-(f->>'returned_qty')::numeric<(f->>'requested_qty')::numeric)then
   raise exception 'CP7_CREDIT_RETURN_QTY_SOURCE_INVALID';end if;
  delta_fg:=(after_target->>'fg_value')::numeric-b.fg_value;
  delta_cogs:=(after_target->>'cogs_value')::numeric-b.cogs_value;
  delta_other:=(after_target->>'other_out_value')::numeric-b.other_out_value;
  if cp7_credit.initial_hpp_support_v1(r.product_id,r.po_id)is distinct from source_support then
   raise exception 'CP7_CREDIT_HPP_SUPPORT_CHANGED_DURING_READ';end if;
  if cp7_credit.initial_opening_hpp_source_v1(r.product_id,r.po_id)is distinct from opening_source then
   raise exception 'CP7_CREDIT_OPENING_HPP_SOURCE_CHANGED_DURING_READ';end if;
  if delta_fg+delta_cogs+delta_other<>0 or(after_target->>'hpp_total_cost')::numeric<>(before_target->>'hpp_total_cost')::numeric
   or r.po_id is not null and(delta_fg<0 or delta_cogs>0)then raise exception 'CP7_CREDIT_HPP_VECTOR_NOT_CONSERVED';end if;
  group_amount:=greatest(delta_fg,0)+greatest(delta_cogs,0)+greatest(delta_other,0);hpp:=hpp+group_amount;
  groups:=groups||jsonb_build_array(jsonb_build_object('product_id',case when r.po_id is null then r.product_id end,'po_id',r.po_id,
   'amount',cp7_credit.cent_text(group_amount),'before_target',before_target,'after_target',after_target,'before_book',actual_book,'before_saved_state',saved_state,
   'before_profile',before_profile,'after_profile',after_profile,'source_support',source_support,'opening_source',opening_source,
   'delta',jsonb_build_object('fg_value',delta_fg,'cogs_value',delta_cogs,'other_out_value',delta_other)));
  for x in select *from jsonb_array_elements(jsonb_build_array(
   jsonb_build_object('mapping_key','FG_INVENTORY','signed_amount',delta_fg),jsonb_build_object('mapping_key','COGS','signed_amount',delta_cogs),
   jsonb_build_object('mapping_key',case when delta_other>0 then'OTHER_EXPENSE'else'OTHER_INCOME'end,'signed_amount',delta_other)))loop
   if(x->>'signed_amount')::numeric<>0 then lines:=lines||jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
    'mapping_key',x->>'mapping_key','debit',greatest((x->>'signed_amount')::numeric,0),'credit',greatest(-(x->>'signed_amount')::numeric,0),
    'product_id',case when r.po_id is null then r.product_id end,'po_id',r.po_id)));end if;
  end loop;
 end loop;
 -- The existing source-bound NO_JOURNAL reader proves physical snapshot0.
 -- Do not silently widen it for positive-cost stock with a zero cent vector.
 if hpp=0 and(select coalesce(sum((v->>'refund_amount')::numeric),0)from jsonb_array_elements(items)v)=0
  and exists(select 1 from jsonb_array_elements(items)v where(v->>'unit_hpp_snapshot')::numeric>0)then
  raise exception 'CP7_CREDIT_POSITIVE_HPP_ZERO_VECTOR_UNPROVEN';end if;
 return jsonb_build_object('items',items,'groups',groups,'hpp_amount',cp7_credit.cent_text(hpp),'lines',lines,
  'economic_return_components',component_plan,'locked_lot_ids',to_jsonb(lots),'locked_hpp_version_ids',to_jsonb(versions),'account_facts',account_facts);
end $function$

cp7_sku_conversion.action_v1(text,jsonb,:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.action_v1(p_action text, p_payload jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare a text:=upper(btrim(coalesce(p_action,'')));v jsonb;prior jsonb;part jsonb;child_payload jsonb;child jsonb;
 ids jsonb:='[]'::jsonb;destinations jsonb:='[]'::jsonb;child_id uuid;v_group_id uuid;i int:=0;r record;
begin
 perform erp.require_permission('warehouse.brand_conversion.view');
 if a not in('POST','REVERSE','POST_USAGE','SAVE_REWORK','SAVE_REDYE','SET_REDYE_PRICE')then raise exception 'BE_ACTION_UNKNOWN: tindakan tidak dikenal';end if;
 if not(a='POST'and p_payload?'source_product_id')and not(a='REVERSE'and exists(select 1 from cp7_sku_conversion.members_v1 where conversion_id=(p_payload->>'conversion_id')::uuid))then
  return erp.save_product_conversion_action_v1(p_action,p_payload,p_request);end if;
 perform erp.require_permission('warehouse.brand_conversion.view');perform erp.require_permission(case when a='REVERSE'then 'warehouse.brand_conversion.reverse'else 'warehouse.brand_conversion.post'end);
 if a='REVERSE'then perform erp.require_owner_admin();end if;perform erp.require_internal();
 if p_request is null or jsonb_typeof(p_payload)is distinct from 'object'or octet_length(p_payload::text)>30000 then raise exception 'CP7_SKU_CONVERSION_REQUEST';end if;
 prior:=erp._idempotency_begin('cp7_sku_conversion_v1',p_request,erp._request_hash(jsonb_build_object('action',a,'payload',p_payload)));
 perform erp.require_permission('warehouse.brand_conversion.view');perform erp.require_permission(case when a='REVERSE'then 'warehouse.brand_conversion.reverse'else 'warehouse.brand_conversion.post'end);
 if a='REVERSE'then perform erp.require_owner_admin();end if;perform erp.require_internal();
 if prior is not null then return prior;end if;
 perform erp.pocket_period_lock_v1();perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 perform erp.require_permission('warehouse.brand_conversion.view');perform erp.require_permission(case when a='REVERSE'then 'warehouse.brand_conversion.reverse'else 'warehouse.brand_conversion.post'end);
 if a='REVERSE'then perform erp.require_owner_admin();end if;perform erp.require_internal();
 if a='POST'then
  if not(p_payload?'expected_version')then raise exception 'CP7_SKU_PREVIEW_REQUIRED';end if;
  v:=cp7_sku_conversion.preview_v1(p_payload);
  perform erp.require_permission('warehouse.brand_conversion.view');perform erp.require_permission('warehouse.brand_conversion.post');perform erp.require_internal();
  insert into cp7_sku_conversion.groups_v1(request_id,actor,payload)values(p_request,erp.current_app_user_id(),p_payload);
  perform cp7_sku_conversion.prepare_valuation_v2(p_request,v);
  insert into cp7_sku_conversion.execution_v1(backend_pid,transaction_id,group_id,mode)values(pg_backend_pid(),txid_current(),p_request,'POST');
  for part in select value from jsonb_array_elements(v->'allocations')with ordinality as parts(value,ordinal)order by ordinal loop
   i:=i+1;child_id:=case when i=1 then p_request else gen_random_uuid()end;
   update cp7_sku_conversion.execution_v1 set source_lot_id=(part->>'source_lot_id')::uuid,target_id=(v->>'target_product_id')::uuid,
    location_id=(v->>'location_id')::uuid,qty=(part->>'qty_pcs')::int,physical_at=(v->>'physical_at')::timestamptz
    where backend_pid=pg_backend_pid()and transaction_id=txid_current();
   child_payload:=jsonb_build_object('source_lot_id',part->'source_lot_id','target_product_id',v->'target_product_id','location_id',v->'location_id',
    'qty_pcs',part->'qty_pcs','physical_at',v->'physical_at','reason',p_payload->'reason','expected_version',part->'source_revision');
   if i=1 and p_payload?'expected_returns'then child_payload:=child_payload||jsonb_build_object('expected_returns',p_payload->'expected_returns');end if;
   child:=erp.save_product_conversion_action_v1('POST',child_payload,child_id);
   insert into cp7_sku_conversion.members_v1 values(child_id,p_request,i);
   ids:=ids||jsonb_build_array(child_id);destinations:=destinations||jsonb_build_array(child->'destination_lot_id');
  end loop;
  perform cp7_sku_conversion.finalize_valuation_v2(p_request);
  v:=v||jsonb_build_object('conversion_id',p_request,'destination_lot_id',destinations->0,'conversion_ids',ids,'destination_lot_ids',destinations,'status','POSTED');
 else
  perform erp._cp3_assert_closed_json_object(p_payload,array['conversion_id','reason'],array['conversion_id','reason'],'pembatalan konversi');
  perform erp.bc_text_v1(p_payload,'reason',true,1000);
  select m.group_id into strict v_group_id from cp7_sku_conversion.members_v1 m where m.conversion_id=(p_payload->>'conversion_id')::uuid;
  -- Validate every member before invoking any Native inverse. A rollback of
  -- an earlier member cannot undo Native audit or stock-book nextval calls.
  -- Keep the original BE and Native guards below as the posting authority.
  perform 1 from erp.product_conversions c join cp7_sku_conversion.members_v1 m on m.conversion_id=c.id
   where m.group_id=v_group_id order by c.id for update of c;
  perform erp.require_permission('warehouse.brand_conversion.view');perform erp.require_permission('warehouse.brand_conversion.reverse');
  perform erp.require_owner_admin();perform erp.require_internal();
  if exists(select 1 from cp7_sku_conversion.members_v1 m where m.group_id=v_group_id
   and not exists(select 1 from erp.be_conversion_sources_v1 s where s.conversion_id=m.conversion_id))then
   raise exception 'BE_DOCUMENT_NOT_FOUND';end if;
  if exists(select 1 from cp7_sku_conversion.members_v1 m join erp.be_conversion_cost_sources_v1 s on s.conversion_id=m.conversion_id
   join erp.bc_documents_v1 d on d.id=s.document_id where m.group_id=v_group_id and d.status='POSTED')then
   raise exception 'BE_REVERSE_DEPENDANTS: batalkan dahulu sumber biaya/pemulihan';end if;
  if exists(select 1 from cp7_sku_conversion.members_v1 m join erp.be_conversion_returns_v1 s on s.conversion_id=m.conversion_id
   join erp.bc_return_lots_v1 l on l.outstanding_id=s.outstanding_id join erp.bc_documents_v1 d on d.id=l.document_id
   where m.group_id=v_group_id and d.status='POSTED')then
   raise exception 'BE_REVERSE_DEPENDANTS: batalkan dahulu penerimaan bongkaran';end if;
  if exists(select 1 from cp7_sku_conversion.members_v1 m join erp.product_conversions c on c.id=m.conversion_id
   where m.group_id=v_group_id and c.status not in('POSTED','REVERSED'))then
   raise exception 'Hanya conversion/rebrand POSTED yang dapat direverse';end if;
  if exists(select 1 from cp7_sku_conversion.members_v1 m join erp.product_conversions c on c.id=m.conversion_id
   join erp.product_conversion_allocations a on a.conversion_id=c.id where m.group_id=v_group_id and c.status='POSTED'
   and erp.fg_lot_has_active_downstream(a.destination_lot_id,'REBRAND_IN','PRODUCT_CONVERSION',c.id))then
   raise exception 'Hasil conversion/rebrand masih dipakai transaksi downstream aktif. Reverse transaksi downstream terlebih dahulu.';end if;
  if exists(select 1 from cp7_sku_conversion.members_v1 m join erp.product_conversions c on c.id=m.conversion_id
   where m.group_id=v_group_id and c.status='POSTED'
   and (select coalesce(sum(a.qty_pcs*a.original_hpp_per_pcs),0)::numeric(24,6)from erp.product_conversion_allocations a where a.conversion_id=c.id)>0.005
   and not exists(select 1 from erp.journal_entries j where j.source_type='PRODUCT_CONVERSION'and j.source_id=c.id and j.status='POSTED'))then
   raise exception 'Jurnal conversion/rebrand tidak ditemukan; reversal dibatalkan agar nilai persediaan tidak rusak';end if;
  perform cp7_sku_conversion.assert_group_inverse_capacity_v3(v_group_id);
  insert into cp7_sku_conversion.execution_v1(backend_pid,transaction_id,group_id,mode)values(pg_backend_pid(),txid_current(),v_group_id,'REVERSE');
  for r in select m.conversion_id from cp7_sku_conversion.members_v1 m where m.group_id=v_group_id order by line_no desc loop
   child:=erp.save_product_conversion_action_v1('REVERSE',jsonb_build_object('conversion_id',r.conversion_id,'reason',p_payload->'reason'),
     case when r.conversion_id=(p_payload->>'conversion_id')::uuid then p_request else gen_random_uuid()end);
   ids:=ids||jsonb_build_array(r.conversion_id);
  end loop;
  perform cp7_sku_conversion.reverse_valuation_v2(v_group_id);
  v:=jsonb_build_object('conversion_id',p_payload->'conversion_id','conversion_ids',ids,'status','REVERSED');
 end if;
 delete from cp7_sku_conversion.execution_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current();
 return erp._idempotency_complete('cp7_sku_conversion_v1',p_request,v||jsonb_build_object('request_id',p_request,'action',a));
end $function$

cp7_sku_conversion.finalize_valuation_v2:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.finalize_valuation_v2(p_group uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare q cp7_sku_conversion.valuation_quotes_v2%rowtype;v_native numeric(24,2);v_delta numeric(24,2);v_journal uuid;v_lines jsonb:='[]'::jsonb;r record;
begin
 perform erp.require_internal();perform erp.require_permission('warehouse.brand_conversion.post');
 select *into strict q from cp7_sku_conversion.valuation_quotes_v2 where group_id=p_group;
 if exists(select 1 from cp7_sku_conversion.valuation_postings_v2 where group_id=p_group and phase='POST')then raise exception 'CP7_SKU_MOVAVG_ALREADY_FINALIZED';end if;
 select round(coalesce(sum(a.qty_pcs*a.original_hpp_per_pcs),0),2)into v_native from cp7_sku_conversion.members_v1 m
 join erp.product_conversion_allocations a on a.conversion_id=m.conversion_id where m.group_id=p_group;
 v_delta:=q.transfer_value-v_native;
 with effective as(select po_id,sum(transfer_value)::numeric effective from(
  select po_id,transfer_value from cp7_sku_conversion.valuation_contributors_v2 where group_id=p_group
  union all select po_id,transfer_value from cp7_sku_conversion.cost_contributors_v3 where group_id=p_group)c group by po_id),
 legacy as(select l.po_id,round(sum(a.qty_pcs*a.original_hpp_per_pcs),2)::numeric legacy from cp7_sku_conversion.members_v1 m
  join erp.product_conversion_allocations a on a.conversion_id=m.conversion_id join erp.fg_lots l on l.id=a.source_lot_id where m.group_id=p_group group by l.po_id),
 keys as(select po_id from effective union select po_id from legacy),
 joined as(select k.po_id,coalesce(e.effective,0)effective,coalesce(l.legacy,0)legacy from keys k
  left join effective e on e.po_id is not distinct from k.po_id
  left join legacy l on l.po_id is not distinct from k.po_id),
 numbered as(select row_number()over(order by po_id nulls last)::integer line_no,*from joined)
 insert into cp7_sku_conversion.valuation_attributions_v2(group_id,phase,side,line_no,po_id,product_id,effective_value_delta,legacy_value_delta,adjustment_delta)
 select p_group,'POST','SOURCE',line_no,po_id,q.source_product_id,-effective,-legacy,legacy-effective from numbered
 union all select p_group,'POST','TARGET',line_no,po_id,q.target_product_id,effective,legacy,effective-legacy from numbered;
 for r in select *from cp7_sku_conversion.valuation_attributions_v2 where group_id=p_group and phase='POST'and side='TARGET'and abs(adjustment_delta)>0.005 order by line_no loop
  v_lines:=v_lines||jsonb_build_array(
   (case when r.adjustment_delta>0 then jsonb_build_object('mapping_key','FG_INVENTORY','debit',r.adjustment_delta,'credit',0)
    else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',abs(r.adjustment_delta))end)
    ||case when r.po_id is null then jsonb_build_object('product_id',q.target_product_id)else jsonb_build_object('po_id',r.po_id)end,
   (case when r.adjustment_delta>0 then jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',r.adjustment_delta)
    else jsonb_build_object('mapping_key','FG_INVENTORY','debit',abs(r.adjustment_delta),'credit',0)end)
    ||case when r.po_id is null then jsonb_build_object('product_id',q.source_product_id)else jsonb_build_object('po_id',r.po_id)end);
 end loop;
 if jsonb_array_length(v_lines)>0 then v_journal:=erp.post_journal('SKU_MOVING_AVERAGE',p_group,(q.physical_at at time zone 'Asia/Jakarta')::date,
  'Koreksi nilai Ganti Merek ke rata-rata SKU/gudang',v_lines);end if;
 insert into cp7_sku_conversion.valuation_postings_v2 values(p_group,'POST',v_native,q.transfer_value,v_delta,v_journal,statement_timestamp());
 with entries as(
  select 'SOURCE'::text side,q.source_product_id product_id,c.root_lot_id,-c.transfer_units::numeric units
  from cp7_sku_conversion.valuation_contributors_v2 c where c.group_id=p_group
  union all
  select 'SOURCE',q.source_product_id,a.source_lot_id,sum(a.qty_pcs)::numeric
  from cp7_sku_conversion.members_v1 m join erp.product_conversion_allocations a on a.conversion_id=m.conversion_id
  where m.group_id=p_group group by a.source_lot_id
  union all
  select 'TARGET',q.target_product_id,a.destination_lot_id,-sum(a.qty_pcs)::numeric
  from cp7_sku_conversion.members_v1 m join erp.product_conversion_allocations a on a.conversion_id=m.conversion_id
  where m.group_id=p_group group by a.destination_lot_id
  union all
  select 'TARGET',q.target_product_id,c.root_lot_id,c.transfer_units::numeric
  from cp7_sku_conversion.valuation_contributors_v2 c where c.group_id=p_group
 ), compact as(
  select side,product_id,root_lot_id,sum(units)::numeric units from entries group by side,product_id,root_lot_id
  having abs(sum(units))>0.000000000001
 ), numbered as(
  select row_number()over(partition by side order by root_lot_id)::integer line_no,*from compact
 )
 insert into cp7_sku_conversion.component_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,root_lot_id,units_delta,physical_at,economic_date)
 select gen_random_uuid(),p_group,'SKU_CONVERSION',p_group,line_no,'POST',side,product_id,q.location_id,q.quality_grade,root_lot_id,units,q.physical_at,
  (q.physical_at at time zone 'Asia/Jakarta')::date from numbered order by side,line_no;
 if exists(select 1 from cp7_sku_conversion.component_events_v2 where group_id=p_group and phase='POST'
  group by side having abs(sum(units_delta))>0.000000000001)then
  raise exception 'CP7_SKU_MOVAVG_COMPONENT_POOL_QTY_NOT_CONSERVED';end if;
 insert into cp7_sku_conversion.valuation_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,qty_delta,effective_value_delta,legacy_value_delta,adjustment_delta,physical_at,economic_date)
 values(gen_random_uuid(),p_group,'SKU_CONVERSION',p_group,1,'POST','SOURCE',q.source_product_id,q.location_id,q.quality_grade,-q.qty_pcs,-q.transfer_value,-v_native,v_native-q.transfer_value,q.physical_at,(q.physical_at at time zone 'Asia/Jakarta')::date),
       (gen_random_uuid(),p_group,'SKU_CONVERSION',p_group,1,'POST','TARGET',q.target_product_id,q.location_id,q.quality_grade,q.qty_pcs,q.transfer_value,v_native,q.transfer_value-v_native,q.physical_at,(q.physical_at at time zone 'Asia/Jakarta')::date);
 if abs((select coalesce(sum(effective_value_delta),0)from cp7_sku_conversion.valuation_events_v2 where group_id=p_group and phase='POST'))>0.000001
 or abs((select coalesce(sum(adjustment_delta),0)from cp7_sku_conversion.valuation_events_v2 where group_id=p_group and phase='POST'))>0.000001 then
  raise exception 'CP7_SKU_MOVAVG_VALUE_NOT_CONSERVED';end if;
 if exists(select 1 from(select po_id,sum(effective_value_delta)effective,sum(legacy_value_delta)legacy,sum(adjustment_delta)adjustment
  from cp7_sku_conversion.valuation_attributions_v2 where group_id=p_group and phase='POST'group by po_id)x
  where abs(effective)>0.005 or abs(legacy)>0.005 or abs(adjustment)>0.005)then raise exception 'CP7_SKU_MOVAVG_ATTRIBUTION_NOT_CONSERVED';end if;
 perform cp7_sku_conversion.transfer_base_money_v4(p_group,false);
 perform cp7_sku_conversion.finalize_costs_v3(p_group);
 perform erp.sync_non_po_product_hpp_to_gl_v2620f(q.source_product_id,(q.physical_at at time zone 'Asia/Jakarta')::date,
  'SKU_COST_CENT_TRANSFER',p_group,'Pembagian sen mengikuti biaya yang berpindah');
 perform erp.sync_non_po_product_hpp_to_gl_v2620f(q.target_product_id,(q.physical_at at time zone 'Asia/Jakarta')::date,
  'SKU_COST_CENT_TRANSFER',p_group,'Pembagian sen mengikuti biaya yang berpindah');
end $function$

cp7_sku_conversion.pool_quote_v2(uuid,uu:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.pool_quote_v2(p_product uuid, p_location uuid, p_grade text DEFAULT 'GRADE_A'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare v_qty numeric(20,6);v_base numeric(24,6);v_adjust numeric(24,6);v_value numeric(24,6);v_attr numeric(24,6);v_unknown boolean;v_revision text;
begin
 if p_product is null or p_location is null or p_grade is distinct from 'GRADE_A' then raise exception 'CP7_SKU_VALUE_SCOPE_REQUIRED';end if;
 with components as materialized(
  select c.*,h.cost_state,l.po_id root_po_id
  from cp7_sku_conversion.pool_components_v2(p_product,p_location,p_grade)c
  join erp.fg_lots l on l.id=c.root_lot_id
  left join erp.hpp_versions h on h.id=c.hpp_version_id
 ), totals as(
  select coalesce(sum(component_units),0)::numeric qty,coalesce(sum(value),0)::numeric value,
   coalesce(bool_or(component_units< -0.000000000001 or hpp_version_id is null or unit_value is null or cost_state='ESTIMATED'
    or erp.bd_lot_laundry_unknown_v1(root_lot_id)
    or(root_po_id is not null and not exists(select 1 from erp.get_hpp_completeness(root_po_id)z where z.pending_reason_count=0))),false) unknown
  from components
 )select qty,round(value,6),unknown into v_qty,v_value,v_unknown from totals;
 if v_unknown then raise exception 'CP7_SKU_POOL_HPP_UNKNOWN: seluruh komponen ekonomi termasuk reservasi harus diketahui';end if;
 v_base:=v_value;
 select coalesce(sum(c.value),0)into v_adjust from cp7_sku_conversion.pool_cost_components_v3(p_product,p_location,p_grade)c;
 v_value:=round(v_base+v_adjust,6);
 if v_value<0 then raise exception 'CP7_SKU_POOL_VALUE_NEGATIVE: nilai efektif persediaan tidak boleh negatif';end if;
 select coalesce(sum(a.value),0)into v_attr from cp7_sku_conversion.pool_attribution_v2(p_product,p_location,p_grade)a;
 if round(v_attr,6)is distinct from v_value then raise exception 'CP7_SKU_POOL_ATTRIBUTION_MISMATCH';end if;
 select md5(jsonb_build_object('product',p_product,'location',p_location,'grade',p_grade,'qty',v_qty,'base',v_base,'adjust',v_adjust,
  'components',(select coalesce(jsonb_agg(to_jsonb(c)order by c.root_lot_id),'[]'::jsonb)
   from cp7_sku_conversion.pool_components_v2(p_product,p_location,p_grade)c),
  'cost_components',(select coalesce(jsonb_agg(to_jsonb(c)order by c.root_lot_id),'[]'::jsonb)
   from cp7_sku_conversion.pool_cost_components_v3(p_product,p_location,p_grade)c),
  'cost_events',(select coalesce(jsonb_agg(to_jsonb(e)order by e.recorded_at,e.id),'[]'::jsonb)
   from cp7_sku_conversion.cost_events_v3 e where e.product_id=p_product and e.location_id=p_location and e.quality_grade=p_grade),
  'base_money',(select coalesce(jsonb_agg(to_jsonb(m)order by m.id),'[]')from cp7_sku_conversion.base_money_events_v4 m
   where m.root_lot_id in(select root_lot_id from cp7_sku_conversion.pool_components_v2(p_product,p_location,p_grade))),
  'events',(select coalesce(jsonb_agg(to_jsonb(e)order by e.recorded_at,e.id),'[]'::jsonb)from cp7_sku_conversion.valuation_events_v2 e
   where e.product_id=p_product and e.location_id=p_location and e.quality_grade=p_grade))::text) into v_revision;
 return jsonb_build_object('state',case when v_qty=0 then 'EMPTY' else 'KNOWN'end,'qty',v_qty::text,'value',v_value::text,
  'average',case when v_qty>0 then (v_value/v_qty)::text end,'base_value',v_base::text,'adjustment',v_adjust::text,
  'reserved_included',true,'basis','SKU_LOCATION_GRADE_MOVING_AVERAGE_V2','revision',v_revision);
end $function$

cp7_sku_conversion.prepare_return_values:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.prepare_return_values_v2(p_return uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare r record;v_value numeric(24,2);v_legacy numeric(24,2);v_line integer:=0;pool record;v_components jsonb;
begin
 perform erp.require_internal();
 if exists(select 1 from cp7_sku_conversion.sales_return_values_v2 where return_id=p_return)then raise exception 'CP7_SKU_RETURN_VALUE_ALREADY_PREPARED';end if;
 for r in select i.id,i.return_id,i.sale_stock_allocation_id,i.product_id,i.lot_id,i.location_id,i.quality_grade,i.qty_pcs,
   a.qty_pcs sold_qty,h.hpp_per_pcs
  from erp.sales_return_items i join cp7_sku_conversion.sale_allocation_values_v2 a on a.sale_stock_allocation_id=i.sale_stock_allocation_id
  join erp.hpp_versions h on h.lot_id=i.lot_id and h.is_current
  where i.return_id=p_return order by i.sale_stock_allocation_id,i.id loop
  -- Pending rows of this draft are included explicitly, while the shared
  -- owned projection excludes draft effects. Every financial scope therefore
  -- receives exactly its current cumulative FG target change, including the
  -- cent carried from earlier returns, other allocations, reversals or recost.
  with raw as(
   select 'BASE'::text kind,*from cp7_sku_conversion.return_components_v2(r.sale_stock_allocation_id,r.qty_pcs,p_return)
   union all select 'COST',*from cp7_sku_conversion.return_cost_components_v3(r.sale_stock_allocation_id,r.qty_pcs,p_return)
  ), scoped as(
   select po_id,sum(component_units*hpp_per_pcs)::numeric added_value from raw where component_units>0 group by po_id
  ), before_values as(
   select k.po_id,k.added_value,cp7_sku_conversion.owned_scope_value_v2(r.product_id,k.po_id)
    +coalesce((select sum(c.component_units*cp7_sku_conversion.base_current_unit_v4(c.root_lot_id,v.product_id))
      from cp7_sku_conversion.sales_return_components_v2 c join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
      join erp.hpp_versions h on h.lot_id=c.root_lot_id and h.is_current
      where v.return_id=p_return and c.po_id is not distinct from k.po_id
       and(k.po_id is not null or v.product_id=r.product_id)),0)
    +coalesce((select sum(c.component_units*cp7_sku_conversion.cost_current_unit_v3(c.root_lot_id,v.product_id))from cp7_sku_conversion.return_cost_components_v3 c
      join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
      cross join lateral cp7_sku_conversion.cost_root_v3(c.root_lot_id)cr
      where v.return_id=p_return and c.po_id is not distinct from k.po_id
       and(k.po_id is not null or v.product_id=r.product_id)),0)::numeric before_value
   from scoped k
  ), scope_cents as(
   select po_id,added_value,round(before_value+added_value,2)-round(before_value,2)effective_value from before_values
  ), ranked as(
   select c.*,k.effective_value,k.added_value,
    sum(c.component_units*c.hpp_per_pcs)over(partition by c.po_id order by c.kind,c.root_lot_id rows unbounded preceding)cumulative_raw
   from raw c join scope_cents k on k.po_id is not distinct from c.po_id where c.component_units>0
  ), targets as(
   select *,case when effective_value=0 then 0 else round(cumulative_raw*effective_value/nullif(added_value,0),2)end cumulative_target from ranked
  ), shares as(
   select row_number()over(order by kind,root_lot_id)::integer line_no,kind,root_lot_id,po_id,component_units,
    cumulative_target-coalesce(lag(cumulative_target)over(partition by po_id order by kind,root_lot_id),0)booked_value from targets
  )select coalesce(jsonb_agg(to_jsonb(shares)order by line_no),'[]'::jsonb),coalesce(sum(booked_value),0)
    into v_components,v_value from shares;
  v_legacy:=round(r.qty_pcs*r.hpp_per_pcs,2);
  insert into cp7_sku_conversion.sales_return_values_v2(sales_return_item_id,return_id,sale_stock_allocation_id,product_id,lot_id,location_id,quality_grade,qty_pcs,effective_value,legacy_value,effective_unit_value)
  values(r.id,p_return,r.sale_stock_allocation_id,r.product_id,r.lot_id,r.location_id,r.quality_grade,r.qty_pcs,v_value,v_legacy,v_value/r.qty_pcs);
  insert into cp7_sku_conversion.sales_return_components_v2(sales_return_item_id,line_no,root_lot_id,po_id,component_units,booked_value)
  select r.id,c.line_no,c.root_lot_id,c.po_id,c.component_units,c.booked_value
   from jsonb_to_recordset(v_components)as c(line_no integer,kind text,root_lot_id uuid,po_id uuid,component_units numeric,booked_value numeric)where c.kind='BASE'order by c.line_no;
  insert into cp7_sku_conversion.return_cost_components_v3(sales_return_item_id,line_no,root_lot_id,po_id,component_units,booked_value)
  select r.id,c.line_no,c.root_lot_id,c.po_id,c.component_units,c.booked_value from jsonb_to_recordset(v_components)
   as c(line_no integer,kind text,root_lot_id uuid,po_id uuid,component_units numeric,booked_value numeric)where c.kind='COST'order by c.line_no;
  if abs(r.qty_pcs-coalesce((select sum(c.component_units)from cp7_sku_conversion.sales_return_components_v2 c where c.sales_return_item_id=r.id),0))>0.000000000001
   or v_value is distinct from(select sum(c.booked_value)from(select booked_value from cp7_sku_conversion.sales_return_components_v2 where sales_return_item_id=r.id union all select booked_value from cp7_sku_conversion.return_cost_components_v3 where sales_return_item_id=r.id)c)then
   raise exception 'CP7_SKU_RETURN_COMPONENT_MISMATCH';end if;
  with economic as(
   select po_id,sum(booked_value)::numeric effective from(
    select po_id,booked_value from cp7_sku_conversion.sales_return_components_v2 where sales_return_item_id=r.id
    union all select po_id,booked_value from cp7_sku_conversion.return_cost_components_v3 where sales_return_item_id=r.id)c group by po_id
  ), keys as(
   select po_id from economic union select l.po_id from erp.fg_lots l where l.id=r.lot_id
  ), numbered as(
   select row_number()over(order by k.po_id nulls last)::integer line_no,k.po_id,coalesce(e.effective,0)::numeric effective,
    case when k.po_id is not distinct from l.po_id then v_legacy else 0 end::numeric legacy
   from keys k left join economic e on e.po_id is not distinct from k.po_id cross join erp.fg_lots l where l.id=r.lot_id
  )
  insert into cp7_sku_conversion.sales_return_attributions_v2(sales_return_item_id,line_no,po_id,product_id,location_id,quality_grade,effective_value,legacy_value,adjustment_delta)
  select r.id,line_no,po_id,r.product_id,r.location_id,r.quality_grade,effective,legacy,effective-legacy from numbered order by line_no;
  if v_value is distinct from(select sum(a.effective_value)from cp7_sku_conversion.sales_return_attributions_v2 a where a.sales_return_item_id=r.id)
   or v_legacy is distinct from(select sum(a.legacy_value)from cp7_sku_conversion.sales_return_attributions_v2 a where a.sales_return_item_id=r.id)then
   raise exception 'CP7_SKU_RETURN_ATTRIBUTION_MISMATCH';end if;
 end loop;
 for pool in select product_id,location_id,quality_grade,sum(qty_pcs)::numeric qty,sum(effective_value)::numeric effective,sum(legacy_value)::numeric legacy
  from cp7_sku_conversion.sales_return_values_v2 where return_id=p_return group by product_id,location_id,quality_grade order by product_id,location_id,quality_grade loop
  v_line:=v_line+1;
  insert into cp7_sku_conversion.valuation_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,qty_delta,effective_value_delta,legacy_value_delta,adjustment_delta,physical_at,economic_date)
  select gen_random_uuid(),null,'SALES_RETURN',p_return,v_line,'POST','POOL',pool.product_id,pool.location_id,pool.quality_grade,pool.qty,pool.effective,pool.legacy,
   pool.effective-pool.legacy,h.physical_at,(h.physical_at at time zone 'Asia/Jakarta')::date from erp.sales_returns h where h.id=p_return;
 end loop;
 with entries as(
  select v.product_id,v.location_id,v.quality_grade,c.root_lot_id,c.component_units::numeric units
  from cp7_sku_conversion.sales_return_components_v2 c join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
  where v.return_id=p_return
  union all
  select v.product_id,v.location_id,v.quality_grade,v.lot_id,-v.qty_pcs::numeric
  from cp7_sku_conversion.sales_return_values_v2 v where v.return_id=p_return
 ), compact as(
  select product_id,location_id,quality_grade,root_lot_id,sum(units)::numeric units from entries
  group by product_id,location_id,quality_grade,root_lot_id having abs(sum(units))>0.000000000001
 ), numbered as(
  select row_number()over(order by product_id,location_id,quality_grade,root_lot_id)::integer line_no,*from compact
 )
 insert into cp7_sku_conversion.component_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,root_lot_id,units_delta,physical_at,economic_date)
 select gen_random_uuid(),null,'SALES_RETURN',p_return,line_no,'POST','POOL',product_id,location_id,quality_grade,root_lot_id,units,h.physical_at,
  (h.physical_at at time zone 'Asia/Jakarta')::date from numbered cross join erp.sales_returns h where h.id=p_return order by line_no;
 if exists(select 1 from cp7_sku_conversion.component_events_v2 where source_type='SALES_RETURN'and source_id=p_return and phase='POST'
  group by product_id,location_id,quality_grade having abs(sum(units_delta))>0.000000000001)then
  raise exception 'CP7_SKU_RETURN_COMPONENT_QTY_NOT_CONSERVED';end if;
 perform cp7_sku_conversion.post_return_costs_v3(p_return);
end $function$

cp7_sku_conversion.prepare_valuation_v2(:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.prepare_valuation_v2(p_group uuid, p_preview jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare s jsonb;t jsonb;v_qty integer:=(p_preview->>'qty_pcs')::integer;v_transfer numeric(24,2);v_revision text;v_enrolled jsonb;
begin
 perform erp.require_internal();perform erp.require_permission('warehouse.brand_conversion.post');
 if p_group is null then raise exception 'CP7_SKU_MOVAVG_PREVIEW_REQUIRED';end if;
 s:=cp7_sku_conversion.pool_quote_v2((p_preview->>'source_product_id')::uuid,(p_preview->>'location_id')::uuid,'GRADE_A');
 t:=cp7_sku_conversion.pool_quote_v2((p_preview->>'target_product_id')::uuid,(p_preview->>'location_id')::uuid,'GRADE_A');
 if (s->>'revision')is distinct from(p_preview->>'source_value_revision')or(t->>'revision')is distinct from(p_preview->>'target_value_revision')then
  raise exception 'STALE_VERSION: nilai rata-rata sumber atau tujuan berubah; periksa pratinjau terbaru';end if;
 perform cp7_sku_conversion.prepare_base_money_v4(p_preview);
 v_enrolled:=cp7_sku_conversion.pool_quote_v2((p_preview->>'source_product_id')::uuid,(p_preview->>'location_id')::uuid,'GRADE_A');
 if v_enrolled->'qty'is distinct from s->'qty'or v_enrolled->'value'is distinct from s->'value'
  or v_enrolled->'base_value'is distinct from s->'base_value'
  or round(v_qty*(v_enrolled->>'average')::numeric,2)is distinct from round(v_qty*(s->>'average')::numeric,2)then
  raise exception 'CP7_SKU_BASE_ENROLLMENT_PREVIEW_VALUE_CHANGED';end if;
 v_transfer:=round(v_qty*(s->>'average')::numeric,2);
 v_revision:=md5(jsonb_build_object('source',s->>'revision','target',t->>'revision','qty',v_qty,'transfer',v_transfer)::text);
 insert into cp7_sku_conversion.valuation_quotes_v2(group_id,source_product_id,target_product_id,location_id,quality_grade,qty_pcs,physical_at,
  source_before_qty,source_before_value,source_before_average,target_before_qty,target_before_value,target_before_average,transfer_value,valuation_revision)
 values(p_group,(p_preview->>'source_product_id')::uuid,(p_preview->>'target_product_id')::uuid,(p_preview->>'location_id')::uuid,'GRADE_A',v_qty,
  (p_preview->>'physical_at')::timestamptz,(s->>'qty')::numeric,(s->>'value')::numeric,(s->>'average')::numeric,
  (t->>'qty')::numeric,(t->>'value')::numeric,case when t->>'average' is null then null else(t->>'average')::numeric end,v_transfer,v_revision);
 with components as materialized(
  select 'BASE'::text kind,c.line_no,c.root_lot_id,c.po_id,c.hpp_version_id,c.component_units pool_component_units,c.unit_value,c.value contributed_value,
   c.component_units*v_qty/(s->>'qty')::numeric transfer_units,
   c.component_units*v_qty/(s->>'qty')::numeric*c.unit_value transfer_raw_value
  from cp7_sku_conversion.pool_components_v2((p_preview->>'source_product_id')::uuid,(p_preview->>'location_id')::uuid,'GRADE_A')c
  union all
  select 'COST',c.line_no,c.root_lot_id,c.po_id,c.hpp_version_id,c.component_units,c.unit_value,c.value,
   round(c.component_units*v_qty/(s->>'qty')::numeric,12),round(c.component_units*v_qty/(s->>'qty')::numeric,12)*c.unit_value
  from cp7_sku_conversion.pool_cost_components_v3((p_preview->>'source_product_id')::uuid,(p_preview->>'location_id')::uuid,'GRADE_A')c
 ), ranked as(
  select c.*,sum(transfer_raw_value)over(order by kind,line_no rows unbounded preceding)cumulative_value,
   sum(transfer_raw_value)over() total_raw_value
  from components c
 ), targets as(
  select r.*,case when total_raw_value=0 then round(cumulative_value,2)else round(cumulative_value*v_transfer/total_raw_value,2)end cumulative_target
  from ranked r
 ), shares as(
  select t.*,cumulative_target-coalesce(lag(cumulative_target)over(order by kind,line_no),0)transfer_share from targets t
 ),saved_base as(
  insert into cp7_sku_conversion.valuation_contributors_v2(group_id,line_no,root_lot_id,po_id,hpp_version_id,pool_component_units,transfer_units,unit_value,contributed_value,transfer_value)
  select p_group,line_no,root_lot_id,po_id,hpp_version_id,pool_component_units,transfer_units,unit_value,contributed_value,transfer_share from shares where kind='BASE'order by line_no returning group_id
 )insert into cp7_sku_conversion.cost_contributors_v3(group_id,line_no,root_lot_id,po_id,hpp_version_id,pool_component_units,transfer_units,unit_value,contributed_value,transfer_value)
 select p_group,line_no,root_lot_id,po_id,hpp_version_id,pool_component_units,transfer_units,unit_value,contributed_value,transfer_share from shares where kind='COST'and transfer_units>0 order by line_no;
 if (select round(sum(contributed_value),6)from cp7_sku_conversion.valuation_contributors_v2 where group_id=p_group)
    is distinct from round((s->>'base_value')::numeric,6) then raise exception 'CP7_SKU_MOVAVG_CONTRIBUTOR_MISMATCH';end if;
 if (select coalesce(sum(transfer_value),0)from(
  select transfer_value from cp7_sku_conversion.valuation_contributors_v2 where group_id=p_group
  union all select transfer_value from cp7_sku_conversion.cost_contributors_v3 where group_id=p_group)c)
    is distinct from v_transfer then raise exception 'CP7_SKU_MOVAVG_CONTRIBUTOR_CENT_MISMATCH';end if;
 if abs((select coalesce(sum(transfer_units),0)from cp7_sku_conversion.valuation_contributors_v2 where group_id=p_group)-v_qty)>0.000000000001
    then raise exception 'CP7_SKU_MOVAVG_COMPONENT_QTY_MISMATCH';end if;
end $function$

cp7_sku_conversion.return_components_v2(:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.return_components_v2(p_allocation uuid, p_qty numeric, p_current_return uuid)
 RETURNS TABLE(root_lot_id uuid, po_id uuid, component_units numeric, hpp_per_pcs numeric, hpp_version_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare v_sold numeric;v_prior numeric;v_plan jsonb;v_legacy boolean;v_product uuid;
begin
 perform erp.require_internal();
 if p_qty is null or p_qty<=0 or p_qty<>trunc(p_qty)or p_qty::text in('NaN','Infinity','-Infinity')then
  raise exception 'CP7_SKU_RETURN_COMPONENT_QTY_INVALID';end if;
 select v.qty_pcs,v.product_id into v_sold,v_product from cp7_sku_conversion.sale_allocation_values_v2 v where v.sale_stock_allocation_id=p_allocation;
 v_legacy:=not found;
 if v_legacy then select a.qty_pcs,l.product_id into strict v_sold,v_product from erp.sale_stock_allocations a join erp.fg_lots l on l.id=a.lot_id where a.id=p_allocation;end if;
 select coalesce(sum(i.qty_pcs),0)into v_prior from erp.sales_return_items i join erp.sales_returns h on h.id=i.return_id
  where i.sale_stock_allocation_id=p_allocation and h.status='POSTED';
 if p_current_return is not null then
  v_prior:=v_prior+coalesce((select sum(v.qty_pcs)from cp7_sku_conversion.sales_return_values_v2 v
   where v.sale_stock_allocation_id=p_allocation and v.return_id=p_current_return),0);
 end if;
 if v_prior+p_qty>v_sold then raise exception 'CP7_SKU_RETURN_VALUE_EXCEEDS_SALE_ALLOCATION';end if;
 with prior as(
  select c.root_lot_id,sum(c.component_units)::numeric units from cp7_sku_conversion.sales_return_components_v2 c
  join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)join erp.sales_returns h on h.id=v.return_id
  where v.sale_stock_allocation_id=p_allocation and(h.status='POSTED'or h.id=p_current_return)group by c.root_lot_id
 ), planned as(
  select c.root_lot_id,c.po_id,((v_prior+p_qty)*c.component_units/v_sold-coalesce(p.units,0))::numeric(30,12) units
  from cp7_sku_conversion.sale_allocation_components_v2 c left join prior p on p.root_lot_id=c.root_lot_id
  where c.sale_stock_allocation_id=p_allocation and not v_legacy
  union all select a.lot_id,l.po_id,p_qty::numeric(30,12)from erp.sale_stock_allocations a join erp.fg_lots l on l.id=a.lot_id
   where a.id=p_allocation and v_legacy
 )select coalesce(jsonb_agg(jsonb_build_object('root_lot_id',p.root_lot_id,'po_id',p.po_id,'component_units',p.units,
   'hpp_per_pcs',case when h.id is null or h.cost_state='ESTIMATED'then h.hpp_per_pcs else cp7_sku_conversion.base_current_unit_v4(p.root_lot_id,v_product)end,'hpp_version_id',h.id,'root_po_id',l.po_id,'cost_state',h.cost_state,
   'laundry_unknown',erp.bd_lot_laundry_unknown_v1(p.root_lot_id))order by p.root_lot_id),'[]')into v_plan
 from planned p left join erp.fg_lots l on l.id=p.root_lot_id left join erp.hpp_versions h on h.lot_id=p.root_lot_id and h.is_current;
 if exists(select 1 from jsonb_array_elements(v_plan)c where c->>'hpp_version_id'is null or c->>'hpp_per_pcs'is null
  or c->>'cost_state'='ESTIMATED'or(c->>'laundry_unknown')::boolean
  or(c->>'hpp_per_pcs')::numeric<0 or c->>'hpp_per_pcs'in('NaN','Infinity','-Infinity')
  or c->'po_id'is distinct from c->'root_po_id')then raise exception 'CP7_SKU_RETURN_COMPONENT_HPP_UNKNOWN';end if;
 if exists(select 1 from jsonb_array_elements(v_plan)c where(c->>'component_units')::numeric<0)
  or abs(p_qty-coalesce((select sum((c->>'component_units')::numeric)from jsonb_array_elements(v_plan)c),0))>0.000000000001 then
  raise exception 'CP7_SKU_RETURN_COMPONENT_MISMATCH';end if;
 return query select c.root_lot_id,c.po_id,c.component_units,c.hpp_per_pcs,c.hpp_version_id
  from jsonb_to_recordset(v_plan)c(root_lot_id uuid,po_id uuid,component_units numeric,hpp_per_pcs numeric,hpp_version_id uuid)
  where c.component_units>0 order by c.root_lot_id;
end $function$

cp7_sku_conversion.reverse_valuation_v2(:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.reverse_valuation_v2(p_group uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare q cp7_sku_conversion.valuation_quotes_v2%rowtype;p cp7_sku_conversion.valuation_postings_v2%rowtype;v_journal uuid;v_delta numeric(24,2);v_lines jsonb:='[]'::jsonb;r record;v_inverse_before jsonb;
begin
 perform erp.require_internal();perform erp.require_permission('warehouse.brand_conversion.reverse');perform erp.require_owner_admin();
 select *into strict q from cp7_sku_conversion.valuation_quotes_v2 where group_id=p_group;
 select *into strict p from cp7_sku_conversion.valuation_postings_v2 where group_id=p_group and phase='POST';
 if exists(select 1 from cp7_sku_conversion.valuation_postings_v2 where group_id=p_group and phase='REVERSE')then raise exception 'CP7_SKU_MOVAVG_ALREADY_REVERSED';end if;
 v_inverse_before:=cp7_sku_conversion.capture_group_inverse_v3(p_group);
 v_delta:=-p.correction_value;
 insert into cp7_sku_conversion.valuation_attributions_v2(group_id,phase,side,line_no,po_id,product_id,effective_value_delta,legacy_value_delta,adjustment_delta,supersedes_phase)
 select group_id,'REVERSE',side,line_no,po_id,product_id,-effective_value_delta,-legacy_value_delta,-adjustment_delta,'POST'
 from cp7_sku_conversion.valuation_attributions_v2 where group_id=p_group and phase='POST';
 for r in select *from cp7_sku_conversion.valuation_attributions_v2 where group_id=p_group and phase='REVERSE'and side='TARGET'and abs(adjustment_delta)>0.005 order by line_no loop
  v_lines:=v_lines||jsonb_build_array(
   (case when r.adjustment_delta>0 then jsonb_build_object('mapping_key','FG_INVENTORY','debit',r.adjustment_delta,'credit',0)
    else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',abs(r.adjustment_delta))end)
    ||case when r.po_id is null then jsonb_build_object('product_id',q.target_product_id)else jsonb_build_object('po_id',r.po_id)end,
   (case when r.adjustment_delta>0 then jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',r.adjustment_delta)
    else jsonb_build_object('mapping_key','FG_INVENTORY','debit',abs(r.adjustment_delta),'credit',0)end)
    ||case when r.po_id is null then jsonb_build_object('product_id',q.source_product_id)else jsonb_build_object('po_id',r.po_id)end);
 end loop;
 if jsonb_array_length(v_lines)>0 then v_journal:=erp.post_journal('SKU_MOVING_AVERAGE_REVERSAL',p_group,(statement_timestamp()at time zone 'Asia/Jakarta')::date,
  'Pembalikan koreksi nilai Ganti Merek rata-rata SKU/gudang',v_lines);end if;
 insert into cp7_sku_conversion.valuation_postings_v2 values(p_group,'REVERSE',-p.native_value,-p.transfer_value,v_delta,v_journal,statement_timestamp());
 perform cp7_sku_conversion.transfer_base_money_v4(p_group,true);
 insert into cp7_sku_conversion.component_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,root_lot_id,units_delta,physical_at,economic_date,supersedes_event_id)
 select gen_random_uuid(),group_id,source_type,source_id,line_no,'REVERSE',side,product_id,location_id,quality_grade,root_lot_id,-units_delta,
  statement_timestamp(),(statement_timestamp()at time zone 'Asia/Jakarta')::date,id
 from cp7_sku_conversion.component_events_v2 where group_id=p_group and phase='POST'order by side,line_no;
 if exists(select 1 from cp7_sku_conversion.component_events_v2 where group_id=p_group
  group by side,root_lot_id having abs(sum(units_delta))>0.000000000001)then
  raise exception 'CP7_SKU_MOVAVG_COMPONENT_REVERSE_NOT_EXACT';end if;
 insert into cp7_sku_conversion.valuation_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,qty_delta,effective_value_delta,legacy_value_delta,adjustment_delta,physical_at,economic_date)
 values(gen_random_uuid(),p_group,'SKU_CONVERSION',p_group,1,'REVERSE','SOURCE',q.source_product_id,q.location_id,q.quality_grade,q.qty_pcs,q.transfer_value,p.native_value,q.transfer_value-p.native_value,statement_timestamp(),(statement_timestamp()at time zone 'Asia/Jakarta')::date),
       (gen_random_uuid(),p_group,'SKU_CONVERSION',p_group,1,'REVERSE','TARGET',q.target_product_id,q.location_id,q.quality_grade,-q.qty_pcs,-q.transfer_value,-p.native_value,p.native_value-q.transfer_value,statement_timestamp(),(statement_timestamp()at time zone 'Asia/Jakarta')::date);
 if abs((select coalesce(sum(effective_value_delta),0)from cp7_sku_conversion.valuation_events_v2 where group_id=p_group))>0.000001
 or abs((select coalesce(sum(adjustment_delta),0)from cp7_sku_conversion.valuation_events_v2 where group_id=p_group))>0.000001 then
  raise exception 'CP7_SKU_MOVAVG_REVERSE_NOT_CONSERVED';end if;
 perform cp7_sku_conversion.reverse_costs_v3('SKU_CONVERSION',p_group);
 perform cp7_sku_conversion.rebalance_group_inverse_v3(p_group,v_inverse_before);
end $function$

cp7_sku_conversion.status_component_reve:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.status_component_reverse_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare v_type text;v_id uuid;v_components boolean;v_values boolean;
begin
 if old.status is not distinct from new.status or new.status is distinct from 'REVERSED'then return new;end if;
 if tg_table_schema<>'erp'or tg_table_name not in('sales_headers','sales_returns')then raise exception 'CP7_SKU_COMPONENT_TRIGGER_SCOPE';end if;
 v_type:=case when tg_table_name='sales_headers'then'SALE'else'SALES_RETURN'end;v_id:=new.id;
 perform cp7_sku_conversion.reverse_costs_v3(v_type,v_id);
 select exists(select 1 from cp7_sku_conversion.component_events_v2 where source_type=v_type and source_id=v_id and phase='POST')into v_components;
 select exists(select 1 from cp7_sku_conversion.valuation_events_v2 where source_type=v_type and source_id=v_id and phase='POST')into v_values;
 if not v_components and not v_values then return new;end if;
 if exists(select 1 from cp7_sku_conversion.component_events_v2 where source_type=v_type and source_id=v_id and phase='REVERSE')
 or exists(select 1 from cp7_sku_conversion.valuation_events_v2 where source_type=v_type and source_id=v_id and phase='REVERSE')then
  raise exception 'CP7_SKU_COMPONENT_ALREADY_REVERSED';end if;
 if v_components then
  insert into cp7_sku_conversion.component_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,root_lot_id,units_delta,physical_at,economic_date,supersedes_event_id)
  select gen_random_uuid(),null,source_type,source_id,line_no,'REVERSE',side,product_id,location_id,quality_grade,root_lot_id,-units_delta,
   statement_timestamp(),(statement_timestamp()at time zone 'Asia/Jakarta')::date,id
  from cp7_sku_conversion.component_events_v2 where source_type=v_type and source_id=v_id and phase='POST'order by line_no;
 end if;
 if v_values then
  insert into cp7_sku_conversion.valuation_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,qty_delta,effective_value_delta,legacy_value_delta,adjustment_delta,physical_at,economic_date,supersedes_event_id)
  select gen_random_uuid(),null,source_type,source_id,line_no,'REVERSE',side,product_id,location_id,quality_grade,-qty_delta,-effective_value_delta,-legacy_value_delta,-adjustment_delta,
   statement_timestamp(),(statement_timestamp()at time zone 'Asia/Jakarta')::date,id
  from cp7_sku_conversion.valuation_events_v2 where source_type=v_type and source_id=v_id and phase='POST'order by line_no;
 end if;
 if exists(select 1 from cp7_sku_conversion.component_events_v2 where source_type=v_type and source_id=v_id
  group by product_id,location_id,quality_grade,root_lot_id having abs(sum(units_delta))>0.000000000001)then
  raise exception 'CP7_SKU_COMPONENT_STATUS_REVERSE_NOT_EXACT';end if;
 if exists(select 1 from cp7_sku_conversion.valuation_events_v2 where source_type=v_type and source_id=v_id
  group by product_id,location_id,quality_grade having abs(sum(qty_delta))>0.000000000001 or abs(sum(effective_value_delta))>0.001
   or abs(sum(legacy_value_delta))>0.001 or abs(sum(adjustment_delta))>0.001)then
  raise exception 'CP7_SKU_VALUE_STATUS_REVERSE_NOT_EXACT';end if;
 return new;
end $function$

erp.be_reconcile_cost_document_v1(uuid,d:
CREATE OR REPLACE FUNCTION erp.be_reconcile_cost_document_v1(p_document uuid, p_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s erp.be_conversion_cost_sources_v1%rowtype;c erp.product_conversions%rowtype;l erp.fg_lots%rowtype;
 r record;v_target numeric;v_before numeric;v_delta numeric;v_journal uuid;v_own boolean;v_event uuid;
 v_sku_before jsonb;v_sku_delta numeric:=0;
begin
 perform erp.require_internal();
 select * into s from erp.be_conversion_cost_sources_v1 where document_id=p_document;
 if s.document_id is null then return;end if;
 perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 select * into c from erp.product_conversions where id=s.conversion_id for update;
 select * into l from erp.fg_lots where id=(select source_lot_id from erp.be_conversion_sources_v1 where conversion_id=c.id);
 if c.status<>'POSTED' then raise exception 'BE_COST_SOURCE_NOT_POSTED';end if;
 if l.po_id is null then v_sku_before:=cp7_sku_conversion.capture_cost_source_v3(p_document);end if;
 v_own:=not erp.be_in_context_v1();
 if v_own then insert into erp.be_execution_context_v1 values(pg_backend_pid(),txid_current(),gen_random_uuid());end if;
 for r in select p.adjustment_id,p.account_id,d.status from erp.bc_adjustment_purposes_v1 p
    join erp.bc_documents_v1 d on d.id=p.document_id where p.document_id=p_document order by p.adjustment_id loop
   v_target:=case when r.status='POSTED' then -(erp._cp6_material_adjustment_revaluation_state(r.adjustment_id)->>'current_value')::numeric else 0 end;
   if (s.kind='USAGE' and v_target<0) or (s.kind='RECOVERY' and v_target>0) then raise exception 'BE_COST_DIRECTION';end if;
   select coalesce(sum(target_amount-previous_amount),0) into v_before from erp.be_conversion_cost_events_v1 where adjustment_id=r.adjustment_id;
   v_delta:=v_target-v_before;
   if v_delta<>0 then
     v_event:=gen_random_uuid();
     v_journal:=erp.post_journal('BE_CONVERSION_SOURCED_COST',v_event,p_date,'Biaya/pemulihan konversi dari dokumen '||p_document::text,
       jsonb_build_array(jsonb_build_object('mapping_key',case when l.po_id is null then 'FG_INVENTORY' else 'WIP' end,
         'po_id',l.po_id,'product_id',case when l.po_id is null then c.to_product_id end,'debit',greatest(v_delta,0),'credit',greatest(-v_delta,0)),
         jsonb_build_object('account_id',r.account_id,'debit',greatest(-v_delta,0),'credit',greatest(v_delta,0))));
     insert into erp.be_conversion_cost_events_v1(id,document_id,adjustment_id,previous_amount,target_amount,journal_id,economic_date,created_by)
     values(v_event,p_document,r.adjustment_id,v_before,v_target,v_journal,p_date,erp.current_app_user_id());
     v_sku_delta:=v_sku_delta+v_delta;
   end if;
 end loop;
 if l.po_id is null then
   perform cp7_sku_conversion.rebalance_cost_source_v3(p_document,p_date,v_sku_before,v_sku_delta);
   perform erp.be_nonpo_sync_all_v1(p_date,'BE_COST_SOURCE',p_document,'Biaya/pemulihan konversi non-PO');
 else
   perform erp.propagate_conversion_hpp_for_po(l.po_id);
   perform erp.sync_po_hpp_to_gl(l.po_id,p_date);
   perform erp.assert_po_hpp_target_book_v2620e(l.po_id);
 end if;
 if v_own then delete from erp.be_execution_context_v1 where backend_pid=pg_backend_pid() and transaction_id=txid_current();end if;
end;$function$

erp.post_opening_hpp_correction(uuid,num:
CREATE OR REPLACE FUNCTION erp.post_opening_hpp_correction(p_lot_id uuid, p_new_hpp numeric, p_reason text, p_effective_date date DEFAULT ((statement_timestamp() AT TIME ZONE 'Asia/Jakarta'::text))::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare l erp.fg_lots%rowtype;v_old_id uuid;v_old_hpp numeric(20,6);v_ver integer;v_new_id uuid;v_corr uuid;v_no text;v_scope record;v_base_money_before jsonb;
begin
  perform erp.require_owner_admin();
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan koreksi HPP opening wajib diisi'; end if;
  if p_new_hpp is null or p_new_hpp<0 then raise exception 'HPP opening hasil koreksi tidak boleh negatif'; end if;
  select * into l from erp.fg_lots where id=p_lot_id for update;
  if l.id is null or l.lot_origin<>'OPENING' then raise exception 'Koreksi HPP opening hanya untuk lot saldo awal'; end if;
  if exists(select 1 from erp.product_conversion_allocations pca join erp.product_conversions pc on pc.id=pca.conversion_id where pca.source_lot_id=l.id and pc.status='POSTED') then
    raise exception 'Lot opening sudah pernah dipakai conversion/rebrand. Reverse/correct conversion tersebut dulu sebelum mengubah HPP opening.';
  end if;
  -- Prove every affected source/book scope before changing the root HPP.
  -- An equal aggregate must never hide pre-existing opposite discrepancies.
  for v_scope in
    select l.product_id product_id
    union select e.product_id from cp7_sku_conversion.component_events_v2 e
      where e.root_lot_id=l.id and e.source_type='SKU_CONVERSION'
    order by product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(v_scope.product_id);
  end loop;
  select hpp_version_id,hpp_per_pcs into v_old_id,v_old_hpp from erp.v_current_hpp where lot_id=l.id;
  if v_old_id is null then raise exception 'Current HPP lot opening tidak ditemukan'; end if;
  if abs(v_old_hpp-p_new_hpp)<=0.000001 then raise exception 'HPP baru sama dengan HPP current (%)',v_old_hpp; end if;
  select coalesce(max(version_no),0)+1 into v_ver from erp.hpp_versions where lot_id=l.id;
  v_base_money_before:=cp7_sku_conversion.capture_base_price_v4(l.id);
  update erp.hpp_versions set is_current=false where lot_id=l.id and is_current=true;
  insert into erp.hpp_versions(lot_id,version_no,cost_state,qty_basis_pcs,total_cost,is_current,supersedes_id,calculation_reason,created_by)
  values(l.id,v_ver,'ADJUSTED',l.initial_qty_pcs,l.initial_qty_pcs*p_new_hpp,true,v_old_id,'Controlled opening HPP correction: '||p_reason,erp.current_app_user_id()) returning id into v_new_id;
  perform cp7_sku_conversion.reprice_base_money_v4(l.id,p_effective_date,v_base_money_before);
  v_no:='OHPP-'||to_char((clock_timestamp() AT TIME ZONE 'Asia/Jakarta'),'YYYYMMDDHH24MISSMS')||'-'||substr(gen_random_uuid()::text,1,6);
  insert into erp.opening_hpp_corrections(correction_number,lot_id,previous_hpp_snapshot,corrected_hpp,effective_date,reason,hpp_version_id,created_by)
  values(v_no,l.id,v_old_hpp,p_new_hpp,p_effective_date,p_reason,v_new_id,erp.current_app_user_id()) returning id into v_corr;
  perform erp.sync_opening_lot_hpp_to_gl(l.id,p_effective_date);
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('fg_lots',l.id,'UPDATE',jsonb_build_object('correction_id',v_corr,'previous_hpp',v_old_hpp,'corrected_hpp',p_new_hpp),erp.current_app_user_id(),p_reason);
  return v_corr;
end;$function$

erp.post_sale(uuid):
CREATE OR REPLACE FUNCTION erp.post_sale(p_sale_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  h erp.sales_headers%rowtype;
  r record;
  v_sales numeric(24,6):=0;
  v_item_qty bigint;
  v_reserved_qty bigint;
  v_delta_cogs numeric(24,6);
  v_delta_fg numeric(24,6);
  v_delta_other numeric(24,6);
  v_target_hpp numeric(24,6);
  v_target_other numeric(24,6);
  v_book_hpp numeric(24,6);
  v_book_other numeric(24,6);
  v_lines jsonb:='[]'::jsonb;
begin
  perform erp.require_internal();
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  select * into h from erp.sales_headers where id=p_sale_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Sale must be DRAFT'; end if;
  if h.source_location_id is null then raise exception 'Sale source FG location is required'; end if;
  if not exists(select 1 from erp.sales_items where sale_id=p_sale_id) then raise exception 'Sale has no items'; end if;

  select coalesce(sum(qty_pcs),0),coalesce(sum(line_total),0)
  into v_item_qty,v_sales from erp.sales_items where sale_id=h.id;
  select coalesce(sum(abs(m.qty_signed)),0) into v_reserved_qty
  from erp.fg_stock_movements m
  join erp.sales_items i on i.id=m.source_id
  where i.sale_id=h.id and m.source_type='SALE_ITEM' and m.movement_type='SALE_RESERVE'
    and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=m.id);

  if v_reserved_qty=0 then v_reserved_qty:=erp._reserve_sale_draft(h.id); end if;
  if v_reserved_qty<>v_item_qty then
    raise exception 'Sale Draft reservation mismatch. Items %, active reservation %',v_item_qty,v_reserved_qty;
  end if;
  if exists(
    select 1 from erp.sales_items i
    left join(select sale_item_id,sum(qty_pcs)::bigint qty_pcs
      from erp.sale_stock_allocations group by sale_item_id) a on a.sale_item_id=i.id
    where i.sale_id=h.id and coalesce(a.qty_pcs,0)<>i.qty_pcs
  ) then raise exception 'Sale allocation does not match Draft line quantity'; end if;

  if (with active as (
  select m.* from erp.fg_stock_movements m
  where exists(select 1 from erp.sales_items scope_item where scope_item.id=m.source_id and scope_item.sale_id=h.id) and m.source_type='SALE_ITEM' and m.movement_type in('SALE_RESERVE','SALE')
    and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=m.id)
), allocations as (
  select a.sale_item_id,a.lot_id,a.location_id,sum(a.qty_pcs)::bigint qty
  from erp.sale_stock_allocations a where exists(select 1 from erp.sales_items scope_item where scope_item.id=a.sale_item_id and scope_item.sale_id=h.id) group by a.sale_item_id,a.lot_id,a.location_id
), movements as (
  select m.source_id sale_item_id,m.lot_id,m.location_id,sum(-m.qty_signed)::bigint qty
  from active m group by m.source_id,m.lot_id,m.location_id
)
select count(*)::bigint from (
  select m.id,sh_lineage.id sale_id from active m
  left join erp.sales_items i on i.id=m.source_id
  left join erp.sales_headers sh_lineage on sh_lineage.id=i.sale_id
  left join erp.fg_lots l on l.id=m.lot_id
  where sh_lineage.status is null or sh_lineage.status not in('DRAFT','POSTED','PARTIAL_PAID','PAID')
    or m.movement_type is distinct from case when sh_lineage.status='DRAFT' then 'SALE_RESERVE' else 'SALE' end
    or m.product_id is distinct from i.product_id or l.product_id is distinct from i.product_id
    or m.location_id is distinct from sh_lineage.source_location_id
    or m.customer_id is distinct from sh_lineage.customer_id or m.physical_at is distinct from sh_lineage.sale_date
    or m.quality_grade is distinct from 'GRADE_A' or m.qty_signed>=0
  union all
  select a.id,sh_lineage.id from erp.sale_stock_allocations a
  left join erp.sales_items i on i.id=a.sale_item_id
  left join erp.sales_headers sh_lineage on sh_lineage.id=i.sale_id
  left join erp.fg_lots l on l.id=a.lot_id
  where sh_lineage.status is null or sh_lineage.status not in('DRAFT','POSTED','PARTIAL_PAID','PAID','REVERSED')
    or l.product_id is distinct from i.product_id
    or a.location_id is distinct from sh_lineage.source_location_id or a.qty_pcs<=0
  union all
  select i.id,sh_lineage.id from allocations a full join movements m using(sale_item_id,lot_id,location_id)
  join erp.sales_items i on i.id=coalesce(a.sale_item_id,m.sale_item_id)
  join erp.sales_headers sh_lineage on sh_lineage.id=i.sale_id
  where sh_lineage.status in('DRAFT','POSTED','PARTIAL_PAID','PAID') and a.qty is distinct from m.qty
  union all
  select i.id,sh_lineage.id from erp.sales_items i join erp.sales_headers sh_lineage on sh_lineage.id=i.sale_id
  where (sh_lineage.status in('POSTED','PARTIAL_PAID','PAID') or
    (sh_lineage.status='DRAFT' and (exists(select 1 from erp.sale_stock_allocations a
       join erp.sales_items sibling on sibling.id=a.sale_item_id where sibling.sale_id=sh_lineage.id)
      or exists(select 1 from active m join erp.sales_items sibling on sibling.id=m.source_id where sibling.sale_id=sh_lineage.id))))
    and (i.qty_pcs is distinct from (select coalesce(sum(a.qty_pcs),0) from erp.sale_stock_allocations a where a.sale_item_id=i.id)
      or i.qty_pcs is distinct from (select coalesce(sum(-m.qty_signed),0) from active m where m.source_id=i.id))
  union all
  select sh_lineage.id,sh_lineage.id from erp.sales_headers sh_lineage where sh_lineage.status in('POSTED','PARTIAL_PAID','PAID')
    and not exists(select 1 from erp.sales_items i where i.sale_id=sh_lineage.id)
) broken where broken.sale_id=h.id)<>0 then
    raise exception 'AG_SALE_RESERVATION_LINEAGE_MISMATCH';
  end if;

  perform cp7_sku_conversion.prepare_sale_values_v2(h.id);

  for r in
    select distinct v.product_id
    from cp7_sku_conversion.sale_allocation_attributions_v2 a
    join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
    where v.sale_id=h.id and a.po_id is null
    order by v.product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(r.product_id);
  end loop;

  update erp.sale_stock_allocations a
  set unit_hpp_snapshot=cp7_sku_conversion.sale_allocation_unit_v2(a.id,a.lot_id)
  from erp.sales_items i
  where i.id=a.sale_item_id and i.sale_id=h.id;

  update erp.fg_stock_movements m
  set unit_hpp_snapshot=a.unit_hpp_snapshot
  from erp.sales_items i
  join erp.sale_stock_allocations a on a.sale_item_id=i.id
  where i.id=m.source_id and i.sale_id=h.id
    and a.lot_id=m.lot_id
    and m.source_type='SALE_ITEM' and m.movement_type='SALE_RESERVE'
    and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=m.id);

  update erp.fg_stock_movements m
  set movement_type='SALE',notes='Sale posted · quantity reserved in Draft; HPP frozen at POST'
  from erp.sales_items i
  where i.id=m.source_id and i.sale_id=h.id
    and m.source_type='SALE_ITEM' and m.movement_type='SALE_RESERVE'
    and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=m.id);

  -- BD (LAU-04, LAU-DEC04): goods whose laundry price is still unknown are sold only if the owner allows it.
  perform erp.bd_assert_sale_laundry_known_v1(h.id);
  update erp.sales_headers set status='POSTED' where id=h.id;
  if abs(v_sales)>0.005 then
    v_lines:=v_lines||jsonb_build_array(
      jsonb_build_object('mapping_key','AR_CUSTOMER','debit',round(v_sales,2),'credit',0,'customer_id',h.customer_id),
      jsonb_build_object('mapping_key','SALES_REVENUE','debit',0,'credit',round(v_sales,2),'customer_id',h.customer_id));
  end if;

  -- One cumulative target per product, composed from per-lot lifecycle truth.
  for r in
    select distinct v.product_id
    from cp7_sku_conversion.sale_allocation_attributions_v2 a
    join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
    where v.sale_id=h.id and a.po_id is null
    order by v.product_id
  loop
    select round(t.fg_value-b.fg_value,2),
      round(t.cogs_value-b.cogs_value,2),
      round(t.other_out_value-b.other_out_value,2)
    into v_delta_fg,v_delta_cogs,v_delta_other
    from erp.compute_non_po_product_hpp_targets_v2620f(r.product_id) t
    cross join lateral erp.compute_non_po_product_hpp_book_v2620f(r.product_id) b;
    if abs(v_delta_fg+v_delta_cogs+v_delta_other)>0.005 then
      raise exception 'Sale non-PO HPP delta does not conserve source value for product %: fg %, cogs %, other %',
        r.product_id,v_delta_fg,v_delta_cogs,v_delta_other;
    end if;
    if abs(v_delta_fg)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_fg>0
        then jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_delta_fg,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,
          'credit',abs(v_delta_fg),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
    if abs(v_delta_cogs)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_cogs>0
        then jsonb_build_object('mapping_key','COGS','debit',v_delta_cogs,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','COGS','debit',0,
          'credit',abs(v_delta_cogs),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
    if abs(v_delta_other)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_other>0
        then jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',v_delta_other,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,
          'credit',abs(v_delta_other),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
  end loop;

  for r in
    select distinct a.po_id
    from cp7_sku_conversion.sale_allocation_attributions_v2 a
    join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
    where v.sale_id=h.id and a.po_id is not null
    order by a.po_id
  loop
    perform erp.refresh_po_hpp_gl_baseline(r.po_id);
    select
      round(coalesce(t.cogs_value,0),2)-s.cogs_value,
      round(coalesce(t.fg_value,0),2)-s.fg_value,
      (round(coalesce(t.hpp_total_cost,0),2)-round(coalesce(t.fg_value,0),2)
        -round(coalesce(t.cogs_value,0),2))-s.other_out_value,
      round(coalesce(t.hpp_total_cost,0),2),
      round(coalesce(t.hpp_total_cost,0),2)-round(coalesce(t.fg_value,0),2)-round(coalesce(t.cogs_value,0),2),
      s.hpp_total_cost,s.other_out_value
    into v_delta_cogs,v_delta_fg,v_delta_other,
      v_target_hpp,v_target_other,v_book_hpp,v_book_other
    from erp.po_hpp_gl_state s
    cross join lateral erp.compute_po_hpp_gl_targets_v2620d(r.po_id) t
    where s.po_id=r.po_id for update of s;
    if v_delta_cogs<-0.005 or v_delta_fg>0.005
       or abs(v_delta_cogs+v_delta_fg+v_delta_other)>0.005
       or v_target_hpp is distinct from v_book_hpp then
      raise exception 'Sale cumulative HPP target does not conserve PO value %. dc %, df %, do %, target/book hpp %/%',
        r.po_id,v_delta_cogs,v_delta_fg,v_delta_other,v_target_hpp,v_book_hpp;
    end if;
    if abs(v_delta_cogs)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_cogs>0 then
        jsonb_build_object('mapping_key','COGS','debit',v_delta_cogs,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','COGS','debit',0,'credit',abs(v_delta_cogs),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
    if abs(v_delta_fg)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_fg>0 then
        jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_delta_fg,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',abs(v_delta_fg),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
    if abs(v_delta_other)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_other>0 then
        jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',v_delta_other,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,'credit',abs(v_delta_other),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
  end loop;
  if jsonb_array_length(v_lines)>=2 then
    perform erp.post_journal('SALE',h.id,(h.sale_date AT TIME ZONE 'Asia/Jakarta')::date,
      'Sales to customer/toko · cumulative exact HPP target',v_lines);
  end if;

  for r in
    select distinct v.product_id
    from cp7_sku_conversion.sale_allocation_attributions_v2 a
    join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
    where v.sale_id=h.id and a.po_id is null
    order by v.product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(r.product_id);
  end loop;

  for r in
    select distinct a.po_id
    from cp7_sku_conversion.sale_allocation_attributions_v2 a
    join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
    where v.sale_id=h.id and a.po_id is not null
    order by a.po_id
  loop
    perform erp.refresh_po_hpp_gl_baseline(r.po_id);
    perform erp.assert_po_hpp_target_book_v2620e(r.po_id);
  end loop;
end
$function$

erp.post_sales_return(uuid):
CREATE OR REPLACE FUNCTION erp.post_sales_return(p_return_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.sales_returns%rowtype;
  s erp.sales_headers%rowtype;
  r record;
  v_refund numeric(24,6):=0;
  v_sold_qty integer;
  v_prior_returned integer;
  v_current_return integer;
  v_product_sale_value numeric(24,6);
  v_prior_product_refund numeric(24,6);
  v_current_product_refund numeric(24,6);
  v_original_hpp numeric(18,6);
  v_unit_hpp numeric(18,6);
  v_net_total numeric(20,2);
  v_paid numeric(20,2);
  v_delta_cogs numeric(24,6);
  v_delta_fg numeric(24,6);
  v_delta_other numeric(24,6);
  v_target_hpp numeric(24,6);
  v_target_other numeric(24,6);
  v_book_hpp numeric(24,6);
  v_book_other numeric(24,6);
  v_lines jsonb:='[]'::jsonb;
begin
  perform erp.require_internal();
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  perform erp.require_internal();
  perform cp7_credit.native_return_enter(p_return_id);
  perform erp.require_internal();
  select * into h from erp.sales_returns where id=p_return_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Sales return must be DRAFT'; end if;
  if h.sale_id is null then raise exception 'Native sales return must reference the original sale'; end if;
  select * into s from erp.sales_headers where id=h.sale_id for update;
  if s.id is null or s.status not in('POSTED','PARTIAL_PAID','PAID') then raise exception 'Original sale must be active/posted'; end if;
  if s.customer_id is distinct from h.customer_id then raise exception 'Sales return customer does not match original sale customer'; end if;
  if not exists(select 1 from erp.sales_return_items where return_id=h.id) then raise exception 'Sales return has no lines'; end if;

  perform cp7_sku_conversion.prepare_return_values_v2(h.id);

  for r in
    select distinct v.product_id
    from cp7_sku_conversion.sales_return_attributions_v2 a
    join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
    where v.return_id=h.id and a.po_id is null
    union select fl.product_id from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is null
      and not exists(select 1 from cp7_sku_conversion.sales_return_values_v2 v where v.sales_return_item_id=i.id)
    order by product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(r.product_id);
  end loop;

  for r in
    select * from erp.sales_return_items where return_id=h.id
    order by product_id,location_id,quality_grade,lot_id,id
  loop
    if r.lot_id is null then raise exception 'Sales return line requires original FG lot'; end if;
    if not exists(select 1 from erp.fg_lots fl where fl.id=r.lot_id and fl.product_id=r.product_id) then raise exception 'Sales return lot does not belong to selected product'; end if;

    insert into erp.fg_inventory_balances(product_id,location_id,quality_grade,cached_qty_pcs)
    values(r.product_id,r.location_id,r.quality_grade,0)
    on conflict(product_id,location_id,quality_grade) do nothing;
    perform 1 from erp.fg_inventory_balances
    where product_id=r.product_id and location_id=r.location_id and quality_grade=r.quality_grade
    for update;
    perform 1 from erp.fg_lots where id=r.lot_id for update;

    -- Eligibility belongs to the selected allocation. Receipt destination is
    -- independently validated and may be another active FG warehouse.
    select a.qty_pcs,a.unit_hpp_snapshot into v_sold_qty,v_original_hpp
    from erp.sale_stock_allocations a join erp.sales_items si on si.id=a.sale_item_id
    where a.id=r.sale_stock_allocation_id and si.sale_id=h.sale_id
      and si.product_id=r.product_id and a.lot_id=r.lot_id;
    if v_sold_qty is null or v_sold_qty<=0 or v_original_hpp is null then
      raise exception 'AH_RETURN_ALLOCATION_SOURCE_MISMATCH';
    end if;

    v_unit_hpp:=cp7_sku_conversion.return_item_unit_v2(r.id,r.lot_id,v_original_hpp);
    select coalesce(sum(sri.qty_pcs),0)::integer into v_prior_returned
    from erp.sales_return_items sri join erp.sales_returns sr on sr.id=sri.return_id
    where sr.sale_id=h.sale_id and sr.id<>h.id and sr.status='POSTED'
      and sri.sale_stock_allocation_id=r.sale_stock_allocation_id;
    select coalesce(sum(sri.qty_pcs),0)::integer into v_current_return
    from erp.sales_return_items sri
    where sri.return_id=h.id and sri.sale_stock_allocation_id=r.sale_stock_allocation_id;
    if v_prior_returned+v_current_return>v_sold_qty then
      raise exception 'AH_RETURN_EXCEEDS_ORIGINAL_ALLOCATION: Sales return exceeds quantity originally sold for this allocation. Sold %, prior returned %, current return %',v_sold_qty,v_prior_returned,v_current_return;
    end if;

    select coalesce(sum(si.line_total),0) into v_product_sale_value
    from erp.sales_items si where si.sale_id=h.sale_id and si.product_id=r.product_id;
    select coalesce(sum(sri.refund_amount),0) into v_prior_product_refund
    from erp.sales_return_items sri join erp.sales_returns sr on sr.id=sri.return_id
    where sr.sale_id=h.sale_id and sr.id<>h.id and sr.status='POSTED' and sri.product_id=r.product_id;
    select coalesce(sum(sri.refund_amount),0) into v_current_product_refund
    from erp.sales_return_items sri where sri.return_id=h.id and sri.product_id=r.product_id;
    if v_prior_product_refund+v_current_product_refund>v_product_sale_value then
      raise exception 'Refund exceeds original net sale value for product. Sold value %, prior refund %, current refund %',v_product_sale_value,v_prior_product_refund,v_current_product_refund;
    end if;

    update erp.sales_return_items set unit_hpp_snapshot=v_unit_hpp where id=r.id;
    perform erp.post_fg_movement(r.product_id,r.lot_id,r.location_id,r.quality_grade,
      'SALE_RETURN',r.qty_pcs,v_unit_hpp,h.customer_id,'SALES_RETURN_ITEM',r.id,
      h.physical_at,'Customer sales return',false);
    v_refund:=v_refund+r.refund_amount;
  end loop;

  select greatest(erp.sale_net_total(h.sale_id)-v_refund,0)::numeric(20,2) into v_net_total;
  select coalesce(sum(sp.amount),0)::numeric(20,2) into v_paid
  from erp.sales_payments sp where sp.sale_id=h.sale_id and sp.status='POSTED';
  v_paid:=cp7_credit.native_return_guard(h.id,v_refund,v_net_total,v_paid);
  if v_paid>v_net_total then
    raise exception 'Retur ini membuat pembayaran customer melebihi nilai penjualan tersisa. Nilai setelah retur %, sudah dibayar %. Reverse/koreksi pembayaran customer dulu agar kelebihan bayar tidak hilang dari pembukuan.',v_net_total,v_paid;
  end if;

  update erp.sales_returns set status='POSTED' where id=h.id;
  if abs(v_refund)>0.005 then
    v_lines:=v_lines||jsonb_build_array(
      jsonb_build_object('mapping_key','SALES_REVENUE','debit',round(v_refund,2),'credit',0,'customer_id',h.customer_id),
      jsonb_build_object('mapping_key','AR_CUSTOMER','debit',0,'credit',round(v_refund,2),'customer_id',h.customer_id));
  end if;

  for r in
    select distinct v.product_id
    from cp7_sku_conversion.sales_return_attributions_v2 a
    join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
    where v.return_id=h.id and a.po_id is null
    union select fl.product_id from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is null
      and not exists(select 1 from cp7_sku_conversion.sales_return_values_v2 v where v.sales_return_item_id=i.id)
    order by product_id
  loop
    select round(t.fg_value-b.fg_value,2),
      round(t.cogs_value-b.cogs_value,2),
      round(t.other_out_value-b.other_out_value,2)
    into v_delta_fg,v_delta_cogs,v_delta_other
    from erp.compute_non_po_product_hpp_targets_v2620f(r.product_id) t
    cross join lateral erp.compute_non_po_product_hpp_book_v2620f(r.product_id) b;
    if abs(v_delta_fg+v_delta_cogs+v_delta_other)>0.005 then
      raise exception 'Return non-PO HPP delta does not conserve source value for product %: fg %, cogs %, other %',
        r.product_id,v_delta_fg,v_delta_cogs,v_delta_other;
    end if;
    if abs(v_delta_fg)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_fg>0
        then jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_delta_fg,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,
          'credit',abs(v_delta_fg),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
    if abs(v_delta_cogs)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_cogs>0
        then jsonb_build_object('mapping_key','COGS','debit',v_delta_cogs,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','COGS','debit',0,
          'credit',abs(v_delta_cogs),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
    if abs(v_delta_other)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_other>0
        then jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',v_delta_other,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,
          'credit',abs(v_delta_other),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
  end loop;

  for r in
    select distinct a.po_id
    from cp7_sku_conversion.sales_return_attributions_v2 a
    join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
    where v.return_id=h.id and a.po_id is not null
    union select fl.po_id from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is not null
      and not exists(select 1 from cp7_sku_conversion.sales_return_values_v2 v where v.sales_return_item_id=i.id)
    order by po_id
  loop
    perform erp.refresh_po_hpp_gl_baseline(r.po_id);
    select
      round(coalesce(t.cogs_value,0),2)-st.cogs_value,
      round(coalesce(t.fg_value,0),2)-st.fg_value,
      (round(coalesce(t.hpp_total_cost,0),2)-round(coalesce(t.fg_value,0),2)
        -round(coalesce(t.cogs_value,0),2))-st.other_out_value,
      round(coalesce(t.hpp_total_cost,0),2),
      round(coalesce(t.hpp_total_cost,0),2)-round(coalesce(t.fg_value,0),2)-round(coalesce(t.cogs_value,0),2),
      st.hpp_total_cost,st.other_out_value
    into v_delta_cogs,v_delta_fg,v_delta_other,
      v_target_hpp,v_target_other,v_book_hpp,v_book_other
    from erp.po_hpp_gl_state st
    cross join lateral erp.compute_po_hpp_gl_targets_v2620d(r.po_id) t
    where st.po_id=r.po_id for update of st;
    if v_delta_cogs>0.005 or v_delta_fg<-0.005
       or abs(v_delta_cogs+v_delta_fg+v_delta_other)>0.005
       or v_target_hpp is distinct from v_book_hpp then
      raise exception 'Sales-return cumulative HPP target does not conserve PO value %. dc %, df %, do %, target/book hpp %/%',
        r.po_id,v_delta_cogs,v_delta_fg,v_delta_other,v_target_hpp,v_book_hpp;
    end if;
    if abs(v_delta_cogs)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_cogs>0 then
        jsonb_build_object('mapping_key','COGS','debit',v_delta_cogs,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','COGS','debit',0,'credit',abs(v_delta_cogs),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
    if abs(v_delta_fg)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_fg>0 then
        jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_delta_fg,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',abs(v_delta_fg),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
    if abs(v_delta_other)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_other>0 then
        jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',v_delta_other,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,'credit',abs(v_delta_other),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
  end loop;
  if jsonb_array_length(v_lines)>=2 then
    perform cp7_credit.post_return_journal('SALES_RETURN',h.id,(h.physical_at AT TIME ZONE 'Asia/Jakarta')::date,
      'Sales return from customer · cumulative exact HPP target',v_lines);
  end if;
  perform cp7_credit.flush_opening_return_hpp_v1(h.id);
  v_paid:=cp7_credit.native_return_complete(h.id,v_refund,v_net_total);
  perform erp.require_internal();

  for r in
    select distinct v.product_id
    from cp7_sku_conversion.sales_return_attributions_v2 a
    join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
    where v.return_id=h.id and a.po_id is null
    union select fl.product_id from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is null
      and not exists(select 1 from cp7_sku_conversion.sales_return_values_v2 v where v.sales_return_item_id=i.id)
    order by product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(r.product_id);
  end loop;

  update erp.sales_headers
  set status=case when v_paid=v_net_total then 'PAID' when v_paid>0 and v_paid<v_net_total then 'PARTIAL_PAID' else 'POSTED' end
  where id=h.sale_id;
  for r in
    select distinct a.po_id
    from cp7_sku_conversion.sales_return_attributions_v2 a
    join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
    where v.return_id=h.id and a.po_id is not null
    union select fl.po_id from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is not null
      and not exists(select 1 from cp7_sku_conversion.sales_return_values_v2 v where v.sales_return_item_id=i.id)
    order by po_id
  loop
    perform erp.refresh_po_hpp_gl_baseline(r.po_id);
    perform erp.assert_po_hpp_target_book_v2620e(r.po_id);
  end loop;
  perform cp7_credit.native_return_leave(h.id);
  perform erp.require_internal();
end
$function$

erp.sync_non_po_product_hpp_to_gl_v2620f:
CREATE OR REPLACE FUNCTION erp.sync_non_po_product_hpp_to_gl_v2620f(p_product_id uuid, p_effective_date date, p_trigger_source_type text, p_trigger_source_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  t record;
  b record;
  v_df numeric(20,2);
  v_dc numeric(20,2);
  v_do numeric(20,2);
  v_event uuid:=gen_random_uuid();
  v_journal uuid;
  v_lines jsonb:='[]'::jsonb;
  v_scope record;v_guard text:=coalesce(current_setting('cp7.sku_nonpo_sync_expanding',true),'');
begin
  perform erp.require_internal();
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  if v_guard<>'1'then
   perform set_config('cp7.sku_nonpo_sync_expanding','1',true);
   for v_scope in select distinct e.product_id from (select product_id,root_lot_id,source_type from cp7_sku_conversion.component_events_v2 union all select product_id,root_lot_id,source_type from cp7_sku_conversion.cost_events_v3)e
    join erp.fg_lots root on root.id=e.root_lot_id and root.po_id is null and root.product_id=p_product_id
    where e.product_id<>p_product_id order by e.product_id loop
    perform erp.sync_non_po_product_hpp_to_gl_v2620f(v_scope.product_id,p_effective_date,p_trigger_source_type,p_trigger_source_id,p_reason);
   end loop;
   for v_scope in
    with related_sales as(select distinct v.sale_id from (select sale_stock_allocation_id,root_lot_id,po_id from cp7_sku_conversion.sale_allocation_components_v2 union all select sale_stock_allocation_id,root_lot_id,po_id from cp7_sku_conversion.sale_cost_components_v3) c
      join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
      join erp.fg_lots root on root.id=c.root_lot_id and root.po_id is null and root.product_id=p_product_id),
    related_returns as(select distinct v.return_id from (select sales_return_item_id,root_lot_id,po_id from cp7_sku_conversion.sales_return_components_v2 union all select sales_return_item_id,root_lot_id,po_id from cp7_sku_conversion.return_cost_components_v3) c
      join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
      join erp.fg_lots root on root.id=c.root_lot_id and root.po_id is null and root.product_id=p_product_id),
    scopes as(
      select c.po_id from (select sale_stock_allocation_id,root_lot_id,po_id from cp7_sku_conversion.sale_allocation_components_v2 union all select sale_stock_allocation_id,root_lot_id,po_id from cp7_sku_conversion.sale_cost_components_v3) c join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
       where v.sale_id in(select sale_id from related_sales)
      union select c.po_id from (select sales_return_item_id,root_lot_id,po_id from cp7_sku_conversion.sales_return_components_v2 union all select sales_return_item_id,root_lot_id,po_id from cp7_sku_conversion.return_cost_components_v3) c join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
       where v.return_id in(select return_id from related_returns)
      union select c2.po_id from (select group_id,root_lot_id,po_id from cp7_sku_conversion.valuation_contributors_v2 union all select group_id,root_lot_id,po_id from cp7_sku_conversion.cost_contributors_v3) c1
       join erp.fg_lots root on root.id=c1.root_lot_id and root.po_id is null and root.product_id=p_product_id
       join (select group_id,root_lot_id,po_id from cp7_sku_conversion.valuation_contributors_v2 union all select group_id,root_lot_id,po_id from cp7_sku_conversion.cost_contributors_v3) c2 using(group_id))
    select distinct po_id from scopes where po_id is not null order by po_id
   loop
    perform erp.sync_po_hpp_to_gl(v_scope.po_id,p_effective_date);
   end loop;
   perform set_config('cp7.sku_nonpo_sync_expanding',v_guard,true);
  end if;
  if nullif(btrim(p_trigger_source_type),'') is null
     or nullif(btrim(p_reason),'') is null then
    raise exception 'Non-PO HPP synchronization requires source and reason';
  end if;
  if not erp.be_nonpo_in_sync_v1() and exists(select 1 from erp.be_conversion_sources_v1 be_source
      join erp.fg_lots be_lot on be_lot.id=be_source.source_lot_id where be_lot.po_id is null) then
    perform erp.be_nonpo_sync_all_v1(p_effective_date,p_trigger_source_type,p_trigger_source_id,p_reason);return;
  end if;
  if exists(
    select 1
    from erp.product_conversion_allocations a
    join erp.product_conversions c on c.id=a.conversion_id and c.status='POSTED'
    join erp.fg_lots s on s.id=a.source_lot_id
    join erp.fg_lots d on d.id=a.destination_lot_id
    where(s.po_id is null or d.po_id is null) and not erp.be_nonpo_admitted_v1(c.id)
      and(s.product_id=p_product_id or d.product_id=p_product_id)
  ) then
    raise exception 'NON_PO_CONVERSION_REQUIRES_SOURCED_HPP_WORKFLOW';
  end if;

  select * into t
  from erp.compute_non_po_product_hpp_targets_v2620f(p_product_id);
  select * into b
  from erp.compute_non_po_product_hpp_book_v2620f(p_product_id);
  if abs(t.hpp_total_cost-b.hpp_total_cost)>0.005 then
    raise exception 'NON_PO_HPP_SOURCE_VALUE_MISMATCH: product %, target total %, book total %',
      p_product_id,t.hpp_total_cost,b.hpp_total_cost;
  end if;

  v_df:=round(t.fg_value-b.fg_value,2);
  v_dc:=round(t.cogs_value-b.cogs_value,2);
  v_do:=round(t.other_out_value-b.other_out_value,2);
  if abs(v_df+v_dc+v_do)>0.005 then
    raise exception 'NON_PO_HPP_DELTA_NOT_CONSERVED: product %, fg %, cogs %, other %',
      p_product_id,v_df,v_dc,v_do;
  end if;
  if abs(v_df)<=0.005 and abs(v_dc)<=0.005 and abs(v_do)<=0.005 then
    return;
  end if;

  if abs(v_df)>0.005 then
    v_lines:=v_lines||jsonb_build_array(case when v_df>0
      then jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_df,
        'credit',0,'product_id',p_product_id)
      else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,
        'credit',abs(v_df),'product_id',p_product_id) end);
  end if;
  if abs(v_dc)>0.005 then
    v_lines:=v_lines||jsonb_build_array(case when v_dc>0
      then jsonb_build_object('mapping_key','COGS','debit',v_dc,
        'credit',0,'product_id',p_product_id)
      else jsonb_build_object('mapping_key','COGS','debit',0,
        'credit',abs(v_dc),'product_id',p_product_id) end);
  end if;
  if abs(v_do)>0.005 then
    v_lines:=v_lines||jsonb_build_array(case when v_do>0
      then jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',v_do,
        'credit',0,'product_id',p_product_id)
      else jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,
        'credit',abs(v_do),'product_id',p_product_id) end);
  end if;

  v_journal:=erp.post_journal(
    'NON_PO_HPP_GL_SYNC_V2620F',v_event,p_effective_date,
    'Cumulative non-PO HPP redistribution · '||p_reason,v_lines
  );
  insert into erp.non_po_hpp_gl_sync_events_v2620f(
    id,product_id,trigger_source_type,trigger_source_id,effective_date,
    old_fg_value,new_fg_value,fg_delta,
    old_cogs_value,new_cogs_value,cogs_delta,
    old_other_out_value,new_other_out_value,other_delta,
    journal_entry_id,reason,created_by
  ) values(
    v_event,p_product_id,p_trigger_source_type,p_trigger_source_id,
    p_effective_date,b.fg_value,t.fg_value,v_df,
    b.cogs_value,t.cogs_value,v_dc,
    b.other_out_value,t.other_out_value,v_do,
    v_journal,p_reason,erp.current_app_user_id()
  );
  perform erp.assert_non_po_product_hpp_target_book_v2620f(p_product_id);
end
$function$

erp.sync_opening_lot_hpp_to_gl(uuid,date:
CREATE OR REPLACE FUNCTION erp.sync_opening_lot_hpp_to_gl(p_lot_id uuid, p_effective_date date DEFAULT ((statement_timestamp() AT TIME ZONE 'Asia/Jakarta'::text))::date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  l erp.fg_lots%rowtype; s erp.opening_lot_hpp_gl_state%rowtype;
  h erp.hpp_versions%rowtype; v_baseline numeric; v_source_delta numeric;
  v_expected_delta numeric; v_current_qty numeric; v_base_fg numeric;
  v_net_sold_qty numeric; v_actual_cogs numeric; v_expense numeric; v_income numeric;
  v_scope record;v_scope_delta numeric;v_lines jsonb:='[]'::jsonb;
begin
  perform erp.require_internal();
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  select * into l from erp.fg_lots where id=p_lot_id for update;
  if l.id is null or l.lot_origin<>'OPENING' then return; end if;
  select * into h from erp.hpp_versions where lot_id=l.id and is_current;
  if h.id is null then raise exception 'Opening current HPP is missing'; end if;
  select fm.unit_hpp_snapshot into v_baseline from erp.fg_stock_movements fm
  where fm.lot_id=l.id and fm.movement_type='OPENING'
  order by fm.physical_at,fm.system_created_at,fm.id limit 1;
  if v_baseline is null then raise exception 'Opening lot % has no source movement',l.lot_number; end if;
  if exists(select 1 from erp.product_conversion_allocations a
    join erp.product_conversions c on c.id=a.conversion_id
    where a.source_lot_id=l.id and c.status='POSTED') then
    if exists(select 1 from erp.product_conversion_allocations a
      join erp.product_conversions c on c.id=a.conversion_id
      where a.source_lot_id=l.id and c.status='POSTED' and not erp.be_nonpo_admitted_v1(c.id)) then
      raise exception 'Opening HPP conversion requires a sourced descendant correction workflow';
    end if;
    perform erp.be_nonpo_prepare_transfers_v1(p_effective_date);
  end if;
  select * into s from erp.opening_lot_hpp_gl_state where lot_id=l.id for update;
  v_expected_delta:=round(h.total_cost,2)
    -round(l.initial_qty_pcs*coalesce(s.current_hpp,v_baseline),2);
  -- Root basis remains exact. Its source delta follows the economic
  -- component owners, which may include another product after conversion.
  v_source_delta:=0;
  for v_scope in
    select l.product_id product_id
    union select e.product_id from cp7_sku_conversion.component_events_v2 e
      where e.root_lot_id=l.id and e.source_type='SKU_CONVERSION'
    order by product_id
  loop
    select t.hpp_total_cost-b.hpp_total_cost into v_scope_delta
    from erp.compute_non_po_product_hpp_targets_v2620f(v_scope.product_id) t
    cross join lateral erp.compute_non_po_product_hpp_book_v2620f(v_scope.product_id) b;
    if v_scope_delta is null then raise exception 'OPENING_COMPONENT_SOURCE_UNKNOWN';end if;
    v_source_delta:=v_source_delta+v_scope_delta;
    if v_scope_delta<>0 then
      v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','FG_INVENTORY',
        'debit',greatest(v_scope_delta,0),'credit',greatest(-v_scope_delta,0),'product_id',v_scope.product_id));
    end if;
  end loop;
  if v_source_delta is distinct from v_expected_delta then
    raise exception 'OPENING_SOURCE_CHANGE_NOT_EXACT: product %, pending lot basis %, target/book source delta %',
      l.product_id,v_expected_delta,v_source_delta;
  end if;
  if v_source_delta<>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','OPENING_EQUITY',
      'debit',greatest(-v_source_delta,0),'credit',greatest(v_source_delta,0)));
  end if;
  if jsonb_array_length(v_lines)>0 then
    perform erp.post_journal('OPENING_HPP_SOURCE_V2620G',h.id,p_effective_date,
      'Source lot basis correction for '||l.lot_number||' / HPP version '||h.id,v_lines);
  end if;
  perform erp.sync_non_po_product_hpp_to_gl_v2620f(l.product_id,p_effective_date,
    'OPENING_HPP_LIFECYCLE_V2620G',h.id,'Exact rounded opening source and cumulative physical lifecycle');
  for v_scope in
    select l.product_id product_id
    union select e.product_id from cp7_sku_conversion.component_events_v2 e
      where e.root_lot_id=l.id and e.source_type='SKU_CONVERSION'
    order by product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(v_scope.product_id);
  end loop;

  -- Preserve the historical raw revaluation diagnostics and trigger-activation
  -- contract. These projections are not used as monetary posting authority:
  -- actual journals and F's cumulative source/target/book checks are.
  -- DRAFT reservations reduce sellable qty, not company ownership.
  select coalesce(sum(fm.qty_signed),0),coalesce(sum(fm.qty_signed*fm.unit_hpp_snapshot),0)
    into v_current_qty,v_base_fg from erp.fg_stock_movements fm where fm.lot_id=l.id;
  select v_current_qty+coalesce(sum(abs(fm.qty_signed)),0),
    v_base_fg+coalesce(sum(abs(fm.qty_signed)*fm.unit_hpp_snapshot),0)
    into v_current_qty,v_base_fg from erp.fg_stock_movements fm
    where fm.lot_id=l.id and fm.movement_type='SALE_RESERVE'
      and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=fm.id);
  select coalesce(sum(a.qty_pcs),0),coalesce(sum(a.qty_pcs*a.unit_hpp_snapshot),0)
    into v_net_sold_qty,v_actual_cogs from erp.sale_stock_allocations a
    join erp.sales_items i on i.id=a.sale_item_id join erp.sales_headers sh on sh.id=i.sale_id
    where a.lot_id=l.id and sh.status in('POSTED','PARTIAL_PAID','PAID');
  select v_net_sold_qty-coalesce(sum(i.qty_pcs),0),v_actual_cogs-coalesce(sum(i.qty_pcs*i.unit_hpp_snapshot),0)
    into v_net_sold_qty,v_actual_cogs from erp.sales_return_items i
    join erp.sales_returns rh on rh.id=i.return_id where i.lot_id=l.id and rh.status='POSTED';
  select coalesce(sum(case when i.qty_signed<0 then -i.qty_signed*(h.hpp_per_pcs-i.unit_hpp_snapshot) else 0 end),0),
    coalesce(sum(case when i.qty_signed>0 then i.qty_signed*(h.hpp_per_pcs-i.unit_hpp_snapshot) else 0 end),0)
    into v_expense,v_income from erp.fg_adjustment_items i
    join erp.fg_adjustments a on a.id=i.adjustment_id where i.lot_id=l.id and a.status='POSTED';
  insert into erp.opening_lot_hpp_gl_state(lot_id,current_hpp,fg_revaluation,cogs_revaluation,
    expense_revaluation,income_revaluation,equity_revaluation,updated_at)
  values(l.id,h.hpp_per_pcs,v_current_qty*h.hpp_per_pcs-v_base_fg,
    v_net_sold_qty*h.hpp_per_pcs-v_actual_cogs,v_expense,v_income,
    l.initial_qty_pcs*(h.hpp_per_pcs-v_baseline),statement_timestamp())
  on conflict(lot_id) do update set current_hpp=excluded.current_hpp,
    fg_revaluation=excluded.fg_revaluation,cogs_revaluation=excluded.cogs_revaluation,
    expense_revaluation=excluded.expense_revaluation,income_revaluation=excluded.income_revaluation,
    equity_revaluation=excluded.equity_revaluation,updated_at=statement_timestamp();
end
$function$

cp7_credit.initial_hpp_projection_v1(jso:
CREATE OR REPLACE FUNCTION cp7_credit.initial_hpp_projection_v1(p_legacy jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare x jsonb;a record;r record;t record;b record;cost numeric;owned numeric;sold numeric;returned numeric;
 hpp numeric:=0;items jsonb:='[]';groups jsonb:='[]';lines jsonb:='[]';group_amount numeric;
 products uuid[];pos uuid[];lots uuid[];versions uuid[];fresh_lots uuid[];fresh_versions uuid[];
 before_profile jsonb;after_profile jsonb;before_target jsonb;after_target jsonb;actual_book jsonb;saved_state jsonb;account_facts jsonb;source_support jsonb;opening_source jsonb;
 component_plan jsonb;fresh_component_plan jsonb;scope_items jsonb;
 delta_fg numeric;delta_cogs numeric;delta_other numeric;fg_account uuid;cogs_account uuid;expense_account uuid;income_account uuid;
begin
 select array_agg(distinct i.product_id order by i.product_id),array_agg(distinct fl.po_id order by fl.po_id)filter(where fl.po_id is not null)
 into products,pos from jsonb_array_elements(p_legacy->'items')as draft_item(value)join erp.sale_stock_allocations sa on sa.id=(draft_item.value->>'allocation_id')::uuid
  join erp.sales_items i on i.id=sa.sale_item_id join erp.fg_lots fl on fl.id=sa.lot_id;
 pos:=coalesce(pos,'{}'::uuid[]);
 select coalesce(jsonb_agg(jsonb_build_object('allocation_id',planned_allocation.id,'product_id',si.product_id,'root_lot_id',c.root_lot_id,
  'po_id',c.po_id,'component_units',c.component_units,'hpp_per_pcs',c.hpp_per_pcs,'hpp_version_id',c.hpp_version_id)
  order by planned_allocation.id,c.root_lot_id),'[]')into component_plan from jsonb_array_elements(p_legacy->'items')as planned_item(value)
  join erp.sale_stock_allocations planned_allocation on planned_allocation.id=(planned_item.value->>'allocation_id')::uuid join erp.sales_items si on si.id=planned_allocation.sale_item_id
  cross join lateral cp7_sku_conversion.return_components_v2(planned_allocation.id,(planned_item.value->>'qty_pcs')::numeric,null)c;
 select coalesce(jsonb_agg(z order by z->>'po_id',z->>'product_id'),'[]')into scope_items from(
  select distinct jsonb_build_object('product_id',case when fl.po_id is null then si.product_id end,'po_id',fl.po_id)z
  from jsonb_array_elements(p_legacy->'items')as planned_item(value) join erp.sale_stock_allocations planned_allocation on planned_allocation.id=(planned_item.value->>'allocation_id')::uuid
  join erp.sales_items si on si.id=planned_allocation.sale_item_id join erp.fg_lots fl on fl.id=planned_allocation.lot_id
  union select distinct jsonb_build_object('product_id',case when planned_item.value->>'po_id'is null then(planned_item.value->>'product_id')::uuid end,'po_id',(planned_item.value->>'po_id')::uuid)
   from jsonb_array_elements(component_plan)as planned_item(value))s;
 select coalesce(array_agg(distinct id order by id),'{}'::uuid[])into pos from(
  select unnest(pos)id union select(planned_item.value->>'po_id')::uuid from jsonb_array_elements(scope_items)as planned_item(value) where planned_item.value->>'po_id'is not null)s;

 select coalesce(array_agg(distinct id order by id),'{}'::uuid[])into lots from(
  select id from erp.fg_lots where product_id=any(products)or po_id=any(pos)
  union select unnest(cp7_sku_conversion.hpp_scope_lot_ids_v2((planned_item.value->>'product_id')::uuid,(planned_item.value->>'po_id')::uuid))
   from jsonb_array_elements(scope_items)as planned_item(value))s;
 select coalesce(array_agg(id order by id),'{}'::uuid[])into versions from erp.hpp_versions where lot_id=any(lots);
 perform 1 from erp.locations where id in(select(value->>'location_id')::uuid from jsonb_array_elements(p_legacy->'items'))order by id for share;
 perform 1 from erp.fg_inventory_balances inv where exists(select 1 from jsonb_array_elements(p_legacy->'items')draft_item
  join erp.sale_stock_allocations sa on sa.id=(draft_item->>'allocation_id')::uuid join erp.sales_items si on si.id=sa.sale_item_id
  where inv.product_id=si.product_id and inv.location_id=(draft_item->>'location_id')::uuid and inv.quality_grade=draft_item->>'quality_grade')
  order by inv.product_id,inv.location_id,inv.quality_grade for update;
 -- Include PO siblings even when another product owns them. Never acquire
 -- newly discovered earlier-order rows from the completion callback.
 perform 1 from erp.fg_lots where id=any(lots)order by id for update;
 perform 1 from erp.hpp_versions where id=any(versions)order by id for share;
 perform 1 from erp.opening_lot_hpp_gl_state where lot_id=any(lots)order by lot_id for update;
 perform 1 from erp.opening_hpp_corrections where lot_id=any(lots)order by id for share;
 perform 1 from erp.po_hpp_gl_state where po_id=any(pos)order by po_id for update;
 select coalesce(array_agg(distinct id order by id),'{}'::uuid[])into fresh_lots from(
  select id from erp.fg_lots where product_id=any(products)or po_id=any(pos)
  union select unnest(cp7_sku_conversion.hpp_scope_lot_ids_v2((planned_item.value->>'product_id')::uuid,(planned_item.value->>'po_id')::uuid))
   from jsonb_array_elements(scope_items)as planned_item(value))s;
 select coalesce(array_agg(id order by id),'{}'::uuid[])into fresh_versions from erp.hpp_versions where lot_id=any(fresh_lots);
 select coalesce(jsonb_agg(jsonb_build_object('allocation_id',planned_allocation.id,'product_id',si.product_id,'root_lot_id',c.root_lot_id,
  'po_id',c.po_id,'component_units',c.component_units,'hpp_per_pcs',c.hpp_per_pcs,'hpp_version_id',c.hpp_version_id)
  order by planned_allocation.id,c.root_lot_id),'[]')into fresh_component_plan from jsonb_array_elements(p_legacy->'items')as planned_item(value)
  join erp.sale_stock_allocations planned_allocation on planned_allocation.id=(planned_item.value->>'allocation_id')::uuid join erp.sales_items si on si.id=planned_allocation.sale_item_id
  cross join lateral cp7_sku_conversion.return_components_v2(planned_allocation.id,(planned_item.value->>'qty_pcs')::numeric,null)c;
 if component_plan is distinct from fresh_component_plan or fresh_lots is distinct from lots or fresh_versions is distinct from versions then raise exception 'CP7_CREDIT_HPP_LOCK_SET_CHANGED';end if;
 account_facts:=cp7_credit.initial_hpp_account_facts_v1();
 fg_account:=cp7_credit.account_by_mapping_v1('FG_INVENTORY');cogs_account:=cp7_credit.account_by_mapping_v1('COGS');
 expense_account:=cp7_credit.account_by_mapping_v1('OTHER_EXPENSE');income_account:=cp7_credit.account_by_mapping_v1('OTHER_INCOME');
 if exists(select 1 from jsonb_array_elements(account_facts->'mappings')as mapped(value)where(mapped.value->>'account_id')::uuid is distinct from
  case mapped.value->>'mapping_key'when'FG_INVENTORY'then fg_account when'COGS'then cogs_account when'OTHER_EXPENSE'then expense_account else income_account end)then
  raise exception 'CP7_CREDIT_HPP_ACCOUNT_SOURCE_CHANGED';end if;
 for x in select value from jsonb_array_elements(p_legacy->'items')loop
  select sa.*,i.sale_id,i.product_id,fl.po_id,fl.lot_origin,hv.id hpp_id,hv.total_cost,hv.qty_basis_pcs,hv.hpp_per_pcs current_unit_snapshot into strict a
   from erp.sale_stock_allocations sa join erp.sales_items i on i.id=sa.sale_item_id join erp.fg_lots fl on fl.id=sa.lot_id
   join erp.hpp_versions hv on hv.lot_id=fl.id and hv.is_current where sa.id=(x->>'allocation_id')::uuid;
  if a.sale_id<>(p_legacy->>'sale_id')::uuid or a.qty_basis_pcs<=0 or a.lot_origin='VOIDED_PRODUCTION'
   or not exists(select 1 from erp.locations where id=(x->>'location_id')::uuid and is_active and location_type='FG_WAREHOUSE')then
   raise exception 'CP7_CREDIT_RETURN_SOURCE_OR_DESTINATION_CHANGED';end if;
  if a.total_cost::text in('NaN','Infinity','-Infinity')or a.current_unit_snapshot::text in('NaN','Infinity','-Infinity')then
   raise exception 'CP7_CREDIT_NONFINITE_HPP_SOURCE';end if;
  cost:=a.total_cost/a.qty_basis_pcs;
  if cost<0 then raise exception 'CP7_CREDIT_NEGATIVE_HPP_SOURCE';end if;
  select coalesce(sum(m.qty_signed),0)+coalesce(sum(abs(m.qty_signed))filter(where m.movement_type='SALE_RESERVE'
   and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=m.id)),0)into owned
   from erp.fg_stock_movements m where m.lot_id=a.lot_id;
  select coalesce(sum(sa.qty_pcs),0)into sold from erp.sale_stock_allocations sa join erp.sales_items si on si.id=sa.sale_item_id
   join erp.sales_headers sh on sh.id=si.sale_id where sa.lot_id=a.lot_id and sh.status in('POSTED','PARTIAL_PAID','PAID');
  select coalesce(sum(ri.qty_pcs),0)into returned from erp.sales_return_items ri join erp.sales_returns rr on rr.id=ri.return_id
   where ri.lot_id=a.lot_id and rr.status='POSTED';
  -- Preserve the retained Native allocation refusal before the extra HPP
  -- target checks; a prior completed return consumes this same allocation.
  if (x->>'qty_pcs')::numeric>a.qty_pcs-coalesce((select sum(ri.qty_pcs)from erp.sales_return_items ri join erp.sales_returns rr on rr.id=ri.return_id
    where rr.status='POSTED'and ri.sale_stock_allocation_id=a.id),0)then raise exception 'AH_RETURN_EXCEEDS_ORIGINAL_ALLOCATION';end if;
  if owned<0 or sold-returned<(select sum((v->>'qty_pcs')::numeric)from jsonb_array_elements(p_legacy->'items')v
   join erp.sale_stock_allocations s on s.id=(v->>'allocation_id')::uuid where s.lot_id=a.lot_id)then raise exception 'CP7_CREDIT_RETURN_QTY_SOURCE_INVALID';end if;
  items:=items||jsonb_build_array(x||jsonb_build_object('product_id',a.product_id,'lot_id',a.lot_id,'po_id',a.po_id,
   'hpp_version_id',a.hpp_id,'unit_hpp_raw',cost::text,'unit_hpp_snapshot',a.current_unit_snapshot::text));
 end loop;
 for r in select distinct case when z->>'po_id'is null then(z->>'product_id')::uuid end product_id,
  (z->>'po_id')::uuid po_id from jsonb_array_elements(scope_items)z
  order by po_id nulls first,product_id loop
  saved_state:=null;
  source_support:=cp7_credit.initial_hpp_support_v1(r.product_id,r.po_id);
  opening_source:=cp7_credit.initial_opening_hpp_source_v1(r.product_id,r.po_id);
  if r.po_id is null then
   select *into strict t from erp.compute_non_po_product_hpp_targets_v2620f(r.product_id);
   select coalesce(sum(l.debit-l.credit)filter(where l.account_id=fg_account),0)fg_value,
    coalesce(sum(l.debit-l.credit)filter(where l.account_id=cogs_account),0)cogs_value,
    coalesce(sum(l.debit-l.credit)filter(where l.account_id in(expense_account,income_account)),0)other_out_value
   into b from erp.journal_lines l join erp.journal_entries j on j.id=l.journal_entry_id left join erp.journal_entries o on o.id=j.reversal_of_id
    where l.product_id=r.product_id and l.po_id is null and j.status in('POSTED','REVERSED')
     and(j.source_type<>'PRODUCT_CONVERSION'or erp.be_nonpo_admitted_v1(j.source_id))
     and(j.source_type<>'JOURNAL_REVERSAL'or o.source_type is distinct from'PRODUCT_CONVERSION'or erp.be_nonpo_admitted_v1(o.source_id));
   if round(t.fg_value,2)<>b.fg_value or round(t.cogs_value,2)<>b.cogs_value or round(t.other_out_value,2)<>b.other_out_value then
    raise exception 'CP7_CREDIT_HPP_TARGET_BOOK_NOT_RECONCILED';end if;
   actual_book:=to_jsonb(b)||jsonb_build_object('hpp_total_cost',b.fg_value+b.cogs_value+b.other_out_value);
  else
   -- PO groups are emitted once, and the source is the actual Native book
   -- reader's safe private equivalent, not the possibly stale cache alone.
   select *into strict t from erp.compute_po_hpp_gl_targets_v2620d(r.po_id);
   select to_jsonb(st)into strict saved_state from erp.po_hpp_gl_state st where st.po_id=r.po_id;
   if t.base_output_qty is distinct from(saved_state->>'base_output_qty')::integer
    or t.hpp_total_cost is distinct from(saved_state->>'hpp_total_cost')::numeric
    or t.fg_value is distinct from(saved_state->>'fg_value')::numeric or t.cogs_value is distinct from(saved_state->>'cogs_value')::numeric
    or t.other_out_value is distinct from(saved_state->>'other_out_value')::numeric then
    raise exception 'CP7_CREDIT_HPP_TARGET_BOOK_NOT_RECONCILED';end if;
   actual_book:=cp7_credit.initial_po_hpp_book_v1(r.po_id,fg_account,cogs_account,expense_account,income_account);
   select (actual_book->>'hpp_total_cost')::numeric hpp_total_cost,(actual_book->>'fg_value')::numeric fg_value,
    (actual_book->>'cogs_value')::numeric cogs_value,(actual_book->>'other_out_value')::numeric other_out_value into b;
   if round(t.hpp_total_cost,2)<>b.hpp_total_cost or round(t.fg_value,2)<>b.fg_value or round(t.cogs_value,2)<>b.cogs_value
    or round(t.other_out_value,2)<>b.other_out_value then raise exception 'CP7_CREDIT_HPP_TARGET_BOOK_NOT_RECONCILED';end if;
  end if;
  before_profile:=cp7_credit.initial_hpp_targets_v1(r.product_id,r.po_id,items,false);
  after_profile:=cp7_credit.initial_hpp_targets_v1(r.product_id,r.po_id,items,true);
  before_target:=before_profile->'target';after_target:=after_profile->'target';
  if before_target is distinct from to_jsonb(t)then raise exception 'CP7_CREDIT_HPP_CANONICAL_TARGET_MISMATCH';end if;
  if exists(select 1 from jsonb_array_elements(before_profile->'lots')f where(f->>'unit_raw')::text in('NaN','Infinity','-Infinity')
   or(f->>'raw_total')::text in('NaN','Infinity','-Infinity')or(f->>'unit_raw')::numeric<0
   or(f->>'owned_qty')::numeric<0 or(f->>'sold_qty')::numeric-(f->>'returned_qty')::numeric<(f->>'requested_qty')::numeric)then
   raise exception 'CP7_CREDIT_RETURN_QTY_SOURCE_INVALID';end if;
  delta_fg:=(after_target->>'fg_value')::numeric-b.fg_value;
  delta_cogs:=(after_target->>'cogs_value')::numeric-b.cogs_value;
  delta_other:=(after_target->>'other_out_value')::numeric-b.other_out_value;
  if cp7_credit.initial_hpp_support_v1(r.product_id,r.po_id)is distinct from source_support then
   raise exception 'CP7_CREDIT_HPP_SUPPORT_CHANGED_DURING_READ';end if;
  if cp7_credit.initial_opening_hpp_source_v1(r.product_id,r.po_id)is distinct from opening_source then
   raise exception 'CP7_CREDIT_OPENING_HPP_SOURCE_CHANGED_DURING_READ';end if;
  if delta_fg+delta_cogs+delta_other<>0 or(after_target->>'hpp_total_cost')::numeric<>(before_target->>'hpp_total_cost')::numeric
   or r.po_id is not null and(delta_fg<0 or delta_cogs>0)then raise exception 'CP7_CREDIT_HPP_VECTOR_NOT_CONSERVED';end if;
  group_amount:=greatest(delta_fg,0)+greatest(delta_cogs,0)+greatest(delta_other,0);hpp:=hpp+group_amount;
  groups:=groups||jsonb_build_array(jsonb_build_object('product_id',case when r.po_id is null then r.product_id end,'po_id',r.po_id,
   'amount',cp7_credit.cent_text(group_amount),'before_target',before_target,'after_target',after_target,'before_book',actual_book,'before_saved_state',saved_state,
   'before_profile',before_profile,'after_profile',after_profile,'source_support',source_support,'opening_source',opening_source,
   'delta',jsonb_build_object('fg_value',delta_fg,'cogs_value',delta_cogs,'other_out_value',delta_other)));
  for x in select *from jsonb_array_elements(jsonb_build_array(
   jsonb_build_object('mapping_key','FG_INVENTORY','signed_amount',delta_fg),jsonb_build_object('mapping_key','COGS','signed_amount',delta_cogs),
   jsonb_build_object('mapping_key',case when delta_other>0 then'OTHER_EXPENSE'else'OTHER_INCOME'end,'signed_amount',delta_other)))loop
   if(x->>'signed_amount')::numeric<>0 then lines:=lines||jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
    'mapping_key',x->>'mapping_key','debit',greatest((x->>'signed_amount')::numeric,0),'credit',greatest(-(x->>'signed_amount')::numeric,0),
    'product_id',case when r.po_id is null then r.product_id end,'po_id',r.po_id)));end if;
  end loop;
 end loop;
 -- The existing source-bound NO_JOURNAL reader proves physical snapshot0.
 -- Do not silently widen it for positive-cost stock with a zero cent vector.
 if hpp=0 and(select coalesce(sum((v->>'refund_amount')::numeric),0)from jsonb_array_elements(items)v)=0
  and exists(select 1 from jsonb_array_elements(items)v where(v->>'unit_hpp_snapshot')::numeric>0)then
  raise exception 'CP7_CREDIT_POSITIVE_HPP_ZERO_VECTOR_UNPROVEN';end if;
 return jsonb_build_object('items',items,'groups',groups,'hpp_amount',cp7_credit.cent_text(hpp),'lines',lines,
  'economic_return_components',component_plan,'locked_lot_ids',to_jsonb(lots),'locked_hpp_version_ids',to_jsonb(versions),'account_facts',account_facts);
end $function$

cp7_sku_conversion.action_v1(text,jsonb,:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.action_v1(p_action text, p_payload jsonb, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare a text:=upper(btrim(coalesce(p_action,'')));v jsonb;prior jsonb;part jsonb;child_payload jsonb;child jsonb;
 ids jsonb:='[]'::jsonb;destinations jsonb:='[]'::jsonb;child_id uuid;v_group_id uuid;i int:=0;r record;
begin
 perform erp.require_permission('warehouse.brand_conversion.view');
 if a not in('POST','REVERSE','POST_USAGE','SAVE_REWORK','SAVE_REDYE','SET_REDYE_PRICE')then raise exception 'BE_ACTION_UNKNOWN: tindakan tidak dikenal';end if;
 if not(a='POST'and p_payload?'source_product_id')and not(a='REVERSE'and exists(select 1 from cp7_sku_conversion.members_v1 where conversion_id=(p_payload->>'conversion_id')::uuid))then
  return erp.save_product_conversion_action_v1(p_action,p_payload,p_request);end if;
 perform erp.require_permission('warehouse.brand_conversion.view');perform erp.require_permission(case when a='REVERSE'then 'warehouse.brand_conversion.reverse'else 'warehouse.brand_conversion.post'end);
 if a='REVERSE'then perform erp.require_owner_admin();end if;perform erp.require_internal();
 if p_request is null or jsonb_typeof(p_payload)is distinct from 'object'or octet_length(p_payload::text)>30000 then raise exception 'CP7_SKU_CONVERSION_REQUEST';end if;
 prior:=erp._idempotency_begin('cp7_sku_conversion_v1',p_request,erp._request_hash(jsonb_build_object('action',a,'payload',p_payload)));
 perform erp.require_permission('warehouse.brand_conversion.view');perform erp.require_permission(case when a='REVERSE'then 'warehouse.brand_conversion.reverse'else 'warehouse.brand_conversion.post'end);
 if a='REVERSE'then perform erp.require_owner_admin();end if;perform erp.require_internal();
 if prior is not null then return prior;end if;
 perform erp.pocket_period_lock_v1();perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 perform erp.require_permission('warehouse.brand_conversion.view');perform erp.require_permission(case when a='REVERSE'then 'warehouse.brand_conversion.reverse'else 'warehouse.brand_conversion.post'end);
 if a='REVERSE'then perform erp.require_owner_admin();end if;perform erp.require_internal();
 if a='POST'then
  if not(p_payload?'expected_version')then raise exception 'CP7_SKU_PREVIEW_REQUIRED';end if;
  v:=cp7_sku_conversion.preview_v1(p_payload);
  perform erp.require_permission('warehouse.brand_conversion.view');perform erp.require_permission('warehouse.brand_conversion.post');perform erp.require_internal();
  insert into cp7_sku_conversion.groups_v1(request_id,actor,payload)values(p_request,erp.current_app_user_id(),p_payload);
  perform cp7_sku_conversion.prepare_valuation_v2(p_request,v);
  insert into cp7_sku_conversion.execution_v1(backend_pid,transaction_id,group_id,mode)values(pg_backend_pid(),txid_current(),p_request,'POST');
  for part in select value from jsonb_array_elements(v->'allocations')with ordinality as parts(value,ordinal)order by ordinal loop
   i:=i+1;child_id:=case when i=1 then p_request else gen_random_uuid()end;
   update cp7_sku_conversion.execution_v1 set source_lot_id=(part->>'source_lot_id')::uuid,target_id=(v->>'target_product_id')::uuid,
    location_id=(v->>'location_id')::uuid,qty=(part->>'qty_pcs')::int,physical_at=(v->>'physical_at')::timestamptz
    where backend_pid=pg_backend_pid()and transaction_id=txid_current();
   child_payload:=jsonb_build_object('source_lot_id',part->'source_lot_id','target_product_id',v->'target_product_id','location_id',v->'location_id',
    'qty_pcs',part->'qty_pcs','physical_at',v->'physical_at','reason',p_payload->'reason','expected_version',part->'source_revision');
   if i=1 and p_payload?'expected_returns'then child_payload:=child_payload||jsonb_build_object('expected_returns',p_payload->'expected_returns');end if;
   child:=erp.save_product_conversion_action_v1('POST',child_payload,child_id);
   insert into cp7_sku_conversion.members_v1 values(child_id,p_request,i);
   ids:=ids||jsonb_build_array(child_id);destinations:=destinations||jsonb_build_array(child->'destination_lot_id');
  end loop;
  perform cp7_sku_conversion.finalize_valuation_v2(p_request);
  v:=v||jsonb_build_object('conversion_id',p_request,'destination_lot_id',destinations->0,'conversion_ids',ids,'destination_lot_ids',destinations,'status','POSTED');
 else
  perform erp._cp3_assert_closed_json_object(p_payload,array['conversion_id','reason'],array['conversion_id','reason'],'pembatalan konversi');
  perform erp.bc_text_v1(p_payload,'reason',true,1000);
  select m.group_id into strict v_group_id from cp7_sku_conversion.members_v1 m where m.conversion_id=(p_payload->>'conversion_id')::uuid;
  -- Validate every member before invoking any Native inverse. A rollback of
  -- an earlier member cannot undo Native audit or stock-book nextval calls.
  -- Keep the original BE and Native guards below as the posting authority.
  perform 1 from erp.product_conversions c join cp7_sku_conversion.members_v1 m on m.conversion_id=c.id
   where m.group_id=v_group_id order by c.id for update of c;
  perform erp.require_permission('warehouse.brand_conversion.view');perform erp.require_permission('warehouse.brand_conversion.reverse');
  perform erp.require_owner_admin();perform erp.require_internal();
  if exists(select 1 from cp7_sku_conversion.members_v1 m where m.group_id=v_group_id
   and not exists(select 1 from erp.be_conversion_sources_v1 s where s.conversion_id=m.conversion_id))then
   raise exception 'BE_DOCUMENT_NOT_FOUND';end if;
  if exists(select 1 from cp7_sku_conversion.members_v1 m join erp.be_conversion_cost_sources_v1 s on s.conversion_id=m.conversion_id
   join erp.bc_documents_v1 d on d.id=s.document_id where m.group_id=v_group_id and d.status='POSTED')then
   raise exception 'BE_REVERSE_DEPENDANTS: batalkan dahulu sumber biaya/pemulihan';end if;
  if exists(select 1 from cp7_sku_conversion.members_v1 m join erp.be_conversion_returns_v1 s on s.conversion_id=m.conversion_id
   join erp.bc_return_lots_v1 l on l.outstanding_id=s.outstanding_id join erp.bc_documents_v1 d on d.id=l.document_id
   where m.group_id=v_group_id and d.status='POSTED')then
   raise exception 'BE_REVERSE_DEPENDANTS: batalkan dahulu penerimaan bongkaran';end if;
  if exists(select 1 from cp7_sku_conversion.members_v1 m join erp.product_conversions c on c.id=m.conversion_id
   where m.group_id=v_group_id and c.status not in('POSTED','REVERSED'))then
   raise exception 'Hanya conversion/rebrand POSTED yang dapat direverse';end if;
  if exists(select 1 from cp7_sku_conversion.members_v1 m join erp.product_conversions c on c.id=m.conversion_id
   join erp.product_conversion_allocations a on a.conversion_id=c.id where m.group_id=v_group_id and c.status='POSTED'
   and erp.fg_lot_has_active_downstream(a.destination_lot_id,'REBRAND_IN','PRODUCT_CONVERSION',c.id))then
   raise exception 'Hasil conversion/rebrand masih dipakai transaksi downstream aktif. Reverse transaksi downstream terlebih dahulu.';end if;
  if exists(select 1 from cp7_sku_conversion.members_v1 m join erp.product_conversions c on c.id=m.conversion_id
   where m.group_id=v_group_id and c.status='POSTED'
   and (select coalesce(sum(a.qty_pcs*a.original_hpp_per_pcs),0)::numeric(24,6)from erp.product_conversion_allocations a where a.conversion_id=c.id)>0.005
   and not exists(select 1 from erp.journal_entries j where j.source_type='PRODUCT_CONVERSION'and j.source_id=c.id and j.status='POSTED'))then
   raise exception 'Jurnal conversion/rebrand tidak ditemukan; reversal dibatalkan agar nilai persediaan tidak rusak';end if;
  insert into cp7_sku_conversion.execution_v1(backend_pid,transaction_id,group_id,mode)values(pg_backend_pid(),txid_current(),v_group_id,'REVERSE');
  for r in select m.conversion_id from cp7_sku_conversion.members_v1 m where m.group_id=v_group_id order by line_no desc loop
   child:=erp.save_product_conversion_action_v1('REVERSE',jsonb_build_object('conversion_id',r.conversion_id,'reason',p_payload->'reason'),
     case when r.conversion_id=(p_payload->>'conversion_id')::uuid then p_request else gen_random_uuid()end);
   ids:=ids||jsonb_build_array(r.conversion_id);
  end loop;
  perform cp7_sku_conversion.reverse_valuation_v2(v_group_id);
  v:=jsonb_build_object('conversion_id',p_payload->'conversion_id','conversion_ids',ids,'status','REVERSED');
 end if;
 delete from cp7_sku_conversion.execution_v1 where backend_pid=pg_backend_pid()and transaction_id=txid_current();
 return erp._idempotency_complete('cp7_sku_conversion_v1',p_request,v||jsonb_build_object('request_id',p_request,'action',a));
end $function$

cp7_sku_conversion.pool_quote_v2(uuid,uu:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.pool_quote_v2(p_product uuid, p_location uuid, p_grade text DEFAULT 'GRADE_A'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare v_qty numeric(20,6);v_base numeric(24,6);v_adjust numeric(24,6);v_value numeric(24,6);v_attr numeric(24,6);v_unknown boolean;v_revision text;
begin
 if p_product is null or p_location is null or p_grade is distinct from 'GRADE_A' then raise exception 'CP7_SKU_VALUE_SCOPE_REQUIRED';end if;
 with components as materialized(
  select c.*,h.cost_state,l.po_id root_po_id
  from cp7_sku_conversion.pool_components_v2(p_product,p_location,p_grade)c
  join erp.fg_lots l on l.id=c.root_lot_id
  left join erp.hpp_versions h on h.id=c.hpp_version_id
 ), totals as(
  select coalesce(sum(component_units),0)::numeric qty,coalesce(sum(value),0)::numeric value,
   coalesce(bool_or(component_units< -0.000000000001 or hpp_version_id is null or unit_value is null or cost_state='ESTIMATED'
    or erp.bd_lot_laundry_unknown_v1(root_lot_id)
    or(root_po_id is not null and not exists(select 1 from erp.get_hpp_completeness(root_po_id)z where z.pending_reason_count=0))),false) unknown
  from components
 )select qty,round(value,6),unknown into v_qty,v_value,v_unknown from totals;
 if v_unknown then raise exception 'CP7_SKU_POOL_HPP_UNKNOWN: seluruh komponen ekonomi termasuk reservasi harus diketahui';end if;
 v_base:=v_value;v_adjust:=0;
 if v_value<0 then raise exception 'CP7_SKU_POOL_VALUE_NEGATIVE: nilai efektif persediaan tidak boleh negatif';end if;
 select coalesce(sum(a.value),0)into v_attr from cp7_sku_conversion.pool_attribution_v2(p_product,p_location,p_grade)a;
 if round(v_attr,6)is distinct from v_value then raise exception 'CP7_SKU_POOL_ATTRIBUTION_MISMATCH';end if;
 select md5(jsonb_build_object('product',p_product,'location',p_location,'grade',p_grade,'qty',v_qty,'base',v_base,'adjust',v_adjust,
  'components',(select coalesce(jsonb_agg(to_jsonb(c)order by c.root_lot_id),'[]'::jsonb)
   from cp7_sku_conversion.pool_components_v2(p_product,p_location,p_grade)c),
  'events',(select coalesce(jsonb_agg(to_jsonb(e)order by e.recorded_at,e.id),'[]'::jsonb)from cp7_sku_conversion.valuation_events_v2 e
   where e.product_id=p_product and e.location_id=p_location and e.quality_grade=p_grade))::text) into v_revision;
 return jsonb_build_object('state',case when v_qty=0 then 'EMPTY' else 'KNOWN'end,'qty',v_qty::text,'value',v_value::text,
  'average',case when v_qty>0 then (v_value/v_qty)::text end,'base_value',v_base::text,'adjustment',v_adjust::text,
  'reserved_included',true,'basis','SKU_LOCATION_GRADE_MOVING_AVERAGE_V2','revision',v_revision);
end $function$

cp7_sku_conversion.prepare_return_values:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.prepare_return_values_v2(p_return uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare r record;v_value numeric(24,2);v_legacy numeric(24,2);v_line integer:=0;pool record;v_components jsonb;
begin
 perform erp.require_internal();
 if exists(select 1 from cp7_sku_conversion.sales_return_values_v2 where return_id=p_return)then raise exception 'CP7_SKU_RETURN_VALUE_ALREADY_PREPARED';end if;
 for r in select i.id,i.return_id,i.sale_stock_allocation_id,i.product_id,i.lot_id,i.location_id,i.quality_grade,i.qty_pcs,
   a.qty_pcs sold_qty,h.hpp_per_pcs
  from erp.sales_return_items i join cp7_sku_conversion.sale_allocation_values_v2 a on a.sale_stock_allocation_id=i.sale_stock_allocation_id
  join erp.hpp_versions h on h.lot_id=i.lot_id and h.is_current
  where i.return_id=p_return order by i.sale_stock_allocation_id,i.id loop
  -- Pending rows of this draft are included explicitly, while the shared
  -- owned projection excludes draft effects. Every financial scope therefore
  -- receives exactly its current cumulative FG target change, including the
  -- cent carried from earlier returns, other allocations, reversals or recost.
  with raw as(
   select *from cp7_sku_conversion.return_components_v2(r.sale_stock_allocation_id,r.qty_pcs,p_return)
  ), scoped as(
   select po_id,sum(component_units*hpp_per_pcs)::numeric added_value from raw where component_units>0 group by po_id
  ), before_values as(
   select k.po_id,k.added_value,cp7_sku_conversion.owned_scope_value_v2(r.product_id,k.po_id)
    +coalesce((select sum(c.component_units*h.hpp_per_pcs)
      from cp7_sku_conversion.sales_return_components_v2 c join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
      join erp.hpp_versions h on h.lot_id=c.root_lot_id and h.is_current
      where v.return_id=p_return and c.po_id is not distinct from k.po_id
       and(k.po_id is not null or v.product_id=r.product_id)),0)::numeric before_value
   from scoped k
  ), scope_cents as(
   select po_id,added_value,round(before_value+added_value,2)-round(before_value,2)effective_value from before_values
  ), ranked as(
   select c.*,k.effective_value,k.added_value,
    sum(c.component_units*c.hpp_per_pcs)over(partition by c.po_id order by c.root_lot_id rows unbounded preceding)cumulative_raw
   from raw c join scope_cents k on k.po_id is not distinct from c.po_id where c.component_units>0
  ), targets as(
   select *,case when effective_value=0 then 0 else round(cumulative_raw*effective_value/nullif(added_value,0),2)end cumulative_target from ranked
  ), shares as(
   select row_number()over(order by root_lot_id)::integer line_no,root_lot_id,po_id,component_units,
    cumulative_target-coalesce(lag(cumulative_target)over(partition by po_id order by root_lot_id),0)booked_value from targets
  )select coalesce(jsonb_agg(to_jsonb(shares)order by line_no),'[]'::jsonb),coalesce(sum(booked_value),0)
    into v_components,v_value from shares;
  v_legacy:=round(r.qty_pcs*r.hpp_per_pcs,2);
  insert into cp7_sku_conversion.sales_return_values_v2(sales_return_item_id,return_id,sale_stock_allocation_id,product_id,lot_id,location_id,quality_grade,qty_pcs,effective_value,legacy_value,effective_unit_value)
  values(r.id,p_return,r.sale_stock_allocation_id,r.product_id,r.lot_id,r.location_id,r.quality_grade,r.qty_pcs,v_value,v_legacy,v_value/r.qty_pcs);
  insert into cp7_sku_conversion.sales_return_components_v2(sales_return_item_id,line_no,root_lot_id,po_id,component_units,booked_value)
  select r.id,c.line_no,c.root_lot_id,c.po_id,c.component_units,c.booked_value
   from jsonb_to_recordset(v_components)as c(line_no integer,root_lot_id uuid,po_id uuid,component_units numeric,booked_value numeric)order by c.line_no;
  if abs(r.qty_pcs-coalesce((select sum(c.component_units)from cp7_sku_conversion.sales_return_components_v2 c where c.sales_return_item_id=r.id),0))>0.000000000001
   or v_value is distinct from(select sum(c.booked_value)from cp7_sku_conversion.sales_return_components_v2 c where c.sales_return_item_id=r.id)then
   raise exception 'CP7_SKU_RETURN_COMPONENT_MISMATCH';end if;
  with economic as(
   select po_id,sum(booked_value)::numeric effective from cp7_sku_conversion.sales_return_components_v2 where sales_return_item_id=r.id group by po_id
  ), keys as(
   select po_id from economic union select l.po_id from erp.fg_lots l where l.id=r.lot_id
  ), numbered as(
   select row_number()over(order by k.po_id nulls last)::integer line_no,k.po_id,coalesce(e.effective,0)::numeric effective,
    case when k.po_id is not distinct from l.po_id then v_legacy else 0 end::numeric legacy
   from keys k left join economic e on e.po_id is not distinct from k.po_id cross join erp.fg_lots l where l.id=r.lot_id
  )
  insert into cp7_sku_conversion.sales_return_attributions_v2(sales_return_item_id,line_no,po_id,product_id,location_id,quality_grade,effective_value,legacy_value,adjustment_delta)
  select r.id,line_no,po_id,r.product_id,r.location_id,r.quality_grade,effective,legacy,effective-legacy from numbered order by line_no;
  if v_value is distinct from(select sum(a.effective_value)from cp7_sku_conversion.sales_return_attributions_v2 a where a.sales_return_item_id=r.id)
   or v_legacy is distinct from(select sum(a.legacy_value)from cp7_sku_conversion.sales_return_attributions_v2 a where a.sales_return_item_id=r.id)then
   raise exception 'CP7_SKU_RETURN_ATTRIBUTION_MISMATCH';end if;
 end loop;
 for pool in select product_id,location_id,quality_grade,sum(qty_pcs)::numeric qty,sum(effective_value)::numeric effective,sum(legacy_value)::numeric legacy
  from cp7_sku_conversion.sales_return_values_v2 where return_id=p_return group by product_id,location_id,quality_grade order by product_id,location_id,quality_grade loop
  v_line:=v_line+1;
  insert into cp7_sku_conversion.valuation_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,qty_delta,effective_value_delta,legacy_value_delta,adjustment_delta,physical_at,economic_date)
  select gen_random_uuid(),null,'SALES_RETURN',p_return,v_line,'POST','POOL',pool.product_id,pool.location_id,pool.quality_grade,pool.qty,pool.effective,pool.legacy,
   pool.effective-pool.legacy,h.physical_at,(h.physical_at at time zone 'Asia/Jakarta')::date from erp.sales_returns h where h.id=p_return;
 end loop;
 with entries as(
  select v.product_id,v.location_id,v.quality_grade,c.root_lot_id,c.component_units::numeric units
  from cp7_sku_conversion.sales_return_components_v2 c join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
  where v.return_id=p_return
  union all
  select v.product_id,v.location_id,v.quality_grade,v.lot_id,-v.qty_pcs::numeric
  from cp7_sku_conversion.sales_return_values_v2 v where v.return_id=p_return
 ), compact as(
  select product_id,location_id,quality_grade,root_lot_id,sum(units)::numeric units from entries
  group by product_id,location_id,quality_grade,root_lot_id having abs(sum(units))>0.000000000001
 ), numbered as(
  select row_number()over(order by product_id,location_id,quality_grade,root_lot_id)::integer line_no,*from compact
 )
 insert into cp7_sku_conversion.component_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,root_lot_id,units_delta,physical_at,economic_date)
 select gen_random_uuid(),null,'SALES_RETURN',p_return,line_no,'POST','POOL',product_id,location_id,quality_grade,root_lot_id,units,h.physical_at,
  (h.physical_at at time zone 'Asia/Jakarta')::date from numbered cross join erp.sales_returns h where h.id=p_return order by line_no;
 if exists(select 1 from cp7_sku_conversion.component_events_v2 where source_type='SALES_RETURN'and source_id=p_return and phase='POST'
  group by product_id,location_id,quality_grade having abs(sum(units_delta))>0.000000000001)then
  raise exception 'CP7_SKU_RETURN_COMPONENT_QTY_NOT_CONSERVED';end if;
end $function$

cp7_sku_conversion.prepare_sale_values_v:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.prepare_sale_values_v2(p_sale uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare pool record;v_allocation record;q jsonb;v_average numeric;v_effective numeric(24,2);v_prior numeric(24,2);v_total_effective numeric(24,2);v_total_legacy numeric(24,2);v_qty integer;v_line integer:=0;
begin
 perform erp.require_internal();
 if exists(select 1 from cp7_sku_conversion.sale_allocation_values_v2 where sale_id=p_sale)then raise exception 'CP7_SKU_SALE_VALUE_ALREADY_PREPARED';end if;
 for pool in select i.product_id,a.location_id,sum(a.qty_pcs)::integer qty
  from erp.sale_stock_allocations a join erp.sales_items i on i.id=a.sale_item_id
  where i.sale_id=p_sale group by i.product_id,a.location_id order by i.product_id,a.location_id loop
  q:=cp7_sku_conversion.pool_quote_v2(pool.product_id,pool.location_id,'GRADE_A');
  if(q->>'qty')::numeric<pool.qty then raise exception 'CP7_SKU_SALE_VALUE_POOL_SHORT';end if;
  v_average:=(q->>'average')::numeric;v_prior:=0;v_total_legacy:=0;v_line:=v_line+1;
  for v_allocation in select a.id,i.product_id,a.lot_id,a.location_id,a.qty_pcs,h.hpp_per_pcs,
      sum(a.qty_pcs)over(order by a.id rows unbounded preceding)::numeric cumulative_qty
    from erp.sale_stock_allocations a join erp.sales_items i on i.id=a.sale_item_id
    join erp.hpp_versions h on h.lot_id=a.lot_id and h.is_current
    where i.sale_id=p_sale and i.product_id=pool.product_id and a.location_id=pool.location_id order by a.id loop
   v_effective:=round(v_allocation.cumulative_qty*v_average,2)-v_prior;v_prior:=v_prior+v_effective;
   insert into cp7_sku_conversion.sale_allocation_values_v2(sale_stock_allocation_id,sale_id,product_id,lot_id,location_id,quality_grade,qty_pcs,effective_value,legacy_value,effective_unit_value,pool_revision)
   values(v_allocation.id,p_sale,v_allocation.product_id,v_allocation.lot_id,v_allocation.location_id,'GRADE_A',v_allocation.qty_pcs,v_effective,round(v_allocation.qty_pcs*v_allocation.hpp_per_pcs,2),v_effective/v_allocation.qty_pcs,q->>'revision');
   v_total_legacy:=v_total_legacy+round(v_allocation.qty_pcs*v_allocation.hpp_per_pcs,2);
  end loop;
  v_qty:=pool.qty;v_total_effective:=round(v_qty*v_average,2);
  if v_prior is distinct from v_total_effective then raise exception 'CP7_SKU_SALE_CENT_APPORTIONMENT';end if;
  -- Every physical allocation carries the same economic pool mix. Cutting
  -- consecutive root intervals would return a different HPP for each FIFO lot.
  with matrix as(
   select v.sale_stock_allocation_id,c.root_lot_id,c.po_id,c.unit_value,
    (round(v.qty_pcs*sum(c.component_units)over(partition by v.sale_stock_allocation_id
      order by c.root_lot_id rows unbounded preceding)/(q->>'qty')::numeric,12)
     -round(v.qty_pcs*coalesce(sum(c.component_units)over(partition by v.sale_stock_allocation_id
      order by c.root_lot_id rows between unbounded preceding and 1 preceding),0)/(q->>'qty')::numeric,12))::numeric component_units,
    v.effective_value
   from cp7_sku_conversion.sale_allocation_values_v2 v
   cross join cp7_sku_conversion.pool_components_v2(pool.product_id,pool.location_id,'GRADE_A')c
   where v.sale_id=p_sale and v.product_id=pool.product_id and v.location_id=pool.location_id
  ), raw as(
   select *,component_units*unit_value raw_value,
    sum(component_units*unit_value)over(partition by sale_stock_allocation_id order by root_lot_id rows unbounded preceding)cumulative_raw,
    sum(component_units*unit_value)over(partition by sale_stock_allocation_id)total_raw
   from matrix where component_units>0
  ), targets as(
   select *,case when effective_value=0 then 0 else round(cumulative_raw*effective_value/nullif(total_raw,0),2)end cumulative_target
   from raw
  ), shares as(
   select row_number()over(partition by sale_stock_allocation_id order by root_lot_id)::integer line_no,*,
    cumulative_target-coalesce(lag(cumulative_target)over(partition by sale_stock_allocation_id order by root_lot_id),0)booked_value
   from targets
  )
  insert into cp7_sku_conversion.sale_allocation_components_v2(sale_stock_allocation_id,line_no,root_lot_id,po_id,component_units,booked_value)
  select sale_stock_allocation_id,line_no,root_lot_id,po_id,component_units,booked_value from shares order by sale_stock_allocation_id,line_no;
  if exists(select 1 from cp7_sku_conversion.sale_allocation_values_v2 v where v.sale_id=p_sale and v.product_id=pool.product_id and v.location_id=pool.location_id
   and(abs(v.qty_pcs-coalesce((select sum(c.component_units)from cp7_sku_conversion.sale_allocation_components_v2 c where c.sale_stock_allocation_id=v.sale_stock_allocation_id),0))>0.000000000001
    or v.effective_value is distinct from(select sum(c.booked_value)from cp7_sku_conversion.sale_allocation_components_v2 c where c.sale_stock_allocation_id=v.sale_stock_allocation_id)))then
   raise exception 'CP7_SKU_SALE_COMPONENT_MISMATCH';end if;
  with allocation_ranked as(
   select v.sale_stock_allocation_id,v.product_id,v.location_id,v.effective_value,v.legacy_value,l.po_id physical_po
   from cp7_sku_conversion.sale_allocation_values_v2 v join erp.fg_lots l on l.id=v.lot_id
   where v.sale_id=p_sale and v.product_id=pool.product_id and v.location_id=pool.location_id
  ), economic as(
   select c.sale_stock_allocation_id,c.po_id,sum(c.booked_value)::numeric effective
   from cp7_sku_conversion.sale_allocation_components_v2 c join allocation_ranked a using(sale_stock_allocation_id)
   group by c.sale_stock_allocation_id,c.po_id
  ), keys as(
   select sale_stock_allocation_id,po_id from economic
   union select sale_stock_allocation_id,physical_po from allocation_ranked
  ), numbered as(
   select row_number()over(partition by k.sale_stock_allocation_id order by k.po_id nulls last)::integer line_no,k.sale_stock_allocation_id,k.po_id,
    a.product_id,a.location_id,coalesce(e.effective,0)::numeric effective,
    case when k.po_id is not distinct from a.physical_po then a.legacy_value else 0 end::numeric legacy
   from keys k join allocation_ranked a using(sale_stock_allocation_id)
   left join economic e on e.sale_stock_allocation_id=k.sale_stock_allocation_id and e.po_id is not distinct from k.po_id
  )
  insert into cp7_sku_conversion.sale_allocation_attributions_v2(sale_stock_allocation_id,line_no,po_id,product_id,location_id,quality_grade,effective_value,legacy_value,adjustment_delta)
  select sale_stock_allocation_id,line_no,po_id,product_id,location_id,'GRADE_A',effective,legacy,legacy-effective from numbered order by sale_stock_allocation_id,line_no;
  if exists(select 1 from cp7_sku_conversion.sale_allocation_values_v2 v where v.sale_id=p_sale and v.product_id=pool.product_id and v.location_id=pool.location_id
   and(v.effective_value is distinct from(select sum(a.effective_value)from cp7_sku_conversion.sale_allocation_attributions_v2 a where a.sale_stock_allocation_id=v.sale_stock_allocation_id)
    or v.legacy_value is distinct from(select sum(a.legacy_value)from cp7_sku_conversion.sale_allocation_attributions_v2 a where a.sale_stock_allocation_id=v.sale_stock_allocation_id)))then
   raise exception 'CP7_SKU_SALE_ATTRIBUTION_MISMATCH';end if;
  insert into cp7_sku_conversion.valuation_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,qty_delta,effective_value_delta,legacy_value_delta,adjustment_delta,physical_at,economic_date)
  select gen_random_uuid(),null,'SALE',p_sale,v_line,'POST','POOL',pool.product_id,pool.location_id,'GRADE_A',-v_qty,-v_total_effective,-v_total_legacy,
   v_total_legacy-v_total_effective,h.sale_date,(h.sale_date at time zone 'Asia/Jakarta')::date from erp.sales_headers h where h.id=p_sale;
 end loop;
 with entries as(
  select v.product_id,v.location_id,v.quality_grade,c.root_lot_id,-c.component_units::numeric units
  from cp7_sku_conversion.sale_allocation_components_v2 c
  join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)where v.sale_id=p_sale
  union all
  select v.product_id,v.location_id,v.quality_grade,v.lot_id,v.qty_pcs::numeric
  from cp7_sku_conversion.sale_allocation_values_v2 v where v.sale_id=p_sale
 ), compact as(
  select product_id,location_id,quality_grade,root_lot_id,sum(units)::numeric units from entries
  group by product_id,location_id,quality_grade,root_lot_id having abs(sum(units))>0.000000000001
 ), numbered as(
  select row_number()over(order by product_id,location_id,quality_grade,root_lot_id)::integer line_no,*from compact
 )
 insert into cp7_sku_conversion.component_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,root_lot_id,units_delta,physical_at,economic_date)
 select gen_random_uuid(),null,'SALE',p_sale,line_no,'POST','POOL',product_id,location_id,quality_grade,root_lot_id,units,h.sale_date,
  (h.sale_date at time zone 'Asia/Jakarta')::date from numbered cross join erp.sales_headers h where h.id=p_sale order by line_no;
 if exists(select 1 from cp7_sku_conversion.component_events_v2 where source_type='SALE'and source_id=p_sale and phase='POST'
  group by product_id,location_id,quality_grade having abs(sum(units_delta))>0.000000000001)then
  raise exception 'CP7_SKU_SALE_COMPONENT_QTY_NOT_CONSERVED';end if;
end $function$

cp7_sku_conversion.prepare_valuation_v2(:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.prepare_valuation_v2(p_group uuid, p_preview jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare s jsonb;t jsonb;v_qty integer:=(p_preview->>'qty_pcs')::integer;v_transfer numeric(24,2);v_revision text;
begin
 perform erp.require_internal();perform erp.require_permission('warehouse.brand_conversion.post');
 if p_group is null then raise exception 'CP7_SKU_MOVAVG_PREVIEW_REQUIRED';end if;
 s:=cp7_sku_conversion.pool_quote_v2((p_preview->>'source_product_id')::uuid,(p_preview->>'location_id')::uuid,'GRADE_A');
 t:=cp7_sku_conversion.pool_quote_v2((p_preview->>'target_product_id')::uuid,(p_preview->>'location_id')::uuid,'GRADE_A');
 if (s->>'revision')is distinct from(p_preview->>'source_value_revision')or(t->>'revision')is distinct from(p_preview->>'target_value_revision')then
  raise exception 'STALE_VERSION: nilai rata-rata sumber atau tujuan berubah; periksa pratinjau terbaru';end if;
 v_transfer:=round(v_qty*(s->>'average')::numeric,2);
 v_revision:=md5(jsonb_build_object('source',s->>'revision','target',t->>'revision','qty',v_qty,'transfer',v_transfer)::text);
 insert into cp7_sku_conversion.valuation_quotes_v2(group_id,source_product_id,target_product_id,location_id,quality_grade,qty_pcs,physical_at,
  source_before_qty,source_before_value,source_before_average,target_before_qty,target_before_value,target_before_average,transfer_value,valuation_revision)
 values(p_group,(p_preview->>'source_product_id')::uuid,(p_preview->>'target_product_id')::uuid,(p_preview->>'location_id')::uuid,'GRADE_A',v_qty,
  (p_preview->>'physical_at')::timestamptz,(s->>'qty')::numeric,(s->>'value')::numeric,(s->>'average')::numeric,
  (t->>'qty')::numeric,(t->>'value')::numeric,case when t->>'average' is null then null else(t->>'average')::numeric end,v_transfer,v_revision);
 with components as materialized(
  select c.line_no,c.root_lot_id,c.po_id,c.hpp_version_id,c.component_units pool_component_units,c.unit_value,c.value contributed_value,
   c.component_units*v_qty/(s->>'qty')::numeric transfer_units,
   c.component_units*v_qty/(s->>'qty')::numeric*c.unit_value transfer_raw_value
  from cp7_sku_conversion.pool_components_v2((p_preview->>'source_product_id')::uuid,(p_preview->>'location_id')::uuid,'GRADE_A')c
 ), ranked as(
  select c.*,sum(transfer_raw_value)over(order by line_no rows unbounded preceding)cumulative_value,
   sum(transfer_raw_value)over() total_raw_value
  from components c
 ), targets as(
  select r.*,case when v_transfer=0 then 0 else round(cumulative_value*v_transfer/nullif(total_raw_value,0),2)end cumulative_target
  from ranked r
 ), shares as(
  select t.*,cumulative_target-coalesce(lag(cumulative_target)over(order by line_no),0)transfer_share from targets t
 )
 insert into cp7_sku_conversion.valuation_contributors_v2(group_id,line_no,root_lot_id,po_id,hpp_version_id,pool_component_units,transfer_units,unit_value,contributed_value,transfer_value)
 select p_group,line_no,root_lot_id,po_id,hpp_version_id,pool_component_units,transfer_units,unit_value,contributed_value,transfer_share from shares order by line_no;
 if (select round(sum(contributed_value),6)from cp7_sku_conversion.valuation_contributors_v2 where group_id=p_group)
    is distinct from round((s->>'base_value')::numeric,6) then raise exception 'CP7_SKU_MOVAVG_CONTRIBUTOR_MISMATCH';end if;
 if (select coalesce(sum(transfer_value),0)from cp7_sku_conversion.valuation_contributors_v2 where group_id=p_group)
    is distinct from v_transfer then raise exception 'CP7_SKU_MOVAVG_CONTRIBUTOR_CENT_MISMATCH';end if;
 if abs((select coalesce(sum(transfer_units),0)from cp7_sku_conversion.valuation_contributors_v2 where group_id=p_group)-v_qty)>0.000000000001
    then raise exception 'CP7_SKU_MOVAVG_COMPONENT_QTY_MISMATCH';end if;
end $function$

cp7_sku_conversion.return_components_v2(:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.return_components_v2(p_allocation uuid, p_qty numeric, p_current_return uuid)
 RETURNS TABLE(root_lot_id uuid, po_id uuid, component_units numeric, hpp_per_pcs numeric, hpp_version_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare v_sold numeric;v_prior numeric;v_plan jsonb;v_legacy boolean;
begin
 perform erp.require_internal();
 if p_qty is null or p_qty<=0 or p_qty<>trunc(p_qty)or p_qty::text in('NaN','Infinity','-Infinity')then
  raise exception 'CP7_SKU_RETURN_COMPONENT_QTY_INVALID';end if;
 select v.qty_pcs into v_sold from cp7_sku_conversion.sale_allocation_values_v2 v where v.sale_stock_allocation_id=p_allocation;
 v_legacy:=not found;
 if v_legacy then select a.qty_pcs into strict v_sold from erp.sale_stock_allocations a where a.id=p_allocation;end if;
 select coalesce(sum(i.qty_pcs),0)into v_prior from erp.sales_return_items i join erp.sales_returns h on h.id=i.return_id
  where i.sale_stock_allocation_id=p_allocation and h.status='POSTED';
 if p_current_return is not null then
  v_prior:=v_prior+coalesce((select sum(v.qty_pcs)from cp7_sku_conversion.sales_return_values_v2 v
   where v.sale_stock_allocation_id=p_allocation and v.return_id=p_current_return),0);
 end if;
 if v_prior+p_qty>v_sold then raise exception 'CP7_SKU_RETURN_VALUE_EXCEEDS_SALE_ALLOCATION';end if;
 with prior as(
  select c.root_lot_id,sum(c.component_units)::numeric units from cp7_sku_conversion.sales_return_components_v2 c
  join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)join erp.sales_returns h on h.id=v.return_id
  where v.sale_stock_allocation_id=p_allocation and(h.status='POSTED'or h.id=p_current_return)group by c.root_lot_id
 ), planned as(
  select c.root_lot_id,c.po_id,((v_prior+p_qty)*c.component_units/v_sold-coalesce(p.units,0))::numeric(30,12) units
  from cp7_sku_conversion.sale_allocation_components_v2 c left join prior p on p.root_lot_id=c.root_lot_id
  where c.sale_stock_allocation_id=p_allocation and not v_legacy
  union all select a.lot_id,l.po_id,p_qty::numeric(30,12)from erp.sale_stock_allocations a join erp.fg_lots l on l.id=a.lot_id
   where a.id=p_allocation and v_legacy
 )select coalesce(jsonb_agg(jsonb_build_object('root_lot_id',p.root_lot_id,'po_id',p.po_id,'component_units',p.units,
   'hpp_per_pcs',h.hpp_per_pcs,'hpp_version_id',h.id,'root_po_id',l.po_id,'cost_state',h.cost_state,
   'laundry_unknown',erp.bd_lot_laundry_unknown_v1(p.root_lot_id))order by p.root_lot_id),'[]')into v_plan
 from planned p left join erp.fg_lots l on l.id=p.root_lot_id left join erp.hpp_versions h on h.lot_id=p.root_lot_id and h.is_current;
 if exists(select 1 from jsonb_array_elements(v_plan)c where c->>'hpp_version_id'is null or c->>'hpp_per_pcs'is null
  or c->>'cost_state'='ESTIMATED'or(c->>'laundry_unknown')::boolean
  or(c->>'hpp_per_pcs')::numeric<0 or c->>'hpp_per_pcs'in('NaN','Infinity','-Infinity')
  or c->'po_id'is distinct from c->'root_po_id')then raise exception 'CP7_SKU_RETURN_COMPONENT_HPP_UNKNOWN';end if;
 if exists(select 1 from jsonb_array_elements(v_plan)c where(c->>'component_units')::numeric<0)
  or abs(p_qty-coalesce((select sum((c->>'component_units')::numeric)from jsonb_array_elements(v_plan)c),0))>0.000000000001 then
  raise exception 'CP7_SKU_RETURN_COMPONENT_MISMATCH';end if;
 return query select c.root_lot_id,c.po_id,c.component_units,c.hpp_per_pcs,c.hpp_version_id
  from jsonb_to_recordset(v_plan)c(root_lot_id uuid,po_id uuid,component_units numeric,hpp_per_pcs numeric,hpp_version_id uuid)
  where c.component_units>0 order by c.root_lot_id;
end $function$

cp7_sku_conversion.reverse_valuation_v2(:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.reverse_valuation_v2(p_group uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare q cp7_sku_conversion.valuation_quotes_v2%rowtype;p cp7_sku_conversion.valuation_postings_v2%rowtype;v_journal uuid;v_delta numeric(24,2);v_lines jsonb:='[]'::jsonb;r record;
begin
 perform erp.require_internal();perform erp.require_permission('warehouse.brand_conversion.reverse');perform erp.require_owner_admin();
 select *into strict q from cp7_sku_conversion.valuation_quotes_v2 where group_id=p_group;
 select *into strict p from cp7_sku_conversion.valuation_postings_v2 where group_id=p_group and phase='POST';
 if exists(select 1 from cp7_sku_conversion.valuation_postings_v2 where group_id=p_group and phase='REVERSE')then raise exception 'CP7_SKU_MOVAVG_ALREADY_REVERSED';end if;
 v_delta:=-p.correction_value;
 insert into cp7_sku_conversion.valuation_attributions_v2(group_id,phase,side,line_no,po_id,product_id,effective_value_delta,legacy_value_delta,adjustment_delta,supersedes_phase)
 select group_id,'REVERSE',side,line_no,po_id,product_id,-effective_value_delta,-legacy_value_delta,-adjustment_delta,'POST'
 from cp7_sku_conversion.valuation_attributions_v2 where group_id=p_group and phase='POST';
 for r in select *from cp7_sku_conversion.valuation_attributions_v2 where group_id=p_group and phase='REVERSE'and side='TARGET'and abs(adjustment_delta)>0.005 order by line_no loop
  v_lines:=v_lines||jsonb_build_array(
   (case when r.adjustment_delta>0 then jsonb_build_object('mapping_key','FG_INVENTORY','debit',r.adjustment_delta,'credit',0)
    else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',abs(r.adjustment_delta))end)
    ||case when r.po_id is null then jsonb_build_object('product_id',q.target_product_id)else jsonb_build_object('po_id',r.po_id)end,
   (case when r.adjustment_delta>0 then jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',r.adjustment_delta)
    else jsonb_build_object('mapping_key','FG_INVENTORY','debit',abs(r.adjustment_delta),'credit',0)end)
    ||case when r.po_id is null then jsonb_build_object('product_id',q.source_product_id)else jsonb_build_object('po_id',r.po_id)end);
 end loop;
 if jsonb_array_length(v_lines)>0 then v_journal:=erp.post_journal('SKU_MOVING_AVERAGE_REVERSAL',p_group,(statement_timestamp()at time zone 'Asia/Jakarta')::date,
  'Pembalikan koreksi nilai Ganti Merek rata-rata SKU/gudang',v_lines);end if;
 insert into cp7_sku_conversion.valuation_postings_v2 values(p_group,'REVERSE',-p.native_value,-p.transfer_value,v_delta,v_journal,statement_timestamp());
 insert into cp7_sku_conversion.component_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,root_lot_id,units_delta,physical_at,economic_date,supersedes_event_id)
 select gen_random_uuid(),group_id,source_type,source_id,line_no,'REVERSE',side,product_id,location_id,quality_grade,root_lot_id,-units_delta,
  statement_timestamp(),(statement_timestamp()at time zone 'Asia/Jakarta')::date,id
 from cp7_sku_conversion.component_events_v2 where group_id=p_group and phase='POST'order by side,line_no;
 if exists(select 1 from cp7_sku_conversion.component_events_v2 where group_id=p_group
  group by side,root_lot_id having abs(sum(units_delta))>0.000000000001)then
  raise exception 'CP7_SKU_MOVAVG_COMPONENT_REVERSE_NOT_EXACT';end if;
 insert into cp7_sku_conversion.valuation_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,qty_delta,effective_value_delta,legacy_value_delta,adjustment_delta,physical_at,economic_date)
 values(gen_random_uuid(),p_group,'SKU_CONVERSION',p_group,1,'REVERSE','SOURCE',q.source_product_id,q.location_id,q.quality_grade,q.qty_pcs,q.transfer_value,p.native_value,q.transfer_value-p.native_value,statement_timestamp(),(statement_timestamp()at time zone 'Asia/Jakarta')::date),
       (gen_random_uuid(),p_group,'SKU_CONVERSION',p_group,1,'REVERSE','TARGET',q.target_product_id,q.location_id,q.quality_grade,-q.qty_pcs,-q.transfer_value,-p.native_value,p.native_value-q.transfer_value,statement_timestamp(),(statement_timestamp()at time zone 'Asia/Jakarta')::date);
 if abs((select coalesce(sum(effective_value_delta),0)from cp7_sku_conversion.valuation_events_v2 where group_id=p_group))>0.000001
 or abs((select coalesce(sum(adjustment_delta),0)from cp7_sku_conversion.valuation_events_v2 where group_id=p_group))>0.000001 then
  raise exception 'CP7_SKU_MOVAVG_REVERSE_NOT_CONSERVED';end if;
end $function$

cp7_sku_conversion.status_component_reve:
CREATE OR REPLACE FUNCTION cp7_sku_conversion.status_component_reverse_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare v_type text;v_id uuid;v_components boolean;v_values boolean;
begin
 if old.status is not distinct from new.status or new.status is distinct from 'REVERSED'then return new;end if;
 if tg_table_schema<>'erp'or tg_table_name not in('sales_headers','sales_returns')then raise exception 'CP7_SKU_COMPONENT_TRIGGER_SCOPE';end if;
 v_type:=case when tg_table_name='sales_headers'then'SALE'else'SALES_RETURN'end;v_id:=new.id;
 select exists(select 1 from cp7_sku_conversion.component_events_v2 where source_type=v_type and source_id=v_id and phase='POST')into v_components;
 select exists(select 1 from cp7_sku_conversion.valuation_events_v2 where source_type=v_type and source_id=v_id and phase='POST')into v_values;
 if not v_components and not v_values then return new;end if;
 if exists(select 1 from cp7_sku_conversion.component_events_v2 where source_type=v_type and source_id=v_id and phase='REVERSE')
 or exists(select 1 from cp7_sku_conversion.valuation_events_v2 where source_type=v_type and source_id=v_id and phase='REVERSE')then
  raise exception 'CP7_SKU_COMPONENT_ALREADY_REVERSED';end if;
 if v_components then
  insert into cp7_sku_conversion.component_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,root_lot_id,units_delta,physical_at,economic_date,supersedes_event_id)
  select gen_random_uuid(),null,source_type,source_id,line_no,'REVERSE',side,product_id,location_id,quality_grade,root_lot_id,-units_delta,
   statement_timestamp(),(statement_timestamp()at time zone 'Asia/Jakarta')::date,id
  from cp7_sku_conversion.component_events_v2 where source_type=v_type and source_id=v_id and phase='POST'order by line_no;
 end if;
 if v_values then
  insert into cp7_sku_conversion.valuation_events_v2(id,group_id,source_type,source_id,line_no,phase,side,product_id,location_id,quality_grade,qty_delta,effective_value_delta,legacy_value_delta,adjustment_delta,physical_at,economic_date,supersedes_event_id)
  select gen_random_uuid(),null,source_type,source_id,line_no,'REVERSE',side,product_id,location_id,quality_grade,-qty_delta,-effective_value_delta,-legacy_value_delta,-adjustment_delta,
   statement_timestamp(),(statement_timestamp()at time zone 'Asia/Jakarta')::date,id
  from cp7_sku_conversion.valuation_events_v2 where source_type=v_type and source_id=v_id and phase='POST'order by line_no;
 end if;
 if exists(select 1 from cp7_sku_conversion.component_events_v2 where source_type=v_type and source_id=v_id
  group by product_id,location_id,quality_grade,root_lot_id having abs(sum(units_delta))>0.000000000001)then
  raise exception 'CP7_SKU_COMPONENT_STATUS_REVERSE_NOT_EXACT';end if;
 if exists(select 1 from cp7_sku_conversion.valuation_events_v2 where source_type=v_type and source_id=v_id
  group by product_id,location_id,quality_grade having abs(sum(qty_delta))>0.000000000001 or abs(sum(effective_value_delta))>0.001
   or abs(sum(legacy_value_delta))>0.001 or abs(sum(adjustment_delta))>0.001)then
  raise exception 'CP7_SKU_VALUE_STATUS_REVERSE_NOT_EXACT';end if;
 return new;
end $function$

erp.be_reconcile_cost_document_v1(uuid,d:
CREATE OR REPLACE FUNCTION erp.be_reconcile_cost_document_v1(p_document uuid, p_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s erp.be_conversion_cost_sources_v1%rowtype;c erp.product_conversions%rowtype;l erp.fg_lots%rowtype;
 r record;v_target numeric;v_before numeric;v_delta numeric;v_journal uuid;v_own boolean;v_event uuid;
begin
 perform erp.require_internal();
 select * into s from erp.be_conversion_cost_sources_v1 where document_id=p_document;
 if s.document_id is null then return;end if;
 perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
 select * into c from erp.product_conversions where id=s.conversion_id for update;
 select * into l from erp.fg_lots where id=(select source_lot_id from erp.be_conversion_sources_v1 where conversion_id=c.id);
 if c.status<>'POSTED' then raise exception 'BE_COST_SOURCE_NOT_POSTED';end if;
 v_own:=not erp.be_in_context_v1();
 if v_own then insert into erp.be_execution_context_v1 values(pg_backend_pid(),txid_current(),gen_random_uuid());end if;
 for r in select p.adjustment_id,p.account_id,d.status from erp.bc_adjustment_purposes_v1 p
    join erp.bc_documents_v1 d on d.id=p.document_id where p.document_id=p_document order by p.adjustment_id loop
   v_target:=case when r.status='POSTED' then -(erp._cp6_material_adjustment_revaluation_state(r.adjustment_id)->>'current_value')::numeric else 0 end;
   if (s.kind='USAGE' and v_target<0) or (s.kind='RECOVERY' and v_target>0) then raise exception 'BE_COST_DIRECTION';end if;
   select coalesce(sum(target_amount-previous_amount),0) into v_before from erp.be_conversion_cost_events_v1 where adjustment_id=r.adjustment_id;
   v_delta:=v_target-v_before;
   if v_delta<>0 then
     v_event:=gen_random_uuid();
     v_journal:=erp.post_journal('BE_CONVERSION_SOURCED_COST',v_event,p_date,'Biaya/pemulihan konversi dari dokumen '||p_document::text,
       jsonb_build_array(jsonb_build_object('mapping_key',case when l.po_id is null then 'FG_INVENTORY' else 'WIP' end,
         'po_id',l.po_id,'product_id',case when l.po_id is null then c.to_product_id end,'debit',greatest(v_delta,0),'credit',greatest(-v_delta,0)),
         jsonb_build_object('account_id',r.account_id,'debit',greatest(-v_delta,0),'credit',greatest(v_delta,0))));
     insert into erp.be_conversion_cost_events_v1(id,document_id,adjustment_id,previous_amount,target_amount,journal_id,economic_date,created_by)
     values(v_event,p_document,r.adjustment_id,v_before,v_target,v_journal,p_date,erp.current_app_user_id());
   end if;
 end loop;
 if l.po_id is null then
   perform erp.be_nonpo_sync_all_v1(p_date,'BE_COST_SOURCE',p_document,'Biaya/pemulihan konversi non-PO');
 else
   perform erp.propagate_conversion_hpp_for_po(l.po_id);
   perform erp.sync_po_hpp_to_gl(l.po_id,p_date);
   perform erp.assert_po_hpp_target_book_v2620e(l.po_id);
 end if;
 if v_own then delete from erp.be_execution_context_v1 where backend_pid=pg_backend_pid() and transaction_id=txid_current();end if;
end;$function$

erp.post_opening_hpp_correction(uuid,num:
CREATE OR REPLACE FUNCTION erp.post_opening_hpp_correction(p_lot_id uuid, p_new_hpp numeric, p_reason text, p_effective_date date DEFAULT ((statement_timestamp() AT TIME ZONE 'Asia/Jakarta'::text))::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare l erp.fg_lots%rowtype;v_old_id uuid;v_old_hpp numeric(20,6);v_ver integer;v_new_id uuid;v_corr uuid;v_no text;v_scope record;
begin
  perform erp.require_owner_admin();
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  if nullif(trim(p_reason),'') is null then raise exception 'Alasan koreksi HPP opening wajib diisi'; end if;
  if p_new_hpp is null or p_new_hpp<0 then raise exception 'HPP opening hasil koreksi tidak boleh negatif'; end if;
  select * into l from erp.fg_lots where id=p_lot_id for update;
  if l.id is null or l.lot_origin<>'OPENING' then raise exception 'Koreksi HPP opening hanya untuk lot saldo awal'; end if;
  if exists(select 1 from erp.product_conversion_allocations pca join erp.product_conversions pc on pc.id=pca.conversion_id where pca.source_lot_id=l.id and pc.status='POSTED') then
    raise exception 'Lot opening sudah pernah dipakai conversion/rebrand. Reverse/correct conversion tersebut dulu sebelum mengubah HPP opening.';
  end if;
  -- Prove every affected source/book scope before changing the root HPP.
  -- An equal aggregate must never hide pre-existing opposite discrepancies.
  for v_scope in
    select l.product_id product_id
    union select e.product_id from cp7_sku_conversion.component_events_v2 e
      where e.root_lot_id=l.id and e.source_type='SKU_CONVERSION'
    order by product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(v_scope.product_id);
  end loop;
  select hpp_version_id,hpp_per_pcs into v_old_id,v_old_hpp from erp.v_current_hpp where lot_id=l.id;
  if v_old_id is null then raise exception 'Current HPP lot opening tidak ditemukan'; end if;
  if abs(v_old_hpp-p_new_hpp)<=0.000001 then raise exception 'HPP baru sama dengan HPP current (%)',v_old_hpp; end if;
  select coalesce(max(version_no),0)+1 into v_ver from erp.hpp_versions where lot_id=l.id;
  update erp.hpp_versions set is_current=false where lot_id=l.id and is_current=true;
  insert into erp.hpp_versions(lot_id,version_no,cost_state,qty_basis_pcs,total_cost,is_current,supersedes_id,calculation_reason,created_by)
  values(l.id,v_ver,'ADJUSTED',l.initial_qty_pcs,l.initial_qty_pcs*p_new_hpp,true,v_old_id,'Controlled opening HPP correction: '||p_reason,erp.current_app_user_id()) returning id into v_new_id;
  v_no:='OHPP-'||to_char((clock_timestamp() AT TIME ZONE 'Asia/Jakarta'),'YYYYMMDDHH24MISSMS')||'-'||substr(gen_random_uuid()::text,1,6);
  insert into erp.opening_hpp_corrections(correction_number,lot_id,previous_hpp_snapshot,corrected_hpp,effective_date,reason,hpp_version_id,created_by)
  values(v_no,l.id,v_old_hpp,p_new_hpp,p_effective_date,p_reason,v_new_id,erp.current_app_user_id()) returning id into v_corr;
  perform erp.sync_opening_lot_hpp_to_gl(l.id,p_effective_date);
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('fg_lots',l.id,'UPDATE',jsonb_build_object('correction_id',v_corr,'previous_hpp',v_old_hpp,'corrected_hpp',p_new_hpp),erp.current_app_user_id(),p_reason);
  return v_corr;
end;$function$

erp.post_sale(uuid):
CREATE OR REPLACE FUNCTION erp.post_sale(p_sale_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  h erp.sales_headers%rowtype;
  r record;
  v_sales numeric(24,6):=0;
  v_item_qty bigint;
  v_reserved_qty bigint;
  v_delta_cogs numeric(24,6);
  v_delta_fg numeric(24,6);
  v_delta_other numeric(24,6);
  v_target_hpp numeric(24,6);
  v_target_other numeric(24,6);
  v_book_hpp numeric(24,6);
  v_book_other numeric(24,6);
  v_lines jsonb:='[]'::jsonb;
begin
  perform erp.require_internal();
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  select * into h from erp.sales_headers where id=p_sale_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Sale must be DRAFT'; end if;
  if h.source_location_id is null then raise exception 'Sale source FG location is required'; end if;
  if not exists(select 1 from erp.sales_items where sale_id=p_sale_id) then raise exception 'Sale has no items'; end if;

  select coalesce(sum(qty_pcs),0),coalesce(sum(line_total),0)
  into v_item_qty,v_sales from erp.sales_items where sale_id=h.id;
  select coalesce(sum(abs(m.qty_signed)),0) into v_reserved_qty
  from erp.fg_stock_movements m
  join erp.sales_items i on i.id=m.source_id
  where i.sale_id=h.id and m.source_type='SALE_ITEM' and m.movement_type='SALE_RESERVE'
    and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=m.id);

  if v_reserved_qty=0 then v_reserved_qty:=erp._reserve_sale_draft(h.id); end if;
  if v_reserved_qty<>v_item_qty then
    raise exception 'Sale Draft reservation mismatch. Items %, active reservation %',v_item_qty,v_reserved_qty;
  end if;
  if exists(
    select 1 from erp.sales_items i
    left join(select sale_item_id,sum(qty_pcs)::bigint qty_pcs
      from erp.sale_stock_allocations group by sale_item_id) a on a.sale_item_id=i.id
    where i.sale_id=h.id and coalesce(a.qty_pcs,0)<>i.qty_pcs
  ) then raise exception 'Sale allocation does not match Draft line quantity'; end if;

  if (with active as (
  select m.* from erp.fg_stock_movements m
  where exists(select 1 from erp.sales_items scope_item where scope_item.id=m.source_id and scope_item.sale_id=h.id) and m.source_type='SALE_ITEM' and m.movement_type in('SALE_RESERVE','SALE')
    and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=m.id)
), allocations as (
  select a.sale_item_id,a.lot_id,a.location_id,sum(a.qty_pcs)::bigint qty
  from erp.sale_stock_allocations a where exists(select 1 from erp.sales_items scope_item where scope_item.id=a.sale_item_id and scope_item.sale_id=h.id) group by a.sale_item_id,a.lot_id,a.location_id
), movements as (
  select m.source_id sale_item_id,m.lot_id,m.location_id,sum(-m.qty_signed)::bigint qty
  from active m group by m.source_id,m.lot_id,m.location_id
)
select count(*)::bigint from (
  select m.id,sh_lineage.id sale_id from active m
  left join erp.sales_items i on i.id=m.source_id
  left join erp.sales_headers sh_lineage on sh_lineage.id=i.sale_id
  left join erp.fg_lots l on l.id=m.lot_id
  where sh_lineage.status is null or sh_lineage.status not in('DRAFT','POSTED','PARTIAL_PAID','PAID')
    or m.movement_type is distinct from case when sh_lineage.status='DRAFT' then 'SALE_RESERVE' else 'SALE' end
    or m.product_id is distinct from i.product_id or l.product_id is distinct from i.product_id
    or m.location_id is distinct from sh_lineage.source_location_id
    or m.customer_id is distinct from sh_lineage.customer_id or m.physical_at is distinct from sh_lineage.sale_date
    or m.quality_grade is distinct from 'GRADE_A' or m.qty_signed>=0
  union all
  select a.id,sh_lineage.id from erp.sale_stock_allocations a
  left join erp.sales_items i on i.id=a.sale_item_id
  left join erp.sales_headers sh_lineage on sh_lineage.id=i.sale_id
  left join erp.fg_lots l on l.id=a.lot_id
  where sh_lineage.status is null or sh_lineage.status not in('DRAFT','POSTED','PARTIAL_PAID','PAID','REVERSED')
    or l.product_id is distinct from i.product_id
    or a.location_id is distinct from sh_lineage.source_location_id or a.qty_pcs<=0
  union all
  select i.id,sh_lineage.id from allocations a full join movements m using(sale_item_id,lot_id,location_id)
  join erp.sales_items i on i.id=coalesce(a.sale_item_id,m.sale_item_id)
  join erp.sales_headers sh_lineage on sh_lineage.id=i.sale_id
  where sh_lineage.status in('DRAFT','POSTED','PARTIAL_PAID','PAID') and a.qty is distinct from m.qty
  union all
  select i.id,sh_lineage.id from erp.sales_items i join erp.sales_headers sh_lineage on sh_lineage.id=i.sale_id
  where (sh_lineage.status in('POSTED','PARTIAL_PAID','PAID') or
    (sh_lineage.status='DRAFT' and (exists(select 1 from erp.sale_stock_allocations a
       join erp.sales_items sibling on sibling.id=a.sale_item_id where sibling.sale_id=sh_lineage.id)
      or exists(select 1 from active m join erp.sales_items sibling on sibling.id=m.source_id where sibling.sale_id=sh_lineage.id))))
    and (i.qty_pcs is distinct from (select coalesce(sum(a.qty_pcs),0) from erp.sale_stock_allocations a where a.sale_item_id=i.id)
      or i.qty_pcs is distinct from (select coalesce(sum(-m.qty_signed),0) from active m where m.source_id=i.id))
  union all
  select sh_lineage.id,sh_lineage.id from erp.sales_headers sh_lineage where sh_lineage.status in('POSTED','PARTIAL_PAID','PAID')
    and not exists(select 1 from erp.sales_items i where i.sale_id=sh_lineage.id)
) broken where broken.sale_id=h.id)<>0 then
    raise exception 'AG_SALE_RESERVATION_LINEAGE_MISMATCH';
  end if;

  perform cp7_sku_conversion.prepare_sale_values_v2(h.id);

  for r in
    select distinct v.product_id
    from cp7_sku_conversion.sale_allocation_attributions_v2 a
    join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
    where v.sale_id=h.id and a.po_id is null
    order by v.product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(r.product_id);
  end loop;

  update erp.sale_stock_allocations a
  set unit_hpp_snapshot=cp7_sku_conversion.sale_allocation_unit_v2(a.id,a.lot_id)
  from erp.sales_items i
  where i.id=a.sale_item_id and i.sale_id=h.id;

  update erp.fg_stock_movements m
  set unit_hpp_snapshot=a.unit_hpp_snapshot
  from erp.sales_items i
  join erp.sale_stock_allocations a on a.sale_item_id=i.id
  where i.id=m.source_id and i.sale_id=h.id
    and a.lot_id=m.lot_id
    and m.source_type='SALE_ITEM' and m.movement_type='SALE_RESERVE'
    and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=m.id);

  update erp.fg_stock_movements m
  set movement_type='SALE',notes='Sale posted · quantity reserved in Draft; HPP frozen at POST'
  from erp.sales_items i
  where i.id=m.source_id and i.sale_id=h.id
    and m.source_type='SALE_ITEM' and m.movement_type='SALE_RESERVE'
    and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=m.id);

  -- BD (LAU-04, LAU-DEC04): goods whose laundry price is still unknown are sold only if the owner allows it.
  perform erp.bd_assert_sale_laundry_known_v1(h.id);
  update erp.sales_headers set status='POSTED' where id=h.id;
  if abs(v_sales)>0.005 then
    v_lines:=v_lines||jsonb_build_array(
      jsonb_build_object('mapping_key','AR_CUSTOMER','debit',round(v_sales,2),'credit',0,'customer_id',h.customer_id),
      jsonb_build_object('mapping_key','SALES_REVENUE','debit',0,'credit',round(v_sales,2),'customer_id',h.customer_id));
  end if;

  -- One cumulative target per product, composed from per-lot lifecycle truth.
  for r in
    select distinct v.product_id
    from cp7_sku_conversion.sale_allocation_attributions_v2 a
    join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
    where v.sale_id=h.id and a.po_id is null
    order by v.product_id
  loop
    select round(t.fg_value-b.fg_value,2),
      round(t.cogs_value-b.cogs_value,2),
      round(t.other_out_value-b.other_out_value,2)
    into v_delta_fg,v_delta_cogs,v_delta_other
    from erp.compute_non_po_product_hpp_targets_v2620f(r.product_id) t
    cross join lateral erp.compute_non_po_product_hpp_book_v2620f(r.product_id) b;
    if abs(v_delta_fg+v_delta_cogs+v_delta_other)>0.005 then
      raise exception 'Sale non-PO HPP delta does not conserve source value for product %: fg %, cogs %, other %',
        r.product_id,v_delta_fg,v_delta_cogs,v_delta_other;
    end if;
    if abs(v_delta_fg)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_fg>0
        then jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_delta_fg,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,
          'credit',abs(v_delta_fg),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
    if abs(v_delta_cogs)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_cogs>0
        then jsonb_build_object('mapping_key','COGS','debit',v_delta_cogs,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','COGS','debit',0,
          'credit',abs(v_delta_cogs),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
    if abs(v_delta_other)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_other>0
        then jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',v_delta_other,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,
          'credit',abs(v_delta_other),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
  end loop;

  for r in
    select distinct a.po_id
    from cp7_sku_conversion.sale_allocation_attributions_v2 a
    join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
    where v.sale_id=h.id and a.po_id is not null
    order by a.po_id
  loop
    perform erp.refresh_po_hpp_gl_baseline(r.po_id);
    select
      round(coalesce(t.cogs_value,0),2)-s.cogs_value,
      round(coalesce(t.fg_value,0),2)-s.fg_value,
      (round(coalesce(t.hpp_total_cost,0),2)-round(coalesce(t.fg_value,0),2)
        -round(coalesce(t.cogs_value,0),2))-s.other_out_value,
      round(coalesce(t.hpp_total_cost,0),2),
      round(coalesce(t.hpp_total_cost,0),2)-round(coalesce(t.fg_value,0),2)-round(coalesce(t.cogs_value,0),2),
      s.hpp_total_cost,s.other_out_value
    into v_delta_cogs,v_delta_fg,v_delta_other,
      v_target_hpp,v_target_other,v_book_hpp,v_book_other
    from erp.po_hpp_gl_state s
    cross join lateral erp.compute_po_hpp_gl_targets_v2620d(r.po_id) t
    where s.po_id=r.po_id for update of s;
    if v_delta_cogs<-0.005 or v_delta_fg>0.005
       or abs(v_delta_cogs+v_delta_fg+v_delta_other)>0.005
       or v_target_hpp is distinct from v_book_hpp then
      raise exception 'Sale cumulative HPP target does not conserve PO value %. dc %, df %, do %, target/book hpp %/%',
        r.po_id,v_delta_cogs,v_delta_fg,v_delta_other,v_target_hpp,v_book_hpp;
    end if;
    if abs(v_delta_cogs)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_cogs>0 then
        jsonb_build_object('mapping_key','COGS','debit',v_delta_cogs,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','COGS','debit',0,'credit',abs(v_delta_cogs),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
    if abs(v_delta_fg)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_fg>0 then
        jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_delta_fg,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',abs(v_delta_fg),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
    if abs(v_delta_other)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_other>0 then
        jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',v_delta_other,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,'credit',abs(v_delta_other),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
  end loop;
  if jsonb_array_length(v_lines)>=2 then
    perform erp.post_journal('SALE',h.id,(h.sale_date AT TIME ZONE 'Asia/Jakarta')::date,
      'Sales to customer/toko · cumulative exact HPP target',v_lines);
  end if;

  for r in
    select distinct v.product_id
    from cp7_sku_conversion.sale_allocation_attributions_v2 a
    join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
    where v.sale_id=h.id and a.po_id is null
    order by v.product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(r.product_id);
  end loop;

  for r in
    select distinct a.po_id
    from cp7_sku_conversion.sale_allocation_attributions_v2 a
    join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
    where v.sale_id=h.id and a.po_id is not null
    order by a.po_id
  loop
    perform erp.refresh_po_hpp_gl_baseline(r.po_id);
    perform erp.assert_po_hpp_target_book_v2620e(r.po_id);
  end loop;
end
$function$

erp.post_sales_return(uuid):
CREATE OR REPLACE FUNCTION erp.post_sales_return(p_return_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  h erp.sales_returns%rowtype;
  s erp.sales_headers%rowtype;
  r record;
  v_refund numeric(24,6):=0;
  v_sold_qty integer;
  v_prior_returned integer;
  v_current_return integer;
  v_product_sale_value numeric(24,6);
  v_prior_product_refund numeric(24,6);
  v_current_product_refund numeric(24,6);
  v_original_hpp numeric(18,6);
  v_unit_hpp numeric(18,6);
  v_net_total numeric(20,2);
  v_paid numeric(20,2);
  v_delta_cogs numeric(24,6);
  v_delta_fg numeric(24,6);
  v_delta_other numeric(24,6);
  v_target_hpp numeric(24,6);
  v_target_other numeric(24,6);
  v_book_hpp numeric(24,6);
  v_book_other numeric(24,6);
  v_lines jsonb:='[]'::jsonb;
begin
  perform erp.require_internal();
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  perform erp.require_internal();
  perform cp7_credit.native_return_enter(p_return_id);
  perform erp.require_internal();
  select * into h from erp.sales_returns where id=p_return_id for update;
  if h.id is null or h.status<>'DRAFT' then raise exception 'Sales return must be DRAFT'; end if;
  if h.sale_id is null then raise exception 'Native sales return must reference the original sale'; end if;
  select * into s from erp.sales_headers where id=h.sale_id for update;
  if s.id is null or s.status not in('POSTED','PARTIAL_PAID','PAID') then raise exception 'Original sale must be active/posted'; end if;
  if s.customer_id is distinct from h.customer_id then raise exception 'Sales return customer does not match original sale customer'; end if;
  if not exists(select 1 from erp.sales_return_items where return_id=h.id) then raise exception 'Sales return has no lines'; end if;

  perform cp7_sku_conversion.prepare_return_values_v2(h.id);

  for r in
    select distinct v.product_id
    from cp7_sku_conversion.sales_return_attributions_v2 a
    join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
    where v.return_id=h.id and a.po_id is null
    union select fl.product_id from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is null
      and not exists(select 1 from cp7_sku_conversion.sales_return_values_v2 v where v.sales_return_item_id=i.id)
    order by product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(r.product_id);
  end loop;

  for r in
    select * from erp.sales_return_items where return_id=h.id
    order by product_id,location_id,quality_grade,lot_id,id
  loop
    if r.lot_id is null then raise exception 'Sales return line requires original FG lot'; end if;
    if not exists(select 1 from erp.fg_lots fl where fl.id=r.lot_id and fl.product_id=r.product_id) then raise exception 'Sales return lot does not belong to selected product'; end if;

    insert into erp.fg_inventory_balances(product_id,location_id,quality_grade,cached_qty_pcs)
    values(r.product_id,r.location_id,r.quality_grade,0)
    on conflict(product_id,location_id,quality_grade) do nothing;
    perform 1 from erp.fg_inventory_balances
    where product_id=r.product_id and location_id=r.location_id and quality_grade=r.quality_grade
    for update;
    perform 1 from erp.fg_lots where id=r.lot_id for update;

    -- Eligibility belongs to the selected allocation. Receipt destination is
    -- independently validated and may be another active FG warehouse.
    select a.qty_pcs,a.unit_hpp_snapshot into v_sold_qty,v_original_hpp
    from erp.sale_stock_allocations a join erp.sales_items si on si.id=a.sale_item_id
    where a.id=r.sale_stock_allocation_id and si.sale_id=h.sale_id
      and si.product_id=r.product_id and a.lot_id=r.lot_id;
    if v_sold_qty is null or v_sold_qty<=0 or v_original_hpp is null then
      raise exception 'AH_RETURN_ALLOCATION_SOURCE_MISMATCH';
    end if;

    v_unit_hpp:=cp7_sku_conversion.return_item_unit_v2(r.id,r.lot_id,v_original_hpp);
    select coalesce(sum(sri.qty_pcs),0)::integer into v_prior_returned
    from erp.sales_return_items sri join erp.sales_returns sr on sr.id=sri.return_id
    where sr.sale_id=h.sale_id and sr.id<>h.id and sr.status='POSTED'
      and sri.sale_stock_allocation_id=r.sale_stock_allocation_id;
    select coalesce(sum(sri.qty_pcs),0)::integer into v_current_return
    from erp.sales_return_items sri
    where sri.return_id=h.id and sri.sale_stock_allocation_id=r.sale_stock_allocation_id;
    if v_prior_returned+v_current_return>v_sold_qty then
      raise exception 'AH_RETURN_EXCEEDS_ORIGINAL_ALLOCATION: Sales return exceeds quantity originally sold for this allocation. Sold %, prior returned %, current return %',v_sold_qty,v_prior_returned,v_current_return;
    end if;

    select coalesce(sum(si.line_total),0) into v_product_sale_value
    from erp.sales_items si where si.sale_id=h.sale_id and si.product_id=r.product_id;
    select coalesce(sum(sri.refund_amount),0) into v_prior_product_refund
    from erp.sales_return_items sri join erp.sales_returns sr on sr.id=sri.return_id
    where sr.sale_id=h.sale_id and sr.id<>h.id and sr.status='POSTED' and sri.product_id=r.product_id;
    select coalesce(sum(sri.refund_amount),0) into v_current_product_refund
    from erp.sales_return_items sri where sri.return_id=h.id and sri.product_id=r.product_id;
    if v_prior_product_refund+v_current_product_refund>v_product_sale_value then
      raise exception 'Refund exceeds original net sale value for product. Sold value %, prior refund %, current refund %',v_product_sale_value,v_prior_product_refund,v_current_product_refund;
    end if;

    update erp.sales_return_items set unit_hpp_snapshot=v_unit_hpp where id=r.id;
    perform erp.post_fg_movement(r.product_id,r.lot_id,r.location_id,r.quality_grade,
      'SALE_RETURN',r.qty_pcs,v_unit_hpp,h.customer_id,'SALES_RETURN_ITEM',r.id,
      h.physical_at,'Customer sales return',false);
    v_refund:=v_refund+r.refund_amount;
  end loop;

  select greatest(erp.sale_net_total(h.sale_id)-v_refund,0)::numeric(20,2) into v_net_total;
  select coalesce(sum(sp.amount),0)::numeric(20,2) into v_paid
  from erp.sales_payments sp where sp.sale_id=h.sale_id and sp.status='POSTED';
  v_paid:=cp7_credit.native_return_guard(h.id,v_refund,v_net_total,v_paid);
  if v_paid>v_net_total then
    raise exception 'Retur ini membuat pembayaran customer melebihi nilai penjualan tersisa. Nilai setelah retur %, sudah dibayar %. Reverse/koreksi pembayaran customer dulu agar kelebihan bayar tidak hilang dari pembukuan.',v_net_total,v_paid;
  end if;

  update erp.sales_returns set status='POSTED' where id=h.id;
  if abs(v_refund)>0.005 then
    v_lines:=v_lines||jsonb_build_array(
      jsonb_build_object('mapping_key','SALES_REVENUE','debit',round(v_refund,2),'credit',0,'customer_id',h.customer_id),
      jsonb_build_object('mapping_key','AR_CUSTOMER','debit',0,'credit',round(v_refund,2),'customer_id',h.customer_id));
  end if;

  for r in
    select distinct v.product_id
    from cp7_sku_conversion.sales_return_attributions_v2 a
    join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
    where v.return_id=h.id and a.po_id is null
    union select fl.product_id from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is null
      and not exists(select 1 from cp7_sku_conversion.sales_return_values_v2 v where v.sales_return_item_id=i.id)
    order by product_id
  loop
    select round(t.fg_value-b.fg_value,2),
      round(t.cogs_value-b.cogs_value,2),
      round(t.other_out_value-b.other_out_value,2)
    into v_delta_fg,v_delta_cogs,v_delta_other
    from erp.compute_non_po_product_hpp_targets_v2620f(r.product_id) t
    cross join lateral erp.compute_non_po_product_hpp_book_v2620f(r.product_id) b;
    if abs(v_delta_fg+v_delta_cogs+v_delta_other)>0.005 then
      raise exception 'Return non-PO HPP delta does not conserve source value for product %: fg %, cogs %, other %',
        r.product_id,v_delta_fg,v_delta_cogs,v_delta_other;
    end if;
    if abs(v_delta_fg)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_fg>0
        then jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_delta_fg,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,
          'credit',abs(v_delta_fg),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
    if abs(v_delta_cogs)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_cogs>0
        then jsonb_build_object('mapping_key','COGS','debit',v_delta_cogs,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','COGS','debit',0,
          'credit',abs(v_delta_cogs),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
    if abs(v_delta_other)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_other>0
        then jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',v_delta_other,
          'credit',0,'customer_id',h.customer_id,'product_id',r.product_id)
        else jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,
          'credit',abs(v_delta_other),'customer_id',h.customer_id,
          'product_id',r.product_id) end);
    end if;
  end loop;

  for r in
    select distinct a.po_id
    from cp7_sku_conversion.sales_return_attributions_v2 a
    join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
    where v.return_id=h.id and a.po_id is not null
    union select fl.po_id from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is not null
      and not exists(select 1 from cp7_sku_conversion.sales_return_values_v2 v where v.sales_return_item_id=i.id)
    order by po_id
  loop
    perform erp.refresh_po_hpp_gl_baseline(r.po_id);
    select
      round(coalesce(t.cogs_value,0),2)-st.cogs_value,
      round(coalesce(t.fg_value,0),2)-st.fg_value,
      (round(coalesce(t.hpp_total_cost,0),2)-round(coalesce(t.fg_value,0),2)
        -round(coalesce(t.cogs_value,0),2))-st.other_out_value,
      round(coalesce(t.hpp_total_cost,0),2),
      round(coalesce(t.hpp_total_cost,0),2)-round(coalesce(t.fg_value,0),2)-round(coalesce(t.cogs_value,0),2),
      st.hpp_total_cost,st.other_out_value
    into v_delta_cogs,v_delta_fg,v_delta_other,
      v_target_hpp,v_target_other,v_book_hpp,v_book_other
    from erp.po_hpp_gl_state st
    cross join lateral erp.compute_po_hpp_gl_targets_v2620d(r.po_id) t
    where st.po_id=r.po_id for update of st;
    if v_delta_cogs>0.005 or v_delta_fg<-0.005
       or abs(v_delta_cogs+v_delta_fg+v_delta_other)>0.005
       or v_target_hpp is distinct from v_book_hpp then
      raise exception 'Sales-return cumulative HPP target does not conserve PO value %. dc %, df %, do %, target/book hpp %/%',
        r.po_id,v_delta_cogs,v_delta_fg,v_delta_other,v_target_hpp,v_book_hpp;
    end if;
    if abs(v_delta_cogs)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_cogs>0 then
        jsonb_build_object('mapping_key','COGS','debit',v_delta_cogs,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','COGS','debit',0,'credit',abs(v_delta_cogs),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
    if abs(v_delta_fg)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_fg>0 then
        jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_delta_fg,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,'credit',abs(v_delta_fg),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
    if abs(v_delta_other)>0.005 then
      v_lines:=v_lines||jsonb_build_array(case when v_delta_other>0 then
        jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',v_delta_other,'credit',0,
          'customer_id',h.customer_id,'po_id',r.po_id)
        else jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,'credit',abs(v_delta_other),
          'customer_id',h.customer_id,'po_id',r.po_id) end);
    end if;
  end loop;
  if jsonb_array_length(v_lines)>=2 then
    perform cp7_credit.post_return_journal('SALES_RETURN',h.id,(h.physical_at AT TIME ZONE 'Asia/Jakarta')::date,
      'Sales return from customer · cumulative exact HPP target',v_lines);
  end if;
  perform cp7_credit.flush_opening_return_hpp_v1(h.id);
  v_paid:=cp7_credit.native_return_complete(h.id,v_refund,v_net_total);
  perform erp.require_internal();

  for r in
    select distinct v.product_id
    from cp7_sku_conversion.sales_return_attributions_v2 a
    join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
    where v.return_id=h.id and a.po_id is null
    union select fl.product_id from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is null
      and not exists(select 1 from cp7_sku_conversion.sales_return_values_v2 v where v.sales_return_item_id=i.id)
    order by product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(r.product_id);
  end loop;

  update erp.sales_headers
  set status=case when v_paid=v_net_total then 'PAID' when v_paid>0 and v_paid<v_net_total then 'PARTIAL_PAID' else 'POSTED' end
  where id=h.sale_id;
  for r in
    select distinct a.po_id
    from cp7_sku_conversion.sales_return_attributions_v2 a
    join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
    where v.return_id=h.id and a.po_id is not null
    union select fl.po_id from erp.sales_return_items i join erp.fg_lots fl on fl.id=i.lot_id
    where i.return_id=h.id and fl.po_id is not null
      and not exists(select 1 from cp7_sku_conversion.sales_return_values_v2 v where v.sales_return_item_id=i.id)
    order by po_id
  loop
    perform erp.refresh_po_hpp_gl_baseline(r.po_id);
    perform erp.assert_po_hpp_target_book_v2620e(r.po_id);
  end loop;
  perform cp7_credit.native_return_leave(h.id);
  perform erp.require_internal();
end
$function$

erp.sync_non_po_product_hpp_to_gl_v2620f:
CREATE OR REPLACE FUNCTION erp.sync_non_po_product_hpp_to_gl_v2620f(p_product_id uuid, p_effective_date date, p_trigger_source_type text, p_trigger_source_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  t record;
  b record;
  v_df numeric(20,2);
  v_dc numeric(20,2);
  v_do numeric(20,2);
  v_event uuid:=gen_random_uuid();
  v_journal uuid;
  v_lines jsonb:='[]'::jsonb;
  v_scope record;v_guard text:=coalesce(current_setting('cp7.sku_nonpo_sync_expanding',true),'');
begin
  perform erp.require_internal();
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  if v_guard<>'1'then
   perform set_config('cp7.sku_nonpo_sync_expanding','1',true);
   for v_scope in select distinct e.product_id from cp7_sku_conversion.component_events_v2 e
    join erp.fg_lots root on root.id=e.root_lot_id and root.po_id is null and root.product_id=p_product_id
    where e.product_id<>p_product_id order by e.product_id loop
    perform erp.sync_non_po_product_hpp_to_gl_v2620f(v_scope.product_id,p_effective_date,p_trigger_source_type,p_trigger_source_id,p_reason);
   end loop;
   for v_scope in
    with related_sales as(select distinct v.sale_id from cp7_sku_conversion.sale_allocation_components_v2 c
      join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
      join erp.fg_lots root on root.id=c.root_lot_id and root.po_id is null and root.product_id=p_product_id),
    related_returns as(select distinct v.return_id from cp7_sku_conversion.sales_return_components_v2 c
      join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
      join erp.fg_lots root on root.id=c.root_lot_id and root.po_id is null and root.product_id=p_product_id),
    scopes as(
      select c.po_id from cp7_sku_conversion.sale_allocation_components_v2 c join cp7_sku_conversion.sale_allocation_values_v2 v using(sale_stock_allocation_id)
       where v.sale_id in(select sale_id from related_sales)
      union select c.po_id from cp7_sku_conversion.sales_return_components_v2 c join cp7_sku_conversion.sales_return_values_v2 v using(sales_return_item_id)
       where v.return_id in(select return_id from related_returns)
      union select c2.po_id from cp7_sku_conversion.valuation_contributors_v2 c1
       join erp.fg_lots root on root.id=c1.root_lot_id and root.po_id is null and root.product_id=p_product_id
       join cp7_sku_conversion.valuation_contributors_v2 c2 using(group_id))
    select distinct po_id from scopes where po_id is not null order by po_id
   loop
    perform erp.sync_po_hpp_to_gl(v_scope.po_id,p_effective_date);
   end loop;
   perform set_config('cp7.sku_nonpo_sync_expanding',v_guard,true);
  end if;
  if nullif(btrim(p_trigger_source_type),'') is null
     or nullif(btrim(p_reason),'') is null then
    raise exception 'Non-PO HPP synchronization requires source and reason';
  end if;
  if not erp.be_nonpo_in_sync_v1() and exists(select 1 from erp.be_conversion_sources_v1 be_source
      join erp.fg_lots be_lot on be_lot.id=be_source.source_lot_id where be_lot.po_id is null) then
    perform erp.be_nonpo_sync_all_v1(p_effective_date,p_trigger_source_type,p_trigger_source_id,p_reason);return;
  end if;
  if exists(
    select 1
    from erp.product_conversion_allocations a
    join erp.product_conversions c on c.id=a.conversion_id and c.status='POSTED'
    join erp.fg_lots s on s.id=a.source_lot_id
    join erp.fg_lots d on d.id=a.destination_lot_id
    where(s.po_id is null or d.po_id is null) and not erp.be_nonpo_admitted_v1(c.id)
      and(s.product_id=p_product_id or d.product_id=p_product_id)
  ) then
    raise exception 'NON_PO_CONVERSION_REQUIRES_SOURCED_HPP_WORKFLOW';
  end if;

  select * into t
  from erp.compute_non_po_product_hpp_targets_v2620f(p_product_id);
  select * into b
  from erp.compute_non_po_product_hpp_book_v2620f(p_product_id);
  if abs(t.hpp_total_cost-b.hpp_total_cost)>0.005 then
    raise exception 'NON_PO_HPP_SOURCE_VALUE_MISMATCH: product %, target total %, book total %',
      p_product_id,t.hpp_total_cost,b.hpp_total_cost;
  end if;

  v_df:=round(t.fg_value-b.fg_value,2);
  v_dc:=round(t.cogs_value-b.cogs_value,2);
  v_do:=round(t.other_out_value-b.other_out_value,2);
  if abs(v_df+v_dc+v_do)>0.005 then
    raise exception 'NON_PO_HPP_DELTA_NOT_CONSERVED: product %, fg %, cogs %, other %',
      p_product_id,v_df,v_dc,v_do;
  end if;
  if abs(v_df)<=0.005 and abs(v_dc)<=0.005 and abs(v_do)<=0.005 then
    return;
  end if;

  if abs(v_df)>0.005 then
    v_lines:=v_lines||jsonb_build_array(case when v_df>0
      then jsonb_build_object('mapping_key','FG_INVENTORY','debit',v_df,
        'credit',0,'product_id',p_product_id)
      else jsonb_build_object('mapping_key','FG_INVENTORY','debit',0,
        'credit',abs(v_df),'product_id',p_product_id) end);
  end if;
  if abs(v_dc)>0.005 then
    v_lines:=v_lines||jsonb_build_array(case when v_dc>0
      then jsonb_build_object('mapping_key','COGS','debit',v_dc,
        'credit',0,'product_id',p_product_id)
      else jsonb_build_object('mapping_key','COGS','debit',0,
        'credit',abs(v_dc),'product_id',p_product_id) end);
  end if;
  if abs(v_do)>0.005 then
    v_lines:=v_lines||jsonb_build_array(case when v_do>0
      then jsonb_build_object('mapping_key','OTHER_EXPENSE','debit',v_do,
        'credit',0,'product_id',p_product_id)
      else jsonb_build_object('mapping_key','OTHER_INCOME','debit',0,
        'credit',abs(v_do),'product_id',p_product_id) end);
  end if;

  v_journal:=erp.post_journal(
    'NON_PO_HPP_GL_SYNC_V2620F',v_event,p_effective_date,
    'Cumulative non-PO HPP redistribution · '||p_reason,v_lines
  );
  insert into erp.non_po_hpp_gl_sync_events_v2620f(
    id,product_id,trigger_source_type,trigger_source_id,effective_date,
    old_fg_value,new_fg_value,fg_delta,
    old_cogs_value,new_cogs_value,cogs_delta,
    old_other_out_value,new_other_out_value,other_delta,
    journal_entry_id,reason,created_by
  ) values(
    v_event,p_product_id,p_trigger_source_type,p_trigger_source_id,
    p_effective_date,b.fg_value,t.fg_value,v_df,
    b.cogs_value,t.cogs_value,v_dc,
    b.other_out_value,t.other_out_value,v_do,
    v_journal,p_reason,erp.current_app_user_id()
  );
  perform erp.assert_non_po_product_hpp_target_book_v2620f(p_product_id);
end
$function$

erp.sync_opening_lot_hpp_to_gl(uuid,date:
CREATE OR REPLACE FUNCTION erp.sync_opening_lot_hpp_to_gl(p_lot_id uuid, p_effective_date date DEFAULT ((statement_timestamp() AT TIME ZONE 'Asia/Jakarta'::text))::date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  l erp.fg_lots%rowtype; s erp.opening_lot_hpp_gl_state%rowtype;
  h erp.hpp_versions%rowtype; v_baseline numeric; v_source_delta numeric;
  v_expected_delta numeric; v_current_qty numeric; v_base_fg numeric;
  v_net_sold_qty numeric; v_actual_cogs numeric; v_expense numeric; v_income numeric;
  v_scope record;v_scope_delta numeric;v_lines jsonb:='[]'::jsonb;
begin
  perform erp.require_internal();
  perform pg_advisory_xact_lock(hashtextextended('FG_HPP_SALES_V2620C',0));
  select * into l from erp.fg_lots where id=p_lot_id for update;
  if l.id is null or l.lot_origin<>'OPENING' then return; end if;
  select * into h from erp.hpp_versions where lot_id=l.id and is_current;
  if h.id is null then raise exception 'Opening current HPP is missing'; end if;
  select fm.unit_hpp_snapshot into v_baseline from erp.fg_stock_movements fm
  where fm.lot_id=l.id and fm.movement_type='OPENING'
  order by fm.physical_at,fm.system_created_at,fm.id limit 1;
  if v_baseline is null then raise exception 'Opening lot % has no source movement',l.lot_number; end if;
  if exists(select 1 from erp.product_conversion_allocations a
    join erp.product_conversions c on c.id=a.conversion_id
    where a.source_lot_id=l.id and c.status='POSTED') then
    if exists(select 1 from erp.product_conversion_allocations a
      join erp.product_conversions c on c.id=a.conversion_id
      where a.source_lot_id=l.id and c.status='POSTED' and not erp.be_nonpo_admitted_v1(c.id)) then
      raise exception 'Opening HPP conversion requires a sourced descendant correction workflow';
    end if;
    perform erp.be_nonpo_prepare_transfers_v1(p_effective_date);
  end if;
  select * into s from erp.opening_lot_hpp_gl_state where lot_id=l.id for update;
  v_expected_delta:=round(h.total_cost,2)
    -round(l.initial_qty_pcs*coalesce(s.current_hpp,v_baseline),2);
  -- Root basis remains exact. Its source delta follows the economic
  -- component owners, which may include another product after conversion.
  v_source_delta:=0;
  for v_scope in
    select l.product_id product_id
    union select e.product_id from cp7_sku_conversion.component_events_v2 e
      where e.root_lot_id=l.id and e.source_type='SKU_CONVERSION'
    order by product_id
  loop
    select t.hpp_total_cost-b.hpp_total_cost into v_scope_delta
    from erp.compute_non_po_product_hpp_targets_v2620f(v_scope.product_id) t
    cross join lateral erp.compute_non_po_product_hpp_book_v2620f(v_scope.product_id) b;
    if v_scope_delta is null then raise exception 'OPENING_COMPONENT_SOURCE_UNKNOWN';end if;
    v_source_delta:=v_source_delta+v_scope_delta;
    if v_scope_delta<>0 then
      v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','FG_INVENTORY',
        'debit',greatest(v_scope_delta,0),'credit',greatest(-v_scope_delta,0),'product_id',v_scope.product_id));
    end if;
  end loop;
  if v_source_delta is distinct from v_expected_delta then
    raise exception 'OPENING_SOURCE_CHANGE_NOT_EXACT: product %, pending lot basis %, target/book source delta %',
      l.product_id,v_expected_delta,v_source_delta;
  end if;
  if v_source_delta<>0 then
    v_lines:=v_lines||jsonb_build_array(jsonb_build_object('mapping_key','OPENING_EQUITY',
      'debit',greatest(-v_source_delta,0),'credit',greatest(v_source_delta,0)));
  end if;
  if jsonb_array_length(v_lines)>0 then
    perform erp.post_journal('OPENING_HPP_SOURCE_V2620G',h.id,p_effective_date,
      'Source lot basis correction for '||l.lot_number||' / HPP version '||h.id,v_lines);
  end if;
  perform erp.sync_non_po_product_hpp_to_gl_v2620f(l.product_id,p_effective_date,
    'OPENING_HPP_LIFECYCLE_V2620G',h.id,'Exact rounded opening source and cumulative physical lifecycle');
  for v_scope in
    select l.product_id product_id
    union select e.product_id from cp7_sku_conversion.component_events_v2 e
      where e.root_lot_id=l.id and e.source_type='SKU_CONVERSION'
    order by product_id
  loop
    perform erp.assert_non_po_product_hpp_target_book_v2620f(v_scope.product_id);
  end loop;

  -- Preserve the historical raw revaluation diagnostics and trigger-activation
  -- contract. These projections are not used as monetary posting authority:
  -- actual journals and F's cumulative source/target/book checks are.
  -- DRAFT reservations reduce sellable qty, not company ownership.
  select coalesce(sum(fm.qty_signed),0),coalesce(sum(fm.qty_signed*fm.unit_hpp_snapshot),0)
    into v_current_qty,v_base_fg from erp.fg_stock_movements fm where fm.lot_id=l.id;
  select v_current_qty+coalesce(sum(abs(fm.qty_signed)),0),
    v_base_fg+coalesce(sum(abs(fm.qty_signed)*fm.unit_hpp_snapshot),0)
    into v_current_qty,v_base_fg from erp.fg_stock_movements fm
    where fm.lot_id=l.id and fm.movement_type='SALE_RESERVE'
      and not exists(select 1 from erp.fg_stock_movements rv where rv.reversal_of_id=fm.id);
  select coalesce(sum(a.qty_pcs),0),coalesce(sum(a.qty_pcs*a.unit_hpp_snapshot),0)
    into v_net_sold_qty,v_actual_cogs from erp.sale_stock_allocations a
    join erp.sales_items i on i.id=a.sale_item_id join erp.sales_headers sh on sh.id=i.sale_id
    where a.lot_id=l.id and sh.status in('POSTED','PARTIAL_PAID','PAID');
  select v_net_sold_qty-coalesce(sum(i.qty_pcs),0),v_actual_cogs-coalesce(sum(i.qty_pcs*i.unit_hpp_snapshot),0)
    into v_net_sold_qty,v_actual_cogs from erp.sales_return_items i
    join erp.sales_returns rh on rh.id=i.return_id where i.lot_id=l.id and rh.status='POSTED';
  select coalesce(sum(case when i.qty_signed<0 then -i.qty_signed*(h.hpp_per_pcs-i.unit_hpp_snapshot) else 0 end),0),
    coalesce(sum(case when i.qty_signed>0 then i.qty_signed*(h.hpp_per_pcs-i.unit_hpp_snapshot) else 0 end),0)
    into v_expense,v_income from erp.fg_adjustment_items i
    join erp.fg_adjustments a on a.id=i.adjustment_id where i.lot_id=l.id and a.status='POSTED';
  insert into erp.opening_lot_hpp_gl_state(lot_id,current_hpp,fg_revaluation,cogs_revaluation,
    expense_revaluation,income_revaluation,equity_revaluation,updated_at)
  values(l.id,h.hpp_per_pcs,v_current_qty*h.hpp_per_pcs-v_base_fg,
    v_net_sold_qty*h.hpp_per_pcs-v_actual_cogs,v_expense,v_income,
    l.initial_qty_pcs*(h.hpp_per_pcs-v_baseline),statement_timestamp())
  on conflict(lot_id) do update set current_hpp=excluded.current_hpp,
    fg_revaluation=excluded.fg_revaluation,cogs_revaluation=excluded.cogs_revaluation,
    expense_revaluation=excluded.expense_revaluation,income_revaluation=excluded.income_revaluation,
    equity_revaluation=excluded.equity_revaluation,updated_at=statement_timestamp();
end
$function$
